"""Stable dependency-aware backlog ordering for organization-mode projects."""

from __future__ import annotations

from typing import Any, Iterable


class AdaptivePlanner:
    """Orders work by priority while enforcing explicit dependencies deterministically."""

    def order_backlog(
        self,
        tasks: Iterable[Any],
        completed: Iterable[str] = (),
    ) -> list[dict[str, Any]]:
        records = [self._as_dict(task) for task in tasks]
        by_id = {str(item["id"]): item for item in records}
        if len(by_id) != len(records):
            raise ValueError("Task IDs must be unique.")
        completed_ids = set(completed)
        missing_dependencies = sorted({
            dependency
            for item in by_id.values()
            for dependency in item.get("dependencies", [])
            if dependency not in by_id and dependency not in completed_ids
        })
        if missing_dependencies:
            raise ValueError(f"Tasks have unresolved dependencies: {missing_dependencies}")
        remaining = {
            task_id: {
                dependency
                for dependency in item.get("dependencies", [])
                if dependency in by_id and dependency not in completed_ids
            }
            for task_id, item in by_id.items()
        }
        ordered: list[dict[str, Any]] = []
        ready = sorted(
            (task_id for task_id, dependencies in remaining.items() if not dependencies),
            key=lambda task_id: self._priority_key(by_id[task_id]),
        )
        while ready:
            task_id = ready.pop(0)
            ordered.append(by_id[task_id])
            for dependent in sorted(remaining):
                if task_id in remaining[dependent]:
                    remaining[dependent].remove(task_id)
                    if not remaining[dependent] and by_id[dependent] not in ordered and dependent not in ready:
                        ready.append(dependent)
            ready.sort(key=lambda key: self._priority_key(by_id[key]))
        if len(ordered) != len(records):
            unresolved = sorted(set(by_id) - {item["id"] for item in ordered})
            raise ValueError(f"Task dependencies contain a cycle: {unresolved}")
        return ordered

    def replan(self, tasks: Iterable[Any], completed: Iterable[str] = ()) -> list[dict[str, Any]]:
        return self.order_backlog(tasks, completed)

    @staticmethod
    def _as_dict(task: Any) -> dict[str, Any]:
        if isinstance(task, dict):
            item = dict(task)
        elif callable(getattr(task, "to_dict", None)):
            item = task.to_dict()
        else:
            raise TypeError("Tasks must be dictionaries or expose to_dict().")
        if not item.get("id"):
            raise ValueError("Every task must have a non-empty id.")
        item["id"] = str(item["id"])
        item["dependencies"] = sorted(set(item.get("dependencies", [])))
        return item

    @staticmethod
    def _priority_key(task: dict[str, Any]) -> tuple[int, str]:
        return int(task.get("priority", 1)), str(task["id"])

core/agent_bus.py.content:
"""Deterministic priority message bus for collaborating engineering agents."""

from __future__ import annotations

import copy
import heapq
import threading
import time
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Callable, Optional


class AgentMessageType(str, Enum):
    TASK_REQUEST = "TASK_REQUEST"
    TASK_RESULT = "TASK_RESULT"
    QUESTION = "QUESTION"
    ANSWER = "ANSWER"
    ERROR = "ERROR"
    STATUS = "STATUS"
    LEARNING_EVENT = "LEARNING_EVENT"
    SYSTEM_EVENT = "SYSTEM_EVENT"


@dataclass
class AgentMessage:
    message_id: str
    message_type: AgentMessageType
    sender: str
    receiver: str
    payload: dict[str, Any] = field(default_factory=dict)
    priority: int = 0
    correlation_id: Optional[str] = None
    acknowledged: bool = False
    created_sequence: int = 0

    def to_dict(self) -> dict[str, Any]:
        return {
            "message_id": self.message_id,
            "message_type": self.message_type.value,
            "sender": self.sender,
            "receiver": self.receiver,
            "payload": copy.deepcopy(self.payload),
            "priority": self.priority,
            "correlation_id": self.correlation_id,
            "acknowledged": self.acknowledged,
            "created_sequence": self.created_sequence,
        }


RequestMessage = AgentMessage
ResponseMessage = AgentMessage
BroadcastEvent = AgentMessage


class AgentBus:
    """Routes typed messages and delivers each inbox in priority/FIFO order."""

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._condition = threading.Condition(self._lock)
        self._sequence = 0
        self._inboxes: dict[str, list[tuple[int, int, AgentMessage]]] = {}
        self._history: list[AgentMessage] = []
        self._subscribers: dict[AgentMessageType, list[Callable[[AgentMessage], None]]] = {}
        self._pending_responses: dict[str, AgentMessage] = {}

    def subscribe(
        self,
        message_type: AgentMessageType | str,
        handler: Callable[[AgentMessage], None],
    ) -> None:
        kind = self._message_type(message_type)
        with self._lock:
            self._subscribers.setdefault(kind, []).append(handler)

    def register_inbox(self, agent_id: str) -> None:
        if not agent_id:
            raise ValueError("agent_id must not be empty")
        with self._lock:
            self._inboxes.setdefault(agent_id, [])

    def unsubscribe(
        self,
        message_type: AgentMessageType | str,
        handler: Callable[[AgentMessage], None],
    ) -> bool:
        kind = self._message_type(message_type)
        with self._lock:
            handlers = self._subscribers.get(kind, [])
            if handler not in handlers:
                return False
            handlers.remove(handler)
            return True

    def remove_inbox(self, agent_id: str) -> bool:
        """Removes an agent's queued messages and inbox."""
        with self._condition:
            removed = self._inboxes.pop(agent_id, None) is not None
            self._condition.notify_all()
            return removed

    def publish(
        self,
        message_type: AgentMessageType | str,
        sender: str,
        receiver: str,
        payload: Optional[dict[str, Any]] = None,
        priority: int = 0,
        correlation_id: Optional[str] = None,
    ) -> AgentMessage:
        if not sender or not receiver:
            raise ValueError("sender and receiver are required")
        kind = self._message_type(message_type)
        if not isinstance(priority, int):
            raise TypeError("priority must be an integer")
        with self._condition:
            self._sequence += 1
            message = AgentMessage(
                message_id=f"agent-msg-{self._sequence:08d}",
                message_type=kind,
                sender=sender,
                receiver=receiver,
                payload=copy.deepcopy(payload or {}),
                priority=priority,
                correlation_id=correlation_id,
                created_sequence=self._sequence,
            )
            self._history.append(copy.deepcopy(message))
            if kind == AgentMessageType.TASK_RESULT and correlation_id:
                self._pending_responses[correlation_id] = copy.deepcopy(message)
            if receiver == "*":
                targets = sorted(self._inboxes)
                for subscriber_type in (kind,):
                    handlers = list(self._subscribers.get(subscriber_type, []))
            else:
                targets = [receiver]
                handlers = list(self._subscribers.get(kind, []))
                self._inboxes.setdefault(receiver, [])
            for target in targets:
                heapq.heappush(
                    self._inboxes.setdefault(target, []),
                    (-priority, self._sequence, copy.deepcopy(message)),
                )
            self._condition.notify_all()
        for handler in handlers:
            handler(copy.deepcopy(message))
        return copy.deepcopy(message)

    def send_request(
        self,
        sender: str,
        receiver: str,
        payload: Optional[dict[str, Any]] = None,
        timeout: float = 5.0,
        priority: int = 0,
    ) -> Optional[AgentMessage]:
        if timeout < 0:
            raise ValueError("timeout must not be negative")
        request = self.publish(
            AgentMessageType.TASK_REQUEST, sender, receiver, payload, priority
        )
        deadline = time.monotonic() + timeout
        with self._condition:
            while request.message_id not in self._pending_responses:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    return None
                self._condition.wait(remaining)
            return copy.deepcopy(self._pending_responses.pop(request.message_id))

    def receive(self, agent_id: str, timeout: Optional[float] = None) -> Optional[AgentMessage]:
        if timeout is not None and timeout < 0:
            raise ValueError("timeout must not be negative")
        deadline = time.monotonic() + timeout if timeout is not None else None
        with self._condition:
            inbox = self._inboxes.setdefault(agent_id, [])
            while not inbox:
                if deadline is None:
                    self._condition.wait()
                else:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        return None
                    self._condition.wait(remaining)
            return copy.deepcopy(heapq.heappop(inbox)[2])

    def acknowledge(self, message_id: str) -> bool:
        with self._lock:
            for message in self._history:
                if message.message_id == message_id:
                    message.acknowledged = True
                    return True
            return False

    def broadcast(
        self,
        sender: str,
        payload: Optional[dict[str, Any]] = None,
        message_type: AgentMessageType | str = AgentMessageType.SYSTEM_EVENT,
        priority: int = 0,
    ) -> AgentMessage:
        return self.publish(message_type, sender, "*", payload, priority)

    def history(self, limit: Optional[int] = None) -> list[AgentMessage]:
        with self._lock:
            messages = self._history if limit is None else self._history[-max(0, limit):]
            return copy.deepcopy(messages)

    def inbox_size(self, agent_id: str) -> int:
        with self._lock:
            return len(self._inboxes.get(agent_id, []))

    @staticmethod
    def _message_type(value: AgentMessageType | str) -> AgentMessageType:
        return value if isinstance(value, AgentMessageType) else AgentMessageType(value)

core/agent_metrics.py.content:
"""Persistent per-agent execution, quality, and collaboration measurements."""

from __future__ import annotations

import json
import logging
import os
import re
import tempfile
import threading
from pathlib import Path
from typing import Any, Optional

logger = logging.getLogger("AutoDev.AgentMetrics")


class AgentMetricsTracker:
    """Maintains reproducible aggregate metrics and bounded execution history."""

    def __init__(self, storage_dir: str | Path = "memory/agent_metrics") -> None:
        self.storage_dir = Path(storage_dir).resolve()
        self.storage_dir.mkdir(parents=True, exist_ok=True)
        self._lock = threading.RLock()
        self._metrics: dict[str, dict[str, Any]] = {}
        self._load()

    def record(
        self,
        agent_id: str,
        success: bool,
        execution_time: float = 0.0,
        review_score: float = 0.0,
        defects: int = 0,
        collaboration_score: float = 0.0,
        resource_usage: Optional[dict[str, float]] = None,
    ) -> dict[str, Any]:
        if not agent_id:
            raise ValueError("agent_id must not be empty")
        if execution_time < 0 or defects < 0:
            raise ValueError("execution_time and defects must not be negative")
        record = {
            "success": bool(success),
            "execution_time": float(execution_time),
            "review_score": self._bounded(review_score, 100.0),
            "defects": int(defects),
            "collaboration_score": self._bounded(collaboration_score, 100.0),
            "resource_usage": {
                str(key): max(0.0, float(value))
                for key, value in sorted((resource_usage or {}).items())
            },
        }
        with self._lock:
            metric = self._metrics.setdefault(agent_id, {"history": []})
            metric["history"].append(record)
            metric["history"] = metric["history"][-1000:]
            result = self._summarize(metric["history"])
            metric.update(result)
            self._save_agent(agent_id, metric)
            return json.loads(json.dumps(result, sort_keys=True))

    def get_metrics(self, agent_id: str) -> dict[str, Any]:
        with self._lock:
            metric = self._metrics.get(agent_id)
            if metric is None:
                return self._summarize([])
            return {
                key: value
                for key, value in metric.items()
                if key != "history"
            }

    def all_metrics(self) -> dict[str, dict[str, Any]]:
        with self._lock:
            return {agent_id: self.get_metrics(agent_id) for agent_id in sorted(self._metrics)}

    def _load(self) -> None:
        for path in sorted(self.storage_dir.glob("*.json")):
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
                if not isinstance(data, dict) or not isinstance(data.get("agent_id"), str):
                    raise ValueError("Agent metrics document has an invalid schema")
                history = data.get("history", [])
                if not isinstance(history, list):
                    raise ValueError("Agent metrics history must be a list")
                self._metrics[data["agent_id"]] = {
                    "history": history[-1000:],
                    **self._summarize(history),
                }
            except (OSError, ValueError, TypeError) as err:
                logger.warning("Ignoring invalid agent metrics file %s: %s", path, err)

    def _save_agent(self, agent_id: str, metric: dict[str, Any]) -> None:
        safe_id = re.sub(r"[^A-Za-z0-9_.-]", "_", agent_id)[:100] or "agent"
        target = self.storage_dir / f"{safe_id}.json"
        data = {"agent_id": agent_id, **metric}
        temporary_path: Optional[Path] = None
        try:
            with tempfile.NamedTemporaryFile(
                "w", encoding="utf-8", dir=self.storage_dir, delete=False
            ) as temporary:
                json.dump(data, temporary, sort_keys=True, indent=2)
                temporary_path = Path(temporary.name)
            os.replace(temporary_path, target)
        except (OSError, TypeError, ValueError) as err:
            logger.error("Could not persist metrics for agent %s: %s", agent_id, err)
            if temporary_path is not None:
                temporary_path.unlink(missing_ok=True)
            raise

    @staticmethod
    def _summarize(history: list[dict[str, Any]]) -> dict[str, Any]:
        count = len(history)
        successes = sum(1 for entry in history if bool(entry.get("success")))
        failures = count - successes
        if count:
            average_time = sum(float(entry.get("execution_time", 0.0)) for entry in history) / count
            review = sum(float(entry.get("review_score", 0.0)) for entry in history) / count
            defects = sum(int(entry.get("defects", 0)) for entry in history)
            collaboration = sum(float(entry.get("collaboration_score", 0.0)) for entry in history) / count
            resource_names = sorted({
                key for entry in history for key in entry.get("resource_usage", {})
            })
            resources = {
                key: round(
                    sum(float(entry.get("resource_usage", {}).get(key, 0.0)) for entry in history) / count,
                    4,
                )
                for key in resource_names
            }
            recent = history[-max(1, count // 2):]
            earlier = history[:count - len(recent)]
            trend = (
                round(
                    sum(1.0 if entry.get("success") else 0.0 for entry in recent) / len(recent)
                    - sum(1.0 if entry.get("success") else 0.0 for entry in earlier) / len(earlier),
                    4,
                )
                if earlier else 0.0
            )
        else:
            average_time = review = collaboration = 0.0
            defects = 0
            resources = {}
            trend = 0.0
        return {
            "task_count": count,
            "success_rate": round(successes / count, 4) if count else 0.0,
            "failure_rate": round(failures / count, 4) if count else 0.0,
            "average_execution_time": round(average_time, 4),
            "average_review_score": round(review, 4),
            "defect_rate": round(defects / count, 4) if count else 0.0,
            "collaboration_score": round(collaboration, 4),
            "resource_usage": resources,
            "improvement_trend": trend,
        }

    @staticmethod
    def _bounded(value: float, maximum: float) -> float:
        return max(0.0, min(maximum, float(value)))

core/architecture_evolution.py.content:
"""Architecture inspection and deterministic evolution recommendations."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from core.repository_analyzer import RepositoryAnalyzer
from core.symbol_graph import SymbolGraph


class ArchitectureEvolutionEngine:
    """Reuses repository intelligence to identify architectural risk and options."""

    def __init__(self, analyzer: RepositoryAnalyzer | None = None) -> None:
        self.analyzer = analyzer

    def analyze(
        self,
        project_root: str | Path,
        symbol_graph: SymbolGraph | None = None,
        code_quality: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        root = Path(project_root).resolve()
        overview = (self.analyzer or RepositoryAnalyzer(project_root=root)).analyze(
            project_root=root,
            symbol_graph=symbol_graph,
        )
        hotspots = sorted(
            (item.to_dict() for item in overview.hotspots),
            key=lambda item: (-float(item.get("score", 0)), str(item.get("target", ""))),
        )
        cycles = sorted(
            (item.to_dict() for item in overview.circular_dependencies),
            key=lambda item: tuple(item.get("cycle", [])),
        )
        recommendations: list[dict[str, Any]] = []
        for cycle in cycles:
            recommendations.append({
                "title": "Break circular module dependencies",
                "priority": "high",
                "evidence": cycle.get("cycle", []),
                "action": "Move shared contracts to a lower-level module.",
            })
        for hotspot in hotspots:
            if hotspot.get("category") in {"largest_module", "god_object", "high_fan_out"}:
                recommendations.append({
                    "title": f"Reduce architectural hotspot: {hotspot['target']}",
                    "priority": "high" if hotspot.get("category") == "god_object" else "medium",
                    "evidence": [hotspot],
                    "action": "Split cohesive responsibilities behind stable interfaces.",
                })
        quality = code_quality or {}
        for item in quality.get("recommendations", []):
            if "maintainability" in str(item).lower() or "complexity" in str(item).lower():
                recommendations.append({
                    "title": str(item),
                    "priority": "medium",
                    "evidence": [],
                    "action": "Simplify the identified implementation while preserving its public contract.",
                })
        recommendations = sorted(
            recommendations,
            key=lambda item: (
                0 if item["priority"] == "high" else 1,
                item["title"],
            ),
        )

        module_count = max(1, overview.total_modules)
        complexity_ratio = min(1.0, len(hotspots) / module_count)
        cycle_ratio = min(1.0, len(cycles) / module_count)
        maintainability = round(max(0.0, 100.0 - 60.0 * complexity_ratio - 80.0 * cycle_ratio), 2)
        architectures = sorted(
            (item.to_dict() for item in overview.detected_architectures),
            key=lambda item: (-float(item.get("confidence", 0)), str(item.get("pattern_name", ""))),
        )
        return {
            "project_name": overview.project_name,
            "module_count": overview.total_modules,
            "symbol_count": overview.total_symbols,
            "architectures": architectures,
            "hotspots": hotspots,
            "bottlenecks": [item for item in hotspots if item.get("category") in {"high_fan_out", "high_fan_in"}],
            "circular_dependencies": cycles,
            "dead_code_candidates": sorted(overview.dead_code_candidates),
            "recommendations": recommendations,
            "maintainability_estimate": maintainability,
            "alternatives": [
                {"name": "retain_current_boundaries", "maintainability_estimate": maintainability},
                {
                    "name": "reduce_coupling_and_split_hotspots",
                    "maintainability_estimate": round(min(100.0, maintainability + 10.0), 2),
                },
            ],
        }

core/artifact_chunk_store.py.content:
"""
AutoDev Content-Addressed Artifact Chunk Store (Phase 4 - Differential Artifact Synchronization)
Provides immutable, content-addressed storage for artifact chunks with cryptographic
verification, deduplication, path-traversal prevention, and storage quota enforcement.
"""

from dataclasses import dataclass
import hashlib
import os
import re
from typing import Dict, List, Optional, Any


class ChunkStoreError(Exception):
    """Base exception for chunk store errors."""
    pass


class StorageQuotaExceededError(ChunkStoreError):
    """Raised when storing a chunk would exceed configured storage quota."""
    pass


class ChunkIntegrityError(ChunkStoreError):
    """Raised when chunk data does not match declared cryptographic digest."""
    pass


HEX_PATTERN = re.compile(r"^[0-9a-fA-F]{64}$")


class ArtifactChunkStore:
    """
    Content-Addressed Storage (CAS) for deduplicated binary chunks.
    Storage hierarchy: `<storage_root>/sha256/<prefix>/<digest>.chunk`
    """

    def __init__(
        self,
        storage_root: str = "memory/artifact_chunks",
        storage_quota_bytes: int = 10 * 1024 * 1024 * 1024,  # 10GB default
    ) -> None:
        self.storage_root = os.path.abspath(storage_root)
        self.storage_quota_bytes = storage_quota_bytes
        self.base_dir = os.path.join(self.storage_root, "sha256")
        os.makedirs(self.base_dir, exist_ok=True)

    def _validate_digest(self, digest: str) -> str:
        """Validate digest format to prevent directory traversal or malformed keys."""
        cleaned = digest.strip().lower()
        if not HEX_PATTERN.match(cleaned):
            raise ValueError(f"Invalid SHA-256 digest format: {digest}")
        return cleaned

    def _chunk_path(self, digest: str) -> str:
        cleaned = self._validate_digest(digest)
        prefix = cleaned[:2]
        return os.path.join(self.base_dir, prefix, f"{cleaned}.chunk")

    def has_chunk(self, digest: str) -> bool:
        """Check if chunk exists in CAS."""
        try:
            path = self._chunk_path(digest)
            return os.path.isfile(path)
        except ValueError:
            return False

    def put_chunk(self, digest: str, data: bytes) -> bool:
        """
        Verify cryptographic integrity of data against digest, check quotas,
        and store immutably. Deduplicates existing chunks.
        """
        cleaned = self._validate_digest(digest)
        actual_sha256 = hashlib.sha256(data).hexdigest().lower()
        if actual_sha256 != cleaned:
            raise ChunkIntegrityError(f"Chunk digest mismatch: declared {cleaned} != actual {actual_sha256}")

        path = self._chunk_path(cleaned)
        if os.path.isfile(path):
            # Already deduplicated and verified
            return True

        # Check quota
        current_usage = self.get_total_bytes()
        if current_usage + len(data) > self.storage_quota_bytes:
            raise StorageQuotaExceededError(
                f"Chunk store quota exceeded ({current_usage + len(data)} > {self.storage_quota_bytes} bytes)"
            )

        os.makedirs(os.path.dirname(path), exist_ok=True)
        temp_path = f"{path}.tmp.{os.getpid()}"
        try:
            with open(temp_path, "wb") as f:
                f.write(data)
            os.rename(temp_path, path)
            return True
        finally:
            if os.path.exists(temp_path):
                try:
                    os.remove(temp_path)
                except OSError:
                    pass

    def get_chunk(self, digest: str) -> Optional[bytes]:
        """Retrieve chunk binary payload, verifying its integrity on read."""
        path = self._chunk_path(digest)
        if not os.path.isfile(path):
            return None
        with open(path, "rb") as f:
            data = f.read()

        # Integrity verification
        actual_sha256 = hashlib.sha256(data).hexdigest().lower()
        cleaned = self._validate_digest(digest)
        if actual_sha256 != cleaned:
            raise ChunkIntegrityError(f"Corrupted chunk detected at {path}: expected {cleaned}, got {actual_sha256}")
        return data

    def delete_chunk(self, digest: str) -> bool:
        """Delete chunk from CAS."""
        try:
            path = self._chunk_path(digest)
            if os.path.isfile(path):
                os.remove(path)
                return True
            return False
        except (ValueError, OSError):
            return False

    def list_chunks(self) -> List[str]:
        """List all valid chunk digests stored in CAS."""
        digests: List[str] = []
        if not os.path.isdir(self.base_dir):
            return digests

        for prefix in os.listdir(self.base_dir):
            prefix_dir = os.path.join(self.base_dir, prefix)
            if os.path.isdir(prefix_dir):
                for filename in os.listdir(prefix_dir):
                    if filename.endswith(".chunk"):
                        digest = filename[:-6]
                        if HEX_PATTERN.match(digest):
                            digests.append(digest)
        return digests

    def get_total_bytes(self) -> int:
        """Calculate total storage consumed by chunks."""
        total = 0
        if not os.path.isdir(self.base_dir):
            return 0
        for root, _, files in os.walk(self.base_dir):
            for f in files:
                if f.endswith(".chunk"):
                    total += os.path.getsize(os.path.join(root, f))
        return total

    def get_stats(self) -> Dict[str, Any]:
        """Return storage metrics and quota consumption."""
        chunks = self.list_chunks()
        total_bytes = self.get_total_bytes()
        pct = (total_bytes / self.storage_quota_bytes * 100.0) if self.storage_quota_bytes > 0 else 0.0
        return {
            "chunk_count": len(chunks),
            "total_bytes": total_bytes,
            "storage_quota_bytes": self.storage_quota_bytes,
            "usage_percentage": round(pct, 2),
            "storage_root": self.storage_root,
        }

core/blackboard.py.content:
"""Versioned shared blackboard with locking and optimistic conflict detection."""

from __future__ import annotations

import copy
import threading
from dataclasses import dataclass
from typing import Any, Optional


class BlackboardConflictError(RuntimeError):
    """Raised when a writer observes a stale version or another owner's lock."""


@dataclass(frozen=True)
class BlackboardVersion:
    key: str
    version: int
    value: Any
    writer: str

    def to_dict(self) -> dict[str, Any]:
        return {
            "key": self.key,
            "version": self.version,
            "value": copy.deepcopy(self.value),
            "writer": self.writer,
        }


class Blackboard:
    """Thread-safe, copy-isolated shared values with rollback-able history."""

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._values: dict[str, Any] = {}
        self._versions: dict[str, int] = {}
        self._history: dict[str, list[BlackboardVersion]] = {}
        self._owners: dict[str, str] = {}

    def read(self, key: str, default: Any = None) -> Any:
        with self._lock:
            return copy.deepcopy(self._values.get(key, default))

    def write(
        self,
        key: str,
        value: Any,
        writer: str = "system",
        expected_version: Optional[int] = None,
    ) -> int:
        if not key:
            raise ValueError("key must not be empty")
        with self._lock:
            owner = self._owners.get(key)
            if owner is not None and owner != writer:
                raise BlackboardConflictError(f"key {key!r} is locked by {owner!r}")
            current = self._versions.get(key, 0)
            if expected_version is not None and expected_version != current:
                raise BlackboardConflictError(
                    f"stale version for {key!r}: expected {expected_version}, current {current}"
                )
            version = current + 1
            stored = copy.deepcopy(value)
            self._values[key] = stored
            self._versions[key] = version
            self._history.setdefault(key, []).append(
                BlackboardVersion(key, version, stored, writer)
            )
            return version

    def lock(self, key: str, owner: str) -> bool:
        if not key or not owner:
            raise ValueError("key and owner are required")
        with self._lock:
            current = self._owners.get(key)
            if current is not None and current != owner:
                return False
            self._owners[key] = owner
            return True

    def unlock(self, key: str, owner: str) -> bool:
        with self._lock:
            if self._owners.get(key) != owner:
                return False
            del self._owners[key]
            return True

    def history(self, key: str) -> list[BlackboardVersion]:
        with self._lock:
            return copy.deepcopy(self._history.get(key, []))

    def snapshot(self) -> dict[str, Any]:
        with self._lock:
            return {
                "values": copy.deepcopy(self._values),
                "versions": dict(self._versions),
                "history": {
                    key: [entry.to_dict() for entry in entries]
                    for key, entries in sorted(self._history.items())
                },
            }

    def rollback(self, key: str, version: Optional[int] = None, writer: str = "system") -> int:
        with self._lock:
            entries = self._history.get(key, [])
            candidates = [entry for entry in entries if entry.version == version] if version is not None else entries[:-1]
            if not candidates:
                raise KeyError(f"No prior version exists for key {key!r}")
            previous = candidates[-1]
            return self.write(key, previous.value, writer=writer)

    def version(self, key: str) -> int:
        with self._lock:
            return self._versions.get(key, 0)

core/cache_manager.py.content:
"""
cache_manager.py - Unified Cache Management Subsystem for AutoDev (v3.6.1)

Provides a centralized interface for managing, validating, cleaning, and
tracking statistics for all persistent caches in the system.
"""

from __future__ import annotations

import json
import logging
import shutil
import tempfile
import threading
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Optional, Union

logger = logging.getLogger("AutoDev.CacheManager")

@dataclass
class CacheMetadata:
    """Metadata for a single cache entry or subsystem."""
    name: str
    path: Path
    version: str
    created_at: float
    last_accessed: float
    size_bytes: int
    entry_count: int
    hit_count: int = 0
    miss_count: int = 0

    def to_dict(self) -> Dict[str, Any]:
        return {
            "name": self.name,
            "path": str(self.path),
            "version": self.version,
            "created_at": self.created_at,
            "last_accessed": self.last_accessed,
            "size_bytes": self.size_bytes,
            "entry_count": self.entry_count,
            "hit_count": self.hit_count,
            "miss_count": self.miss_count,
            "hit_ratio": self.hit_count / (self.hit_count + self.miss_count) if (self.hit_count + self.miss_count) > 0 else 0.0
        }

class CacheManager:
    """
    Centralized manager for all AutoDev caches.
    Ensures version consistency, provides cleanup routines, and tracks performance.
    """

    CACHE_ROOT = Path("memory/cache")
    METADATA_FILE = CACHE_ROOT / "cache_metadata.json"
    VERSION = "1"

    def __init__(self, cache_root: Optional[Union[str, Path]] = None) -> None:
        self.cache_root = Path(cache_root).resolve() if cache_root else self.CACHE_ROOT.resolve()
        self.cache_root.mkdir(parents=True, exist_ok=True)
        self.metadata_file = self.cache_root / "cache_metadata.json"
        self.metadata: Dict[str, CacheMetadata] = {}
        self._lock = threading.RLock()
        self._load_metadata()
        self.repair()

    def _load_metadata(self) -> None:
        if self.metadata_file.exists():
            try:
                data = json.loads(self.metadata_file.read_text(encoding="utf-8"))
                if not isinstance(data, dict):
                    raise ValueError("Cache metadata must be a JSON object.")
                for name, mdata in data.items():
                    if not isinstance(mdata, dict):
                        raise ValueError(f"Invalid metadata entry for cache {name!r}.")
                    mdata.pop("hit_ratio", None)
                    mdata["path"] = Path(mdata["path"])
                    self.metadata[name] = CacheMetadata(**mdata)
            except (OSError, ValueError, TypeError, KeyError, json.JSONDecodeError) as err:
                logger.warning("Failed to load cache metadata from %s: %s", self.metadata_file, err)
                self.metadata = {}

    def _save_metadata(self) -> None:
        with self._lock:
            data = {name: m.to_dict() for name, m in self.metadata.items()}
            self.cache_root.mkdir(parents=True, exist_ok=True)
            with tempfile.NamedTemporaryFile(
                "w", encoding="utf-8", dir=self.cache_root, delete=False
            ) as temp_file:
                json.dump(data, temp_file, indent=2, sort_keys=True)
                temp_path = Path(temp_file.name)
            temp_path.replace(self.metadata_file)

    def register_cache(self, name: str, version: str) -> Path:
        """Registers or retrieves a cache directory."""
        cache_name = Path(name)
        if not name or cache_name.is_absolute() or ".." in cache_name.parts:
            raise ValueError("Cache name must be a non-empty relative path within the cache root.")
        cache_path = self.cache_root / name
        cache_path.resolve().relative_to(self.cache_root)

        with self._lock:
            if name not in self.metadata or self.metadata[name].version != version:
                if name in self.metadata:
                    logger.info("Cache version mismatch for %s. Clearing old cache.", name)
                    self.clear_cache(name)

                now = time.time()
                self.metadata[name] = CacheMetadata(
                    name=name,
                    path=cache_path,
                    version=version,
                    created_at=now,
                    last_accessed=now,
                    size_bytes=0,
                    entry_count=0,
                )
                cache_path.mkdir(parents=True, exist_ok=True)
                self._save_metadata()
            else:
                cache_path.mkdir(parents=True, exist_ok=True)

        return cache_path

    def update_stats(
        self,
        name: str,
        size_bytes: Optional[int] = None,
        entry_count: Optional[int] = None,
        hit: bool = False,
        miss: bool = False,
    ) -> None:
        """Updates statistics for a registered cache."""
        with self._lock:
            if name not in self.metadata:
                return

            metadata = self.metadata[name]
            metadata.last_accessed = time.time()
            if size_bytes is not None:
                metadata.size_bytes = size_bytes
            if entry_count is not None:
                metadata.entry_count = entry_count
            if hit:
                metadata.hit_count += 1
            if miss:
                metadata.miss_count += 1
            self._save_metadata()

    def get_stats(self) -> Dict[str, Any]:
        """Returns statistics for all registered caches."""
        with self._lock:
            total_size = sum(metadata.size_bytes for metadata in self.metadata.values())
            return {
                "total_size_bytes": total_size,
                "cache_count": len(self.metadata),
                "caches": {
                    name: self.metadata[name].to_dict()
                    for name in sorted(self.metadata)
                },
            }

    def clear_cache(self, name: str) -> bool:
        """Clears a specific cache by name."""
        with self._lock:
            metadata = self.metadata.get(name)
            if metadata is None:
                return False
            cache_path = metadata.path.resolve()
            cache_path.relative_to(self.cache_root)
            if cache_path == self.cache_root:
                raise ValueError("Refusing to clear the cache root itself.")
            if cache_path.exists():
                shutil.rmtree(cache_path)
            cache_path.mkdir(parents=True, exist_ok=True)
            metadata.size_bytes = 0
            metadata.entry_count = 0
            metadata.hit_count = 0
            metadata.miss_count = 0
            metadata.last_accessed = time.time()
            self._save_metadata()
            return True

    def clear(self, name: Optional[str] = None) -> None:
        """Clears one registered cache, or all registered caches when omitted."""
        if name is not None:
            self.clear_cache(name)
            return
        for cache_name in sorted(self.metadata):
            self.clear_cache(cache_name)

    def clear_all(self) -> None:
        """Clears all registered caches."""
        self.clear()

    def cleanup(self, max_age_seconds: float) -> list[str]:
        """Clears caches that have not been accessed within the supplied duration."""
        if max_age_seconds < 0:
            raise ValueError("max_age_seconds must not be negative.")
        now = time.time()
        expired = sorted(
            name
            for name, metadata in self.metadata.items()
            if now - metadata.last_accessed > max_age_seconds
        )
        for name in expired:
            self.clear_cache(name)
        return expired

    def validate_cache(self, name: str, max_age_seconds: Optional[int] = None) -> bool:
        """Validates if a cache is still valid based on age or other criteria."""
        with self._lock:
            metadata = self.metadata.get(name)
            if metadata is None or not metadata.path.is_dir():
                return False
            if max_age_seconds is not None and max_age_seconds >= 0:
                if time.time() - metadata.last_accessed > max_age_seconds:
                    logger.info("Cache %s expired.", name)
                    return False
            return True

    def get_cache_path(self, name: str) -> Optional[Path]:
        """Returns the path for a registered cache."""
        return self.metadata[name].path if name in self.metadata else None

    def verify(self) -> Dict[str, bool]:
        """Checks that registered cache paths exist and stay inside the cache root."""
        results: Dict[str, bool] = {}
        with self._lock:
            for name, metadata in sorted(self.metadata.items()):
                try:
                    metadata.path.resolve().relative_to(self.cache_root)
                    results[name] = metadata.path.is_dir()
                except ValueError:
                    results[name] = False
        return results

    def repair(self) -> Dict[str, bool]:
        """Repairs missing cache directories and recomputes their disk statistics."""
        repaired: Dict[str, bool] = {}
        with self._lock:
            for name, metadata in sorted(self.metadata.items()):
                try:
                    cache_path = metadata.path.resolve()
                    cache_path.relative_to(self.cache_root)
                    if cache_path == self.cache_root:
                        raise ValueError("Cache path cannot be the cache root.")
                    existed = cache_path.is_dir()
                    cache_path.mkdir(parents=True, exist_ok=True)
                    size_bytes = 0
                    entry_count = 0
                    for path in cache_path.rglob("*"):
                        if path.is_file():
                            try:
                                size_bytes += path.stat().st_size
                                entry_count += 1
                            except OSError as err:
                                logger.warning("Could not stat cache entry %s: %s", path, err)
                    metadata.path = cache_path
                    metadata.size_bytes = size_bytes
                    metadata.entry_count = entry_count
                    repaired[name] = not existed
                except (OSError, ValueError) as err:
                    logger.error("Could not repair cache %s: %s", name, err)
                    repaired[name] = False
            if repaired:
                self._save_metadata()
        return repaired

    def stats(self) -> Dict[str, Any]:
        """Public alias for :meth:`get_stats`."""
        return self.get_stats()

core/capability_manager.py.content:
"""Deterministic capability and performance profile management for agents."""

from __future__ import annotations

import threading
from typing import Any, Optional

from core.multi_agent.agent_registry import AgentDescriptor, AgentRegistry


class AgentCapabilityManager:
    """Indexes skills, languages, domains, accuracy, and preferred workloads."""

    def __init__(self, registry: Optional[AgentRegistry] = None) -> None:
        self.registry = registry or AgentRegistry()
        self._lock = threading.RLock()
        self._profiles: dict[str, dict[str, Any]] = {}

    def register(
        self,
        agent_id: str,
        skills: Optional[list[str]] = None,
        languages: Optional[list[str]] = None,
        domains: Optional[list[str]] = None,
        preferred_workloads: Optional[list[str]] = None,
        historical_accuracy: float = 1.0,
        benchmark_performance: float = 0.0,
        reliability: float = 1.0,
        descriptor: Optional[AgentDescriptor] = None,
    ) -> dict[str, Any]:
        if not agent_id:
            raise ValueError("agent_id must not be empty")
        profile = {
            "skills": sorted({str(item).lower() for item in skills or []}),
            "languages": sorted({str(item).lower() for item in languages or []}),
            "domains": sorted({str(item).lower() for item in domains or []}),
            "preferred_workloads": sorted({str(item).lower() for item in preferred_workloads or []}),
            "historical_accuracy": self._bounded(historical_accuracy),
            "benchmark_performance": self._bounded(benchmark_performance),
            "reliability": self._bounded(reliability),
        }
        with self._lock:
            if descriptor is not None and self.registry.get_agent(agent_id) is None:
                self.registry.register_agent(descriptor)
            self._profiles[agent_id] = profile
            return dict(profile)

    def profile(self, agent_id: str) -> Optional[dict[str, Any]]:
        with self._lock:
            profile = self._profiles.get(agent_id)
            return dict(profile) if profile else None

    def discover(
        self,
        skills: Optional[list[str]] = None,
        languages: Optional[list[str]] = None,
        domains: Optional[list[str]] = None,
        available_only: bool = True,
    ) -> list[dict[str, Any]]:
        required = {
            "skills": {str(item).lower() for item in skills or []},
            "languages": {str(item).lower() for item in languages or []},
            "domains": {str(item).lower() for item in domains or []},
        }
        results = []
        with self._lock:
            profiles = dict(self._profiles)
        for descriptor in self.registry.get_all_agents():
            profile = profiles.get(descriptor.agent_id, {})
            if available_only and not descriptor.is_available:
                continue
            if any(not values.issubset(set(profile.get(name, []))) for name, values in required.items()):
                continue
            results.append({"agent": descriptor, "profile": dict(profile)})
        return sorted(results, key=lambda item: item["agent"].agent_id)

    def recommend(
        self,
        skills: Optional[list[str]] = None,
        languages: Optional[list[str]] = None,
        domains: Optional[list[str]] = None,
        available_only: bool = True,
    ) -> Optional[dict[str, Any]]:
        candidates = self.discover(skills, languages, domains, available_only)
        if not candidates:
            return None
        required_count = sum(len(values or []) for values in (skills, languages, domains))
        def score(item: dict[str, Any]) -> tuple[float, str]:
            profile = item["profile"]
            descriptor = item["agent"]
            accuracy = profile.get("historical_accuracy", descriptor.historical_success_rate)
            reliability = profile.get("reliability", descriptor.historical_success_rate)
            benchmark = profile.get("benchmark_performance", 0.0)
            availability = 1.0 - descriptor.workload / max(1, descriptor.max_workload)
            return (
                0.35 * accuracy + 0.30 * reliability + 0.20 * benchmark
                + 0.15 * availability + min(0.05, required_count * 0.01),
                descriptor.agent_id,
            )
        return min(candidates, key=lambda item: (-score(item)[0], item["agent"].agent_id))

    @staticmethod
    def _bounded(value: float) -> float:
        return round(max(0.0, min(1.0, float(value))), 4)

core/change_detector.py.content:
"""Deterministic repository change detection for incremental AutoDev workflows."""

from __future__ import annotations

import hashlib
import json
import logging
import os
import tempfile
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, Mapping, Optional, Set

logger = logging.getLogger("AutoDev.ChangeDetector")


@dataclass
class ChangeSet:
    """Classified repository changes between two content-hash snapshots."""

    modified_files: list[str] = field(default_factory=list)
    deleted_files: list[str] = field(default_factory=list)
    renamed_files: Dict[str, str] = field(default_factory=dict)
    new_files: list[str] = field(default_factory=list)
    changed_tests: list[str] = field(default_factory=list)
    changed_documentation: list[str] = field(default_factory=list)
    current_snapshot: Dict[str, str] = field(default_factory=dict)

    @property
    def changed_files(self) -> list[str]:
        """Returns all paths affected by this change, in stable order."""
        paths = set(self.modified_files) | set(self.deleted_files) | set(self.new_files)
        for old_path, new_path in self.renamed_files.items():
            paths.update((old_path, new_path))
        return sorted(paths)

    @property
    def changed_source_files(self) -> list[str]:
        """Returns changed, existing paths suitable for indexing."""
        paths = set(self.modified_files) | set(self.new_files)
        paths.update(self.renamed_files.values())
        return sorted(paths)

    def to_dict(self) -> Dict[str, object]:
        return {
            "modified_files": list(self.modified_files),
            "deleted_files": list(self.deleted_files),
            "renamed_files": dict(sorted(self.renamed_files.items())),
            "new_files": list(self.new_files),
            "changed_tests": list(self.changed_tests),
            "changed_documentation": list(self.changed_documentation),
            "current_snapshot": dict(sorted(self.current_snapshot.items())),
        }


class RepositoryChangeDetector:
    """Hashes repository files and compares them with a persisted prior snapshot."""

    VERSION = 1
    DEFAULT_IGNORED_DIRS = {
        ".git",
        "__pycache__",
        ".pytest_cache",
        ".mypy_cache",
        ".ruff_cache",
        ".venv",
        "venv",
        "env",
        "node_modules",
        "dist",
        "build",
        "target",
    }
    DOCUMENTATION_SUFFIXES = {".md", ".rst", ".adoc", ".txt"}

    def __init__(
        self,
        project_root: str | Path,
        snapshot_path: Optional[str | Path] = None,
        ignored_dirs: Optional[Set[str]] = None,
    ) -> None:
        self.project_root = Path(project_root).resolve()
        self.snapshot_path = (
            Path(snapshot_path).resolve()
            if snapshot_path is not None
            else self.project_root / "memory" / "cache" / "repository_changes" / "snapshot.json"
        )
        self.ignored_dirs = set(ignored_dirs or self.DEFAULT_IGNORED_DIRS)
        self.ignored_dirs.add("__pycache__")
        self.current_snapshot: Dict[str, str] = {}
        self.current_file_stats: Dict[str, tuple[int, int, int, int]] = {}

    def snapshot(self) -> Dict[str, str]:
        """Returns normalized relative paths and SHA-256 hashes for regular files."""
        hashes: Dict[str, str] = {}
        file_stats: Dict[str, tuple[int, int, int, int]] = {}
        if not self.project_root.is_dir():
            self.current_snapshot = {}
            self.current_file_stats = {}
            return hashes

        for current_root, directories, file_names in os.walk(self.project_root):
            current_path = Path(current_root)
            rel_root = current_path.relative_to(self.project_root)
            directories[:] = sorted(
                directory
                for directory in directories
                if directory not in self.ignored_dirs
                and (
                    not directory.startswith(".")
                    or directory in {".agents", ".github"}
                )
                and not directory.startswith(".venv-")
                and not directory.startswith("venv-")
                and not (
                    rel_root.as_posix() == "memory"
                    and directory == "cache"
                )
                and not (
                    rel_root.as_posix() == "memory"
                    and directory == "benchmarks"
                )
            )
            for file_name in sorted(file_names):
                file_path = current_path / file_name
                if file_path.is_symlink() or not file_path.is_file():
                    continue
                rel_path = file_path.relative_to(self.project_root).as_posix()
                if (
                    Path(rel_path).parts[0] == "memory"
                    and Path(rel_path).suffix.lower() in {".json", ".pickle", ".pkl"}
                ):
                    continue
                try:
                    file_stat = file_path.stat()
                    hashes[rel_path] = self._hash_file(file_path)
                except OSError as err:
                    logger.warning("Could not hash repository file %s: %s", file_path, err)
                    continue
                file_stats[rel_path] = self._stat_signature(file_stat)

        self.current_snapshot = dict(sorted(hashes.items()))
        self.current_file_stats = dict(sorted(file_stats.items()))
        return self.current_snapshot

    def matches_current_stat(self, relative_path: str, file_path: Path) -> bool:
        """Checks whether a file still has the metadata observed during snapshotting."""
        expected = self.current_file_stats.get(relative_path.replace("\\", "/"))
        if expected is None:
            return False
        try:
            return expected == self._stat_signature(file_path.stat())
        except OSError:
            return False

    @staticmethod
    def _stat_signature(
        file_stat: os.stat_result,
    ) -> tuple[int, int, int, int]:
        return (
            file_stat.st_size,
            file_stat.st_mtime_ns,
            file_stat.st_ctime_ns,
            getattr(file_stat, "st_ino", 0),
        )

    @staticmethod
    def _hash_file(file_path: Path) -> str:
        digest = hashlib.sha256()
        with file_path.open("rb") as file_handle:
            for chunk in iter(lambda: file_handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()

    def load(self) -> Dict[str, str]:
        """Loads a valid persisted snapshot, or returns an empty snapshot."""
        try:
            data = json.loads(self.snapshot_path.read_text(encoding="utf-8"))
            if not isinstance(data, dict):
                raise ValueError("Repository snapshot root must be a JSON object.")
            if data.get("version") != self.VERSION or not isinstance(data.get("files"), dict):
                logger.warning("Ignoring incompatible repository snapshot at %s", self.snapshot_path)
                return {}
            return {
                str(path): str(content_hash)
                for path, content_hash in sorted(data["files"].items())
                if isinstance(path, str) and isinstance(content_hash, str)
            }
        except FileNotFoundError:
            return {}
        except (OSError, ValueError, TypeError) as err:
            logger.warning("Could not load repository snapshot %s: %s", self.snapshot_path, err)
            return {}

    def detect(self, previous_snapshot: Optional[Mapping[str, str]] = None) -> ChangeSet:
        """Classifies changed, added, deleted, renamed, test, and documentation files."""
        previous = dict(previous_snapshot) if previous_snapshot is not None else self.load()
        current = self.snapshot()
        modified = sorted(
            path for path in current.keys() & previous.keys()
            if current[path] != previous[path]
        )
        new = set(current) - set(previous)
        deleted = set(previous) - set(current)
        renamed: Dict[str, str] = {}

        old_by_hash: Dict[str, list[str]] = {}
        new_by_hash: Dict[str, list[str]] = {}
        for old_path in sorted(deleted):
            old_by_hash.setdefault(previous[old_path], []).append(old_path)
        for new_path in sorted(new):
            new_by_hash.setdefault(current[new_path], []).append(new_path)
        for content_hash in sorted(old_by_hash.keys() & new_by_hash.keys()):
            for old_path, new_path in zip(old_by_hash[content_hash], new_by_hash[content_hash]):
                renamed[old_path] = new_path
                deleted.remove(old_path)
                new.remove(new_path)

        changed_paths = set(modified) | set(new) | set(deleted)
        for old_path, new_path in renamed.items():
            changed_paths.update((old_path, new_path))

        changed_tests = sorted(path for path in changed_paths if self._is_test_file(path))
        changed_docs = sorted(path for path in changed_paths if self._is_documentation_file(path))
        return ChangeSet(
            modified_files=modified,
            deleted_files=sorted(deleted),
            renamed_files=dict(sorted(renamed.items())),
            new_files=sorted(new),
            changed_tests=changed_tests,
            changed_documentation=changed_docs,
            current_snapshot=current,
        )

    def save(self, snapshot: Optional[Mapping[str, str]] = None) -> None:
        """Persists the supplied snapshot (or the current repository snapshot) atomically."""
        files = dict(snapshot) if snapshot is not None else self.snapshot()
        if self.load() == dict(sorted(files.items())):
            return
        self.snapshot_path.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-8", dir=self.snapshot_path.parent, delete=False
        ) as temp_file:
            json.dump(
                {"version": self.VERSION, "files": dict(sorted(files.items()))},
                temp_file,
                indent=2,
                sort_keys=True,
            )
            temp_path = Path(temp_file.name)
        temp_path.replace(self.snapshot_path)

    def detect_changes(self, previous_snapshot: Optional[Mapping[str, str]] = None) -> ChangeSet:
        """Compatibility-friendly alias for :meth:`detect`."""
        return self.detect(previous_snapshot)

    @staticmethod
    def _is_test_file(path: str) -> bool:
        name = Path(path).name.lower()
        return (
            (name.startswith("test_") and name.endswith(".py"))
            or name.endswith("_test.py")
            or ".test." in name
            or ".spec." in name
            or ("/__tests__/" in f"/{path.lower()}/")
        )

    @classmethod
    def _is_documentation_file(cls, path: str) -> bool:
        normalized = path.lower()
        name = Path(normalized).name
        return (
            Path(normalized).suffix in cls.DOCUMENTATION_SUFFIXES
            and (
                name == "readme.md"
                or "report" in name
                or "architecture" in name
                or "api" in name
                or normalized.startswith(("docs/", "documentation/"))
            )
        )


ChangeDetector = RepositoryChangeDetector

core/cluster/distributed_scheduler.py.content:
"""
distributed_scheduler.py - Distributed Task Scheduler & Rebalancer for AutoDev Cluster (v2.9)

Implements multi-strategy distributed scheduling (Round-Robin, Least-Loaded, Capability-Based,
Priority-Aware, Data-Locality, Dependency-Aware DAG execution), continuous rebalancing,
and dynamic work-stealing across heterogeneous cluster workers.
"""

from __future__ import annotations

import collections
import copy
import logging
import threading
import time
from typing import Any, Dict, List, Optional, Set, Tuple

from core.cluster.cluster_config import ClusterConfig
from core.cluster.cluster_state import NodeInfo, NodeRole, NodeStatus, TaskExecutionStatus, TaskSpec
from core.cluster.node_registry import NodeRegistry

logger = logging.getLogger("AutoDev.Cluster.Scheduler")


class DistributedScheduler:
    """
    Intelligent distributed scheduler for cluster task allocation and rebalancing.
    """

    def __init__(self, registry: NodeRegistry, config: Optional[ClusterConfig] = None) -> None:
        self.registry = registry
        self.config = config or ClusterConfig()
        self._lock = threading.RLock()
        self._rr_index: int = 0
        self._task_assignments: Dict[str, str] = {}  # task_id -> worker_id
        self._worker_active_counts: Dict[str, int] = collections.defaultdict(int)

        # Telemetry metrics
        self._total_scheduled = 0
        self._total_rebalanced = 0
        self._strategy_distribution: Dict[str, int] = collections.defaultdict(int)

    def select_worker(
        self,
        task: TaskSpec,
        strategy: Optional[str] = None,
        cached_node_artifacts: Optional[Dict[str, Set[str]]] = None,
    ) -> Optional[str]:
        """
        Selects the optimal worker ID for a task according to the selected strategy.
        """
        strat = (strategy or self.config.scheduler_strategy).lower()
        self._strategy_distribution[strat] += 1

        with self._lock:
            # 1. Candidate selection: must be worker, healthy/degraded, and have capacity
            candidates = self._get_eligible_candidates(task)
            if not candidates:
                logger.debug("No eligible workers available for task %s (caps: %s)", task.task_id, task.required_capabilities)
                return None

            if strat == "round_robin":
                return self._schedule_round_robin(candidates)
            elif strat == "least_loaded":
                return self._schedule_least_loaded(candidates)
            elif strat == "capability_based":
                return self._schedule_capability_based(candidates, task)
            elif strat == "priority_aware":
                return self._schedule_priority_aware(candidates, task)
            elif strat == "data_locality":
                return self._schedule_data_locality(candidates, task, cached_node_artifacts)
            elif strat == "dependency_aware":
                return self._schedule_least_loaded(candidates)
            else:
                return self._schedule_least_loaded(candidates)

    def _get_eligible_candidates(self, task: TaskSpec) -> List[NodeInfo]:
        all_workers = [
            n for n in self.registry.get_all_nodes()
            if n.role == NodeRole.WORKER
            and n.status in (NodeStatus.HEALTHY, NodeStatus.DEGRADED)
        ]

        eligible: List[NodeInfo] = []
        for w in all_workers:
            # Capacity check
            active = self._worker_active_counts[w.node_id]
            if active >= w.max_tasks:
                continue

            # Capability check
            if task.required_capabilities:
                w_caps = set(w.capabilities)
                if "general" not in w_caps and not all(c in w_caps for c in task.required_capabilities):
                    continue

            eligible.append(w)
        return eligible

    def _schedule_round_robin(self, candidates: List[NodeInfo]) -> str:
        idx = self._rr_index % len(candidates)
        self._rr_index += 1
        return candidates[idx].node_id

    def _schedule_least_loaded(self, candidates: List[NodeInfo]) -> str:
        # Sort by: (current active / max_tasks, cpu_utilization, -health_score)
        def load_score(n: NodeInfo) -> Tuple[float, float, float]:
            active = self._worker_active_counts[n.node_id]
            ratio = (active / n.max_tasks) if n.max_tasks > 0 else 1.0
            return (ratio, n.cpu_utilization, -n.health_score)

        sorted_cands = sorted(candidates, key=load_score)
        return sorted_cands[0].node_id

    def _schedule_capability_based(self, candidates: List[NodeInfo], task: TaskSpec) -> str:
        # Prioritize worker with exact matching capability count and lowest load
        def cap_score(n: NodeInfo) -> Tuple[int, float]:
            exact_matches = len(set(task.required_capabilities).intersection(set(n.capabilities)))
            active = self._worker_active_counts[n.node_id]
            return (-exact_matches, active)

        sorted_cands = sorted(candidates, key=cap_score)
        return sorted_cands[0].node_id

    def _schedule_priority_aware(self, candidates: List[NodeInfo], task: TaskSpec) -> str:
        # High priority tasks (lower task.priority number) routed to lowest CPU and highest health score
        def prio_cand_score(n: NodeInfo) -> Tuple[float, float]:
            active = self._worker_active_counts[n.node_id]
            return (n.cpu_utilization + (active * 10.0), -n.health_score)

        sorted_cands = sorted(candidates, key=prio_cand_score)
        return sorted_cands[0].node_id

    def _schedule_data_locality(
        self,
        candidates: List[NodeInfo],
        task: TaskSpec,
        cached_node_artifacts: Optional[Dict[str, Set[str]]] = None,
    ) -> str:
        locality_hints = set(task.locality_hints)
        if not locality_hints or not cached_node_artifacts:
            return self._schedule_least_loaded(candidates)

        # Worker with most locality hints cached
        def locality_score(n: NodeInfo) -> Tuple[int, float]:
            node_cached = cached_node_artifacts.get(n.node_id, set())
            overlap = len(locality_hints.intersection(node_cached))
            active = self._worker_active_counts[n.node_id]
            return (-overlap, active)

        sorted_cands = sorted(candidates, key=locality_score)
        return sorted_cands[0].node_id

    def assign_task(self, task: TaskSpec, worker_id: str) -> None:
        """Records task allocation in scheduler tracking."""
        with self._lock:
            self._task_assignments[task.task_id] = worker_id
            self._worker_active_counts[worker_id] += 1
            self._total_scheduled += 1
            task.assigned_worker_id = worker_id
            task.status = TaskExecutionStatus.SCHEDULED
            logger.debug("Scheduler assigned task %s to worker %s", task.task_id, worker_id)

    def release_task(self, task_id: str) -> None:
        """Frees worker capacity when task completes or fails."""
        with self._lock:
            worker_id = self._task_assignments.pop(task_id, None)
            if worker_id and self._worker_active_counts[worker_id] > 0:
                self._worker_active_counts[worker_id] -= 1

    def build_dependency_dag(self, tasks: List[TaskSpec]) -> Tuple[Dict[str, Set[str]], List[List[str]]]:
        """
        Builds DAG adjacency representation and Kahn's topological parallel execution waves.
        Raises ValueError if circular dependency is detected.
        """
        task_map = {t.task_id: t for t in tasks}
        in_degree: Dict[str, int] = {t.task_id: 0 for t in tasks}
        adj_graph: Dict[str, Set[str]] = {t.task_id: set() for t in tasks}

        for t in tasks:
            for dep in t.dependencies:
                if dep in task_map:
                    adj_graph[dep].add(t.task_id)
                    in_degree[t.task_id] += 1

        waves: List[List[str]] = []
        current_wave = [t_id for t_id, deg in in_degree.items() if deg == 0]

        visited_count = 0
        while current_wave:
            waves.append(sorted(current_wave))
            next_wave: List[str] = []
            for node in current_wave:
                visited_count += 1
                for neighbor in adj_graph[node]:
                    in_degree[neighbor] -= 1
                    if in_degree[neighbor] == 0:
                        next_wave.append(neighbor)
            current_wave = next_wave

        if visited_count < len(tasks):
            raise ValueError("Cycle detected in task dependencies; cannot form topological DAG")

        return adj_graph, waves

    def rebalance_cluster(self, queued_tasks: Dict[str, TaskSpec]) -> List[Tuple[str, str, str]]:
        """
        Continuous work-stealing and load rebalancing.
        If utilization variance across workers exceeds threshold, migrates tasks from overloaded to underutilized workers.
        Returns list of (task_id, source_worker, target_worker).
        """
        if not self.config.enable_work_stealing:
            return []

        with self._lock:
            workers = [
                n for n in self.registry.get_all_nodes()
                if n.role == NodeRole.WORKER and n.status == NodeStatus.HEALTHY
            ]
            if len(workers) < 2:
                return []

            # Compute load for each worker
            worker_loads: Dict[str, int] = {w.node_id: self._worker_active_counts[w.node_id] for w in workers}
            min_worker = min(workers, key=lambda w: worker_loads[w.node_id])
            max_worker = max(workers, key=lambda w: worker_loads[w.node_id])

            min_load = worker_loads[min_worker.node_id]
            max_load = worker_loads[max_worker.node_id]

            reassignments: List[Tuple[str, str, str]] = []

            if max_load >= 2 and (min_load == 0 or (max_load / max(1, min_load)) >= self.config.work_stealing_threshold_ratio):
                # Find queued tasks currently scheduled to max_worker
                for t_id, task in queued_tasks.items():
                    if task.status == TaskExecutionStatus.SCHEDULED and self._task_assignments.get(t_id) == max_worker.node_id:
                        # Check if min_worker satisfies task capabilities
                        if not task.required_capabilities or set(task.required_capabilities).issubset(set(min_worker.capabilities)) or "general" in min_worker.capabilities:
                            # Migrate task
                            self._task_assignments[t_id] = min_worker.node_id
                            self._worker_active_counts[max_worker.node_id] -= 1
                            self._worker_active_counts[min_worker.node_id] += 1
                            task.assigned_worker_id = min_worker.node_id
                            reassignments.append((t_id, max_worker.node_id, min_worker.node_id))
                            self._total_rebalanced += 1
                            logger.info("Work-stealing rebalanced task %s: %s -> %s", t_id, max_worker.node_id, min_worker.node_id)
                            break

            return reassignments

    def get_scheduler_stats(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "total_scheduled": self._total_scheduled,
                "total_rebalanced": self._total_rebalanced,
                "strategy_distribution": dict(self._strategy_distribution),
                "worker_active_counts": dict(self._worker_active_counts),
            }

core/code_quality_engine.py.content:
"""Deterministic static code-quality analysis using existing AutoDev analyzers."""

from __future__ import annotations

import ast
import os
from pathlib import Path
from typing import Any

from core.complexity_analyzer import ComplexityAnalyzer
from core.duplication_detector import DuplicationDetector
from core.symbol_graph import SymbolGraph


class CodeQualityEngine:
    """Summarizes complexity, coupling, cohesion, duplication, dead code, and boundaries."""

    IGNORED_DIRS = {".git", ".venv", "venv", "__pycache__", ".pytest_cache", "node_modules"}

    def __init__(self) -> None:
        self.complexity_analyzer = ComplexityAnalyzer()
        self.duplication_detector = DuplicationDetector()

    def analyze(
        self,
        project_root: str | Path,
        symbol_graph: SymbolGraph | None = None,
    ) -> dict[str, Any]:
        root = Path(project_root).resolve()
        contents: dict[str, str] = {}
        analysis_errors: list[dict[str, str]] = []
        for current, directories, filenames in os.walk(root):
            directories[:] = sorted(
                name for name in directories
                if name not in self.IGNORED_DIRS and not name.startswith(".venv-")
            )
            for filename in sorted(filenames):
                if not filename.endswith(".py"):
                    continue
                path = Path(current) / filename
                relative = path.relative_to(root).as_posix()
                try:
                    contents[relative] = path.read_text(encoding="utf-8")
                except (OSError, UnicodeError) as exc:
                    analysis_errors.append({
                        "file": relative,
                        "error": f"{type(exc).__name__}: {exc}",
                    })
                    continue

        parsed: dict[str, ast.Module] = {}
        for path, source in sorted(contents.items()):
            try:
                parsed[path] = ast.parse(source, filename=path)
            except SyntaxError as exc:
                analysis_errors.append({
                    "file": path,
                    "error": f"SyntaxError at line {exc.lineno}: {exc.msg}",
                })
        file_metrics = {
            path: self.complexity_analyzer.analyze_source(source, path).to_dict()
            for path, source in sorted(contents.items())
        }
        duplication_blocks, duplication_ratio = self.duplication_detector.scan_files(contents)
        dependencies: dict[str, set[str]] = {path: set() for path in contents}
        if symbol_graph is not None:
            for source, targets in symbol_graph.file_dependency_graph.items():
                if source in dependencies:
                    dependencies[source].update(target for target in targets if target in contents)
        else:
            for path, tree in parsed.items():
                for node in ast.walk(tree):
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            dependencies[path].add(alias.name.replace(".", "/") + ".py")
                    elif isinstance(node, ast.ImportFrom) and node.module:
                        dependencies[path].add(node.module.replace(".", "/") + ".py")

        coupling_values = [len(targets) for targets in dependencies.values()]
        coupling = sum(coupling_values) / len(coupling_values) if coupling_values else 0.0
        cohesion_values: list[float] = []
        references: dict[str, int] = {}
        for path, tree in parsed.items():
            for node in ast.walk(tree):
                if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
                    references[node.id] = references.get(node.id, 0) + 1
            for node in tree.body:
                if not isinstance(node, ast.ClassDef):
                    continue
                methods = [member for member in node.body if isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef))]
                state_sets = [self._self_attributes(method) for method in methods]
                if len(state_sets) < 2:
                    continue
                possible = len(state_sets) * (len(state_sets) - 1) / 2
                shared = sum(
                    bool(state_sets[left] & state_sets[right])
                    for left in range(len(state_sets))
                    for right in range(left + 1, len(state_sets))
                )
                cohesion_values.append(shared / possible if possible else 1.0)

        dead_code: list[str] = []
        high_complexity: list[dict[str, Any]] = []
        for path, source in contents.items():
            if path.startswith("tests/"):
                continue
            tree = parsed.get(path)
            if tree is None:
                continue
            metrics = file_metrics[path]
            if metrics["cyclomatic_complexity"] >= 20 or metrics["maintainability_index"] < 50:
                high_complexity.append({
                    "file": path,
                    "cyclomatic_complexity": metrics["cyclomatic_complexity"],
                    "maintainability_index": metrics["maintainability_index"],
                })
            for node in tree.body:
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    if (
                        node.name not in {"main", "__main__"}
                        and references.get(node.name, 0) == 0
                    ):
                        dead_code.append(f"{path}:{node.name}")

        violations = self._architecture_violations(dependencies)
        average_mi = (
            sum(float(item["maintainability_index"]) for item in file_metrics.values())
            / len(file_metrics)
            if file_metrics else 100.0
        )
        avg_cohesion = sum(cohesion_values) / len(cohesion_values) if cohesion_values else 1.0
        recommendations = []
        if high_complexity:
            recommendations.append("Simplify high-complexity modules and functions.")
        if coupling > 5:
            recommendations.append("Reduce module coupling by separating shared interfaces.")
        if avg_cohesion < 0.5:
            recommendations.append("Improve class cohesion by grouping related responsibilities.")
        if duplication_ratio > 5:
            recommendations.append("Consolidate repeated code behind shared helpers.")
        if dead_code:
            recommendations.append("Review possible dead-code candidates before removal.")
        if violations:
            recommendations.append("Correct imports that cross the declared architecture boundary.")
        return {
            "file_count": len(contents),
            "complexity": {
                "average_cyclomatic": round(
                    sum(item["cyclomatic_complexity"] for item in file_metrics.values()) / len(file_metrics),
                    2,
                ) if file_metrics else 0.0,
                "hotspots": sorted(high_complexity, key=lambda item: item["file"]),
            },
            "maintainability_index": round(average_mi, 2),
            "coupling": round(coupling, 2),
            "cohesion": round(avg_cohesion, 3),
            "duplication_ratio": duplication_ratio,
            "duplication_count": len(duplication_blocks),
            "dead_code_candidates": sorted(dead_code),
            "architecture_violations": sorted(violations),
            "complexity_hotspots": sorted(item["file"] for item in high_complexity),
            "recommendations": recommendations,
            "analysis_errors": sorted(analysis_errors, key=lambda item: (item["file"], item["error"])),
            "files": file_metrics,
        }

    @staticmethod
    def _self_attributes(method: ast.FunctionDef | ast.AsyncFunctionDef) -> set[str]:
        return {
            node.attr
            for node in ast.walk(method)
            if isinstance(node, ast.Attribute)
            and isinstance(node.value, ast.Name)
            and node.value.id == "self"
        }

    @staticmethod
    def _architecture_violations(dependencies: dict[str, set[str]]) -> list[str]:
        violations = []
        for source, targets in dependencies.items():
            if source.startswith("core/") and source != "core/orchestrator.py":
                for target in targets:
                    if target.startswith("agents/"):
                        violations.append(f"{source} imports higher-level module {target}")
        return violations

