    ],
}


@dataclass
class AgentCapacity:
    """Tracks active workload and task capacity for an agent."""
    agent_id: str
    role: AgentRole = AgentRole.GENERAL
    max_capacity_hours: float = 40.0
    current_workload_hours: float = 0.0
    assigned_task_ids: List[str] = field(default_factory=list)

    @property
    def allocated_hours(self) -> float:
        return self.current_workload_hours

    @allocated_hours.setter
    def allocated_hours(self, val: float):
        self.current_workload_hours = val

    @property
    def active_tasks(self) -> List[str]:
        return self.assigned_task_ids

    @property
    def utilization_pct(self) -> float:
        return min(100.0, (self.current_workload_hours / max(1.0, self.max_capacity_hours)) * 100.0)


class TaskAllocator:
    """
    Intelligent skill-affinity and workload-aware task assignment engine for specialized AI engineering agents.
    """

    def __init__(self, default_agents: Optional[List[Dict[str, Any]]] = None):
        self._lock = threading.RLock()
        self._capacities: Dict[str, AgentCapacity] = {}
        self._tasks: Dict[str, TaskAssignment] = {}
        self._completed_tasks: Set[str] = set()

        if default_agents:
            for ag in default_agents:
                self.register_agent_capacity(
                    agent_id=ag["agent_id"],
                    role=ag.get("role", AgentRole.GENERAL),
                    max_capacity_hours=ag.get("max_capacity_hours", 40.0),
                )
        else:
            self._register_default_organization_roster()

    def _register_default_organization_roster(self) -> None:
        """Registers a full default AI engineering team roster."""
        roster = [
            ("ArchitectureAgent", AgentRole.ARCHITECTURE),
            ("BackendAgent", AgentRole.BACKEND),
            ("FrontendAgent", AgentRole.FRONTEND),
            ("TestingAgent", AgentRole.TESTING),
            ("SecurityAgent", AgentRole.SECURITY),
            ("PerformanceAgent", AgentRole.PERFORMANCE),
            ("DocumentationAgent", AgentRole.DOCUMENTATION),
            ("ReleaseAgent", AgentRole.RELEASE),
        ]
        for aid, role in roster:
            self.register_agent_capacity(aid, role)

    def register_agent_capacity(
        self,
        agent_id: str,
        role: Union[AgentRole, str] = AgentRole.GENERAL,
        max_capacity_hours: float = 40.0,
    ) -> None:
        """Register or update capacity tracking for an agent."""
        if isinstance(role, str):
            try:
                role = AgentRole(role)
            except ValueError:
                role = AgentRole.GENERAL

        with self._lock:
            if agent_id not in self._capacities:
                self._capacities[agent_id] = AgentCapacity(
                    agent_id=agent_id,
                    role=role,
                    max_capacity_hours=max_capacity_hours,
                )
            else:
                self._capacities[agent_id].role = role
                self._capacities[agent_id].max_capacity_hours = max_capacity_hours

    # Alias for backwards compatibility
    register_agent = register_agent_capacity

    def get_capacity(self, agent_id: str) -> Optional[AgentCapacity]:
        with self._lock:
            return self._capacities.get(agent_id)

    def get_capacities(self) -> Dict[str, AgentCapacity]:
        with self._lock:
            return dict(self._capacities)

    def get_registered_agents(self) -> List[Dict[str, Any]]:
        with self._lock:
            return [
                {
                    "agent_id": cap.agent_id,
                    "role": cap.role,
                    "max_capacity_hours": cap.max_capacity_hours,
                    "allocated_hours": cap.current_workload_hours,
                    "active_tasks": list(cap.assigned_task_ids),
                }
                for cap in self._capacities.values()
            ]

    def get_agent_workload(self, agent_id: str) -> Dict[str, Any]:
        with self._lock:
            cap = self._capacities.get(agent_id)
            if not cap:
                return {"allocated_hours": 0.0, "utilization_pct": 0.0, "active_tasks": []}
            return {
                "allocated_hours": cap.current_workload_hours,
                "utilization_pct": cap.utilization_pct,
                "active_tasks": list(cap.assigned_task_ids),
            }

    # ------------------------------------------------------------------
    # Task Management
    # ------------------------------------------------------------------

    def submit_task(self, task: Union[TaskAssignment, Dict[str, Any]]) -> TaskAssignment:
        """Register a task into the allocator store."""
        t_obj = task if isinstance(task, TaskAssignment) else TaskAssignment(**task)
        with self._lock:
            self._tasks[t_obj.task_id] = t_obj
        return t_obj

    def submit_tasks(self, tasks: List[Union[TaskAssignment, Dict[str, Any]]]) -> List[TaskAssignment]:
        """Register multiple tasks."""
        return [self.submit_task(t) for t in tasks]

    def get_task(self, task_id: str) -> Optional[TaskAssignment]:
        with self._lock:
            return self._tasks.get(task_id)

    def get_all_tasks(self) -> List[TaskAssignment]:
        with self._lock:
            return list(self._tasks.values())

    # ------------------------------------------------------------------
    # Scoring & Allocation
    # ------------------------------------------------------------------

    def _score_agent_for_task(self, capacity: Optional[AgentCapacity], task: TaskAssignment) -> float:
        """Compute matching affinity score for an agent capacity and task."""
        if not capacity:
            return 0.0

        title = task.title.lower()
        desc = task.description.lower()
        req_skills = [s.lower() for s in task.required_skills]
        files = [f.lower() for f in task.estimated_files]
        combined = f"{title} {desc} {' '.join(req_skills)} {' '.join(files)}"

        patterns = ROLE_SKILL_PATTERNS.get(capacity.role, [])
        matches = 0
        for pat in patterns:
            if pat in combined:
                matches += 2

        for skill in req_skills:
            if any(pat in skill or skill in pat for pat in patterns):
                matches += 5

        # Direct role name match
        role_name = capacity.role.value.lower()
        if role_name in title or any(role_name in s for s in req_skills):
            matches += 5

        # Workload penalty (0 to -0.3)
        workload_ratio = capacity.current_workload_hours / max(1.0, capacity.max_capacity_hours)
        base_score = matches / 2.0
        return max(0.01, base_score - (workload_ratio * 0.2))

    def match_skills(self, task: Union[TaskAssignment, Dict[str, Any]]) -> Tuple[AgentRole, float]:
        """Determine the optimal AgentRole for a task."""
        t_obj = task if isinstance(task, TaskAssignment) else TaskAssignment(**task)
        best_role = AgentRole.BACKEND
        best_score = -1.0

        for aid, cap in self._capacities.items():
            score = self._score_agent_for_task(cap, t_obj)
            if score > best_score:
                best_score = score
                best_role = cap.role

        return best_role, round(max(0.1, best_score), 2)

    def allocate_task(
        self,
        task_or_id: Union[str, TaskAssignment, Dict[str, Any]],
        preferred_agent_id: Optional[str] = None,
    ) -> Optional[TaskAssignment]:
        """Assign a task to the best-matching agent."""
        with self._lock:
            if isinstance(task_or_id, str):
                task = self._tasks.get(task_or_id)
                if not task:
                    task = TaskAssignment(task_id=task_or_id, title=task_or_id)
                    self._tasks[task_or_id] = task
            elif isinstance(task_or_id, TaskAssignment):
                task = task_or_id
                self._tasks[task.task_id] = task
            else:
                task = TaskAssignment(**task_or_id)
                self._tasks[task.task_id] = task

            chosen_agent_id = preferred_agent_id
            chosen_role = None

            if chosen_agent_id and chosen_agent_id in self._capacities:
                chosen_role = self._capacities[chosen_agent_id].role
            else:
                best_score = -1.0
                best_agent_id = "BackendAgent"
                for aid, cap in self._capacities.items():
                    score = self._score_agent_for_task(cap, task)
                    if score > best_score:
                        best_score = score
                        best_agent_id = aid

                chosen_agent_id = best_agent_id
                chosen_role = self._capacities[chosen_agent_id].role

            # Update assignment
            task.assigned_agent = chosen_agent_id
            task.assigned_role = chosen_role
            task.status = TaskStatus.ASSIGNED

            # Update capacity
            cap = self._capacities[chosen_agent_id]
            if task.task_id not in cap.assigned_task_ids:
                cap.assigned_task_ids.append(task.task_id)
                cap.current_workload_hours += task.estimated_hours

            logger.info("Allocated task '%s' -> %s (%s)", task.task_id, chosen_agent_id, chosen_role.value if chosen_role else "general")
            return task

    def allocate_all(self) -> List[TaskAssignment]:
        """Sort tasks by priority and allocate all pending tasks."""
        with self._lock:
            # Sort critical/high priority first
            sorted_tasks = sorted(
                self._tasks.values(),
                key=lambda t: int(t.priority) if hasattr(t.priority, "value") else 2,
                reverse=True,
            )
            allocations = []
            for t in sorted_tasks:
                if t.status in (TaskStatus.PENDING, TaskStatus.ASSIGNED):
                    allocations.append(self.allocate_task(t))
            return allocations

    def reassign_task(self, task_id: str, target_agent_id: str) -> bool:
        """Reassign an active task from one agent to another."""
        with self._lock:
            task = self._tasks.get(task_id)
            if not task or target_agent_id not in self._capacities:
                return False

            old_agent = task.assigned_agent
            if old_agent and old_agent in self._capacities:
                old_cap = self._capacities[old_agent]
                if task_id in old_cap.assigned_task_ids:
                    old_cap.assigned_task_ids.remove(task_id)
                    old_cap.current_workload_hours = max(0.0, old_cap.current_workload_hours - task.estimated_hours)

            new_cap = self._capacities[target_agent_id]
            if task_id not in new_cap.assigned_task_ids:
                new_cap.assigned_task_ids.append(task_id)
                new_cap.current_workload_hours += task.estimated_hours

            task.assigned_agent = target_agent_id
            task.assigned_role = new_cap.role
            task.status = TaskStatus.REASSIGNED
            return True

    def complete_task(self, task_id: str) -> bool:
        """Mark task as completed and free allocated agent workload hours."""
        with self._lock:
            task = self._tasks.get(task_id)
            if not task:
                return False

            task.status = TaskStatus.COMPLETED
            self._completed_tasks.add(task_id)

            agent_id = task.assigned_agent
            if agent_id and agent_id in self._capacities:
                cap = self._capacities[agent_id]
                if task_id in cap.assigned_task_ids:
                    cap.assigned_task_ids.remove(task_id)
                    cap.current_workload_hours = max(0.0, cap.current_workload_hours - task.estimated_hours)

            return True

    def get_allocation_stats(self) -> Dict[str, Any]:
        """Aggregate allocation statistics."""
        with self._lock:
            assigned = [t for t in self._tasks.values() if t.status in (TaskStatus.ASSIGNED, TaskStatus.IN_PROGRESS, TaskStatus.REASSIGNED)]
            completed = list(self._completed_tasks)
            agent_util = {aid: cap.utilization_pct for aid, cap in self._capacities.items()}

            return {
                "total_tasks": len(self._tasks),
                "assigned_tasks": len(assigned),
                "completed_tasks": len(completed),
                "agent_utilization": agent_util,
            }

core/collaboration_engine.py.content:
"""Opt-in task collaboration using safe planning and deterministic scheduling."""

from __future__ import annotations

import threading
from typing import Any, Callable, Mapping, Optional

from core.execution_scheduler import ExecutionScheduler, ScheduledTask
from core.multi_agent_runtime import MultiAgentRuntime
from core.planning_revision import PlanningRevisionEngine


class CollaborationEngine:
    """Coordinates dependencies, agent assignment, progress, and completion events."""

    def __init__(
        self,
        runtime: Optional[MultiAgentRuntime] = None,
        scheduler: Optional[ExecutionScheduler] = None,
        planning_engine: Optional[PlanningRevisionEngine] = None,
    ) -> None:
        self.runtime = runtime
        self.scheduler = scheduler or ExecutionScheduler()
        self.planning_engine = planning_engine or PlanningRevisionEngine()
        self._lock = threading.RLock()
        self._progress: dict[str, dict[str, Any]] = {}
        self._barriers: dict[str, threading.Barrier] = {}

    def plan(self, tasks: Any) -> dict[str, Any]:
        revision = self.planning_engine.optimize(tasks)
        task_list = revision.tasks.get("tasks", []) if isinstance(revision.tasks, dict) else revision.tasks
        with self._lock:
            for task in task_list:
                task_id = self._get(task, "id", self._get(task, "task_id", ""))
                if task_id:
                    self._progress.setdefault(str(task_id), {"status": "planned", "result": None})
        return revision.to_dict()

    def execute(
        self,
        tasks: Any,
        handlers: Optional[Mapping[str, Callable[[Any], Any]]] = None,
        max_workers: Optional[int] = None,
    ) -> dict[str, Any]:
        task_list = tasks.get("tasks", []) if isinstance(tasks, dict) else tasks
        task_list = list(task_list or [])
        if max_workers is not None:
            scheduler = ExecutionScheduler(max_workers=max_workers)
        else:
            scheduler = self.scheduler
        handlers = handlers or {}
        ids = {
            str(self._get(task, "id", self._get(task, "task_id", ""))): task
            for task in task_list
        }
        scheduled = []
        for task_id in sorted(ids):
            task = ids[task_id]
            fn = handlers.get(task_id) or self._get(task, "function")
            if not callable(fn):
                raise ValueError(f"No callable handler provided for task {task_id!r}")
            dependency_values = self._get(task, "dependencies", []) or []
            if isinstance(dependency_values, str):
                dependency_values = [dependency_values]
            resource_values = self._get(
                task,
                "resources",
                self._get(task, "estimated_files", []),
            ) or []
            if isinstance(resource_values, str):
                resource_values = [resource_values]
            dependencies = set(str(item) for item in dependency_values)
            resources = set(str(item) for item in resource_values)
            def runner(task_obj: Any = task, handler: Callable[[Any], Any] = fn, key: str = task_id) -> Any:
                with self._lock:
                    self._progress[key] = {"status": "running", "result": None}
                result = handler(task_obj)
                with self._lock:
                    self._progress[key] = {"status": "completed", "result": result}
                if self.runtime is not None:
                    self.runtime.broadcast(
                        "collaboration_engine",
                        {"event": "TASK_COMPLETED", "task_id": key, "status": "completed"},
                    )
                return result
            scheduled.append(ScheduledTask(
                task_id=task_id,
                function=runner,
                dependencies=dependencies,
                resources=resources,
            ))
        return scheduler.execute(scheduled)

    def progress(self) -> dict[str, dict[str, Any]]:
        with self._lock:
            return {key: dict(self._progress[key]) for key in sorted(self._progress)}

    def notify_completion(self, task_id: str, result: Any = None, success: bool = True) -> None:
        with self._lock:
            self._progress[task_id] = {
                "status": "completed" if success else "failed",
                "result": result,
            }
        if self.runtime is not None:
            self.runtime.broadcast(
                "collaboration_engine",
                {
                    "event": "TASK_COMPLETED" if success else "TASK_FAILED",
                    "task_id": task_id,
                    "status": "completed" if success else "failed",
                },
            )

    def synchronize(self, barrier_id: str, parties: int, timeout: Optional[float] = None) -> bool:
        if parties < 1:
            raise ValueError("parties must be at least one")
        with self._lock:
            barrier = self._barriers.setdefault(barrier_id, threading.Barrier(parties))
        try:
            barrier.wait(timeout=timeout)
            return True
        except threading.BrokenBarrierError:
            return False

    @staticmethod
    def _get(value: Any, name: str, default: Any = None) -> Any:
        return value.get(name, default) if isinstance(value, dict) else getattr(value, name, default)

core/conflict_resolution.py.content:
"""Deterministic conflict detection and policy-driven resolution."""

from __future__ import annotations

import hashlib
import threading
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Mapping, Optional


class ConflictKind(str, Enum):
    FILE_OWNERSHIP = "file_ownership"
    PARALLEL_EDIT = "parallel_edit"
    RESOURCE_CONTENTION = "resource_contention"
    CONTRADICTING_DECISION = "contradicting_decision"
    ARCHITECTURE_DISAGREEMENT = "architecture_disagreement"


@dataclass
class CollaborationConflict:
    conflict_id: str
    kind: ConflictKind
    resource: str
    participants: list[str]
    details: dict[str, Any] = field(default_factory=dict)
    resolved: bool = False
    winner: Optional[str] = None
    resolution: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {
            "conflict_id": self.conflict_id,
            "kind": self.kind.value,
            "resource": self.resource,
            "participants": list(self.participants),
            "details": dict(self.details),
            "resolved": self.resolved,
            "winner": self.winner,
            "resolution": self.resolution,
        }


class ConflictResolutionEngine:
    """Detects concurrent resource/decision conflicts and resolves them by stable policy."""

    POLICIES = {"first_agent", "highest_priority", "prefer_agent", "consensus", "reject"}

    def __init__(
        self,
        policy: str = "highest_priority",
        preferred_agent: Optional[str] = None,
    ) -> None:
        if policy not in self.POLICIES:
            raise ValueError(f"Unsupported conflict policy: {policy}")
        self.policy = policy
        self.preferred_agent = preferred_agent
        self._lock = threading.RLock()
        self._conflicts: dict[str, CollaborationConflict] = {}

    def detect_conflicts(
        self,
        tasks: Optional[list[Any]] = None,
        decisions: Optional[Mapping[str, Mapping[str, Any]]] = None,
    ) -> list[CollaborationConflict]:
        found: list[CollaborationConflict] = []
        resource_owners: dict[str, list[tuple[str, Any]]] = {}
        for task in tasks or []:
            agent = str(self._get(task, "agent_id", self._get(task, "assigned_agent_id", "")))
            resources = self._get(
                task,
                "files",
                self._get(task, "resources", self._get(task, "estimated_files", [])),
            )
            if isinstance(resources, str):
                resources = [resources]
            for resource in sorted({str(item) for item in resources or []}):
                resource_owners.setdefault(resource, []).append((agent, task))
        for resource, owners in sorted(resource_owners.items()):
            participants = sorted({agent for agent, _ in owners if agent})
            if len(participants) > 1:
                found.append(self._create(
                    ConflictKind.FILE_OWNERSHIP,
                    resource,
                    participants,
                    {"tasks": sorted(str(self._get(task, "id", self._get(task, "task_id", ""))) for _, task in owners)},
                ))
        for resource, owners in sorted(resource_owners.items()):
            participants = sorted({agent for agent, _ in owners if agent})
            if len(owners) > 1 and len(participants) > 1:
                found.append(self._create(
                    ConflictKind.RESOURCE_CONTENTION,
                    resource,
                    participants,
                    {"task_count": len(owners)},
                ))
        if decisions:
            values: dict[str, dict[str, list[str]]] = {}
            for agent, proposal in sorted(decisions.items()):
                for key, value in sorted(proposal.items()):
                    values.setdefault(str(key), {}).setdefault(str(value), []).append(str(agent))
            for key, proposals in sorted(values.items()):
                if len(proposals) > 1:
                    participants = sorted({agent for agents in proposals.values() for agent in agents})
                    found.append(self._create(
                        ConflictKind.ARCHITECTURE_DISAGREEMENT,
                        key,
                        participants,
                        {"proposals": {value: sorted(agents) for value, agents in sorted(proposals.items())}},
                    ))
                    found.append(self._create(
                        ConflictKind.CONTRADICTING_DECISION,
                        key,
                        participants,
                        {"proposals": {value: sorted(agents) for value, agents in sorted(proposals.items())}},
                    ))
        with self._lock:
            for conflict in found:
                self._conflicts[conflict.conflict_id] = conflict
        return sorted(found, key=lambda conflict: (conflict.kind.value, conflict.resource, conflict.conflict_id))

    def resolve(
        self,
        conflict: CollaborationConflict | str,
        policy: Optional[str] = None,
        priorities: Optional[Mapping[str, float]] = None,
    ) -> CollaborationConflict:
        record = self._conflicts.get(conflict) if isinstance(conflict, str) else conflict
        if record is None:
            raise KeyError(f"Unknown conflict: {conflict}")
        selected_policy = policy or self.policy
        if selected_policy not in self.POLICIES:
            raise ValueError(f"Unsupported conflict policy: {selected_policy}")
        if record.resolved:
            return record
        participants = sorted(record.participants)
        winner: Optional[str] = None
        if selected_policy == "first_agent":
            winner = participants[0] if participants else None
        elif selected_policy == "highest_priority":
            scores = priorities or {}
            winner = min(participants, key=lambda item: (-float(scores.get(item, 0.0)), item)) if participants else None
        elif selected_policy == "prefer_agent":
            if self.preferred_agent not in participants:
                raise ValueError("preferred_agent must be one of the conflict participants")
            winner = self.preferred_agent
        elif selected_policy == "consensus":
            record.resolution = "escalated_to_consensus"
            return record
        else:
            record.resolution = "all_proposals_rejected"
        record.winner = winner
        record.resolved = selected_policy != "consensus"
        if selected_policy not in {"consensus", "reject"}:
            record.resolution = f"selected {winner} using {selected_policy}"
        with self._lock:
            self._conflicts[record.conflict_id] = record
        return record

    def conflicts(self) -> list[CollaborationConflict]:
        with self._lock:
            return [self._conflicts[key] for key in sorted(self._conflicts)]

    @staticmethod
    def _get(value: Any, name: str, default: Any = None) -> Any:
        return value.get(name, default) if isinstance(value, Mapping) else getattr(value, name, default)

    @staticmethod
    def _create(
        kind: ConflictKind,
        resource: str,
        participants: list[str],
        details: dict[str, Any],
    ) -> CollaborationConflict:
        material = repr((kind.value, resource, participants, sorted(details.items())))
        digest = hashlib.sha256(material.encode("utf-8")).hexdigest()[:16]
        return CollaborationConflict(
            conflict_id=f"conflict-{digest}",
            kind=kind,
            resource=resource,
            participants=participants,
            details=details,
        )

core/consensus_protocol.py.content:
"""
consensus_protocol.py - Consensus Wire Protocol & Fencing Models for AutoDev (v2.4)

Defines coordinator lifecycle states, monotonically increasing fencing tokens,
peer node descriptors, election messages, and consensus protocol schemas.
"""

from __future__ import annotations

from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from enum import Enum
import time
from typing import Any, Dict, List, Optional, Set


class CoordinatorRole(str, Enum):
    """Lifecycle role of a coordinator instance in an HA cluster."""
    STARTING = "STARTING"
    FOLLOWER = "FOLLOWER"
    CANDIDATE = "CANDIDATE"
    LEADER = "LEADER"
    DEGRADED = "DEGRADED"
    UNAVAILABLE = "UNAVAILABLE"
    STOPPING = "STOPPING"


@dataclass
class FencingToken:
    """
    Monotonically increasing fencing generation token ensuring single-writer
    safety across leader failovers. Stale leaders with outdated generation numbers
    are rejected by workers and storage layers.
    """
    term: int
    leader_id: str
    fencing_generation: int
    issued_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    expires_at_timestamp: float = field(default_factory=lambda: time.time() + 15.0)

    @property
    def is_expired(self) -> bool:
        """Returns True if the fencing token has exceeded its lease duration."""
        return time.time() > self.expires_at_timestamp

    def is_valid_for(self, expected_term: int, expected_generation: int) -> bool:
        """Validates that this token matches or exceeds the required term and generation."""
        if self.is_expired:
            return False
        return self.term >= expected_term and self.fencing_generation >= expected_generation

    def to_dict(self) -> Dict[str, Any]:
        return {
            "term": self.term,
            "leader_id": self.leader_id,
            "fencing_generation": self.fencing_generation,
            "issued_at": self.issued_at,
            "expires_at_timestamp": self.expires_at_timestamp,
            "is_expired": self.is_expired,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> FencingToken:
        return cls(
            term=int(data["term"]),
            leader_id=str(data["leader_id"]),
            fencing_generation=int(data["fencing_generation"]),
            issued_at=str(data.get("issued_at", datetime.now(timezone.utc).isoformat())),
            expires_at_timestamp=float(data.get("expires_at_timestamp", time.time() + 15.0)),
        )


@dataclass
class CoordinatorNode:
    """Operational state and connection metadata for a coordinator node."""
    coordinator_id: str
    host: str = "127.0.0.1"
    port: int = 50051
    role: CoordinatorRole = CoordinatorRole.STARTING
    current_term: int = 0
    last_heartbeat_timestamp: float = field(default_factory=time.time)
    last_heartbeat_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    is_active: bool = True
    metadata: Dict[str, Any] = field(default_factory=dict)

    @property
    def is_alive(self) -> bool:
        return self.is_active and (time.time() - self.last_heartbeat_timestamp) < 15.0

    def to_dict(self) -> Dict[str, Any]:
        return {
            "coordinator_id": self.coordinator_id,
            "host": self.host,
            "port": self.port,
            "role": self.role.value if isinstance(self.role, CoordinatorRole) else str(self.role),
            "current_term": self.current_term,
            "last_heartbeat_timestamp": self.last_heartbeat_timestamp,
            "last_heartbeat_at": self.last_heartbeat_at,
            "is_active": self.is_active,
            "is_alive": self.is_alive,
            "metadata": self.metadata,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> CoordinatorNode:
        role_raw = data.get("role", "STARTING")
        try:
            role = CoordinatorRole(role_raw)
        except ValueError:
            role = CoordinatorRole.STARTING
        return cls(
            coordinator_id=str(data["coordinator_id"]),
            host=str(data.get("host", "127.0.0.1")),
            port=int(data.get("port", 50051)),
            role=role,
            current_term=int(data.get("current_term", 0)),
            last_heartbeat_timestamp=float(data.get("last_heartbeat_timestamp", time.time())),
            last_heartbeat_at=str(data.get("last_heartbeat_at", datetime.now(timezone.utc).isoformat())),
            is_active=bool(data.get("is_active", True)),
            metadata=dict(data.get("metadata", {})),
        )


@dataclass
class VoteRequest:
    """Message sent by candidate coordinator requesting peer votes."""
    term: int
    candidate_id: str
    last_log_index: int = 0
    last_log_term: int = 0

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> VoteRequest:
        return cls(
            term=int(data["term"]),
            candidate_id=str(data["candidate_id"]),
            last_log_index=int(data.get("last_log_index", 0)),
            last_log_term=int(data.get("last_log_term", 0)),
        )


@dataclass
class VoteResponse:
    """Message returned by peer node in response to VoteRequest."""
    term: int
    vote_granted: bool
    voter_id: str
    fencing_token: Optional[FencingToken] = None
    reason: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        res = asdict(self)
        res["fencing_token"] = self.fencing_token.to_dict() if self.fencing_token else None
        return res

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> VoteResponse:
        f_tok = None
        if data.get("fencing_token"):
            f_tok = FencingToken.from_dict(data["fencing_token"])
        return cls(
            term=int(data["term"]),
            vote_granted=bool(data["vote_granted"]),
            voter_id=str(data["voter_id"]),
            fencing_token=f_tok,
            reason=data.get("reason"),
        )


@dataclass
class ConsensusHeartbeat:
    """Periodic heartbeat broadcasted by leader coordinator to maintain quorum."""
    term: int
    leader_id: str
    fencing_generation: int
    lease_ttl_seconds: float = 5.0
    timestamp: float = field(default_factory=time.time)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> ConsensusHeartbeat:
        return cls(
            term=int(data["term"]),
            leader_id=str(data["leader_id"]),
            fencing_generation=int(data["fencing_generation"]),
            lease_ttl_seconds=float(data.get("lease_ttl_seconds", 5.0)),
            timestamp=float(data.get("timestamp", time.time())),
        )

core/continuous_improvement.py.content:
"""Evidence-ranked roadmap combining all AutoDev improvement signals."""

from __future__ import annotations

import hashlib
import json
from typing import Any, Mapping


class ContinuousImprovementEngine:
    """Combines research, architecture, performance, learning, and delivery evidence."""

    SOURCE_KEYS = (
        "research",
        "architecture",
        "performance",
        "learning",
        "reflection",
        "analytics",
        "engineering",
    )

    def generate_roadmap(self, **sources: Mapping[str, Any] | None) -> dict[str, Any]:
        items_by_key: dict[str, dict[str, Any]] = {}
        summaries: dict[str, Any] = {}
        for source_name in self.SOURCE_KEYS:
            source = sources.get(source_name) or {}
            summaries[source_name] = self._source_summary(source)
            recommendations = source.get("recommendations", [])
            if isinstance(source.get("roadmap"), list):
                recommendations = list(recommendations) + source["roadmap"]
            if source_name == "research" and source.get("goal"):
                recommendations = list(recommendations) + [{
                    "title": source["goal"],
                    "priority": source.get("severity", "medium"),
                    "evidence": source.get("evidence", {}),
                }]
            for recommendation in recommendations if isinstance(recommendations, list) else []:
                item = self._normalize(source_name, recommendation)
                if item is None:
                    continue
                key = item["title"].casefold()
                existing = items_by_key.get(key)
                if existing is None:
                    items_by_key[key] = item
                else:
                    existing["sources"] = sorted(set(existing["sources"]) | {source_name})
                    existing["evidence"].extend(item["evidence"])
                    existing["priority_score"] = max(existing["priority_score"], item["priority_score"])

        roadmap = sorted(
            items_by_key.values(),
            key=lambda item: (-item["priority_score"], item["title"].casefold(), item["item_id"]),
        )
        for item in roadmap:
            item["sources"] = sorted(set(item["sources"]))
            item["evidence"] = sorted(item["evidence"], key=lambda value: json.dumps(value, sort_keys=True, default=str))
        return {"roadmap": roadmap, "source_summaries": summaries}

    @staticmethod
    def _source_summary(source: Mapping[str, Any]) -> dict[str, Any]:
        return {
            "recommendation_count": len(source.get("recommendations", []))
            if isinstance(source.get("recommendations", []), list) else 0,
            "available": bool(source),
        }

    @staticmethod
    def _normalize(source: str, value: Any) -> dict[str, Any] | None:
        if isinstance(value, str):
            title = value.strip()
            priority = "medium"
            evidence: Any = {}
        elif isinstance(value, Mapping):
            title = str(value.get("title", value.get("action", ""))).strip()
            priority = str(value.get("priority", "medium")).lower()
            evidence = value.get("evidence", {})
        else:
            return None
        if not title:
            return None
        score = {"critical": 4, "high": 3, "medium": 2, "low": 1}.get(priority, 2)
        payload = json.dumps([title, source], sort_keys=True, default=str)
        return {
            "item_id": hashlib.sha256(payload.encode("utf-8")).hexdigest()[:16],
            "title": title,
            "priority": priority,
            "priority_score": score,
            "sources": [source],
            "evidence": [evidence] if evidence else [],
            "status": "proposed",
        }

core/coordination_store.py.content:
"""
coordination_store.py - Durable State Persistence & Coordination Backend for AutoDev (v2.3)

Provides pluggable coordination state backends (Memory and SQLite) for persisting worker registrations,
task leases, idempotency tokens, and task attempt histories across coordinator restarts.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
import json
import logging
import os
from pathlib import Path
import sqlite3
import threading
from typing import Any, Dict, List, Optional, Set, Tuple, Union

logger = logging.getLogger("AutoDev.CoordinationStore")


class CoordinationStoreError(Exception):
    """Base exception for coordination storage errors."""
    pass


class CoordinationStore(ABC):
    """Abstract interface for distributed worker coordination persistence."""

    @abstractmethod
    def save_worker(self, worker_id: str, worker_data: Dict[str, Any]) -> None:
        pass

    @abstractmethod
    def get_worker(self, worker_id: str) -> Optional[Dict[str, Any]]:
        pass

    @abstractmethod
    def list_workers(self) -> List[Dict[str, Any]]:
        pass

    @abstractmethod
    def delete_worker(self, worker_id: str) -> None:
        pass

    @abstractmethod
    def save_lease(self, operation_id: str, lease_data: Dict[str, Any]) -> None:
        pass

    @abstractmethod
    def get_lease(self, operation_id: str) -> Optional[Dict[str, Any]]:
        pass

    @abstractmethod
    def list_leases(self) -> List[Dict[str, Any]]:
        pass

    @abstractmethod
    def delete_lease(self, operation_id: str) -> None:
        pass

    @abstractmethod
    def save_idempotency_record(self, key: str, value: Dict[str, Any]) -> None:
        pass

    @abstractmethod
    def get_idempotency_record(self, key: str) -> Optional[Dict[str, Any]]:
        pass

    @abstractmethod
    def save_coordinator(self, coordinator_id: str, data: Dict[str, Any]) -> None:
        pass

    @abstractmethod
    def get_coordinator(self, coordinator_id: str) -> Optional[Dict[str, Any]]:
        pass

    @abstractmethod
    def list_coordinators(self) -> List[Dict[str, Any]]:
        pass

    @abstractmethod
    def save_leadership(self, term: int, leader_id: str, fencing_generation: int, expires_at: float) -> None:
        pass

    @abstractmethod
    def get_leadership(self) -> Optional[Dict[str, Any]]:
        pass

    @abstractmethod
    def close(self) -> None:
        pass


class MemoryCoordinationStore(CoordinationStore):
    """Thread-safe in-memory coordination store for fast execution and testing."""

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._workers: Dict[str, Dict[str, Any]] = {}
        self._leases: Dict[str, Dict[str, Any]] = {}
        self._idempotency: Dict[str, Dict[str, Any]] = {}
        self._coordinators: Dict[str, Dict[str, Any]] = {}
        self._leadership: Optional[Dict[str, Any]] = None

    def save_worker(self, worker_id: str, worker_data: Dict[str, Any]) -> None:
        with self._lock:
            self._workers[worker_id] = dict(worker_data)

    def get_worker(self, worker_id: str) -> Optional[Dict[str, Any]]:
        with self._lock:
            data = self._workers.get(worker_id)
            return dict(data) if data is not None else None

    def list_workers(self) -> List[Dict[str, Any]]:
        with self._lock:
            return [dict(v) for v in self._workers.values()]

    def delete_worker(self, worker_id: str) -> None:
        with self._lock:
            self._workers.pop(worker_id, None)

    def save_lease(self, operation_id: str, lease_data: Dict[str, Any]) -> None:
        with self._lock:
            self._leases[operation_id] = dict(lease_data)

    def get_lease(self, operation_id: str) -> Optional[Dict[str, Any]]:
        with self._lock:
            data = self._leases.get(operation_id)
            return dict(data) if data is not None else None

    def list_leases(self) -> List[Dict[str, Any]]:
        with self._lock:
            return [dict(v) for v in self._leases.values()]

    def delete_lease(self, operation_id: str) -> None:
        with self._lock:
            self._leases.pop(operation_id, None)

    def save_idempotency_record(self, key: str, value: Dict[str, Any]) -> None:
        with self._lock:
            self._idempotency[key] = dict(value)

    def get_idempotency_record(self, key: str) -> Optional[Dict[str, Any]]:
        with self._lock:
            data = self._idempotency.get(key)
            return dict(data) if data is not None else None

    def save_coordinator(self, coordinator_id: str, data: Dict[str, Any]) -> None:
        with self._lock:
            self._coordinators[coordinator_id] = dict(data)

    def get_coordinator(self, coordinator_id: str) -> Optional[Dict[str, Any]]:
        with self._lock:
            data = self._coordinators.get(coordinator_id)
            return dict(data) if data is not None else None

    def list_coordinators(self) -> List[Dict[str, Any]]:
        with self._lock:
            return [dict(v) for v in self._coordinators.values()]

    def save_leadership(self, term: int, leader_id: str, fencing_generation: int, expires_at: float) -> None:
        with self._lock:
            self._leadership = {
                "term": term,
                "leader_id": leader_id,
                "fencing_generation": fencing_generation,
                "expires_at": expires_at,
                "updated_at": datetime.now(timezone.utc).isoformat(),
            }

    def get_leadership(self) -> Optional[Dict[str, Any]]:
        with self._lock:
            return dict(self._leadership) if self._leadership else None

    def close(self) -> None:
        with self._lock:
            self._workers.clear()
            self._leases.clear()
            self._idempotency.clear()
            self._coordinators.clear()
            self._leadership = None


class SqliteCoordinationStore(CoordinationStore):
    """
    Durable SQLite-backed coordination store persisting worker metadata,
    task leases, and idempotency tokens across coordinator restarts.
    """

    def __init__(self, db_path: Union[str, Path] = "memory/coordination.db") -> None:
        self.db_path = Path(db_path).resolve()
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        self._lock = threading.RLock()
        self._conn = sqlite3.connect(str(self.db_path), check_same_thread=False)
        self._conn.row_factory = sqlite3.Row
        self._init_schema()

    def _init_schema(self) -> None:
        with self._lock:
            with self._conn:
                self._conn.execute("""
                    CREATE TABLE IF NOT EXISTS workers (
                        worker_id TEXT PRIMARY KEY,
                        data_json TEXT NOT NULL,
                        updated_at TEXT NOT NULL
                    )
                """)
                self._conn.execute("""
                    CREATE TABLE IF NOT EXISTS leases (
                        operation_id TEXT PRIMARY KEY,
                        data_json TEXT NOT NULL,
                        updated_at TEXT NOT NULL
                    )
                """)
                self._conn.execute("""
                    CREATE TABLE IF NOT EXISTS idempotency_records (
                        record_key TEXT PRIMARY KEY,
                        data_json TEXT NOT NULL,
                        created_at TEXT NOT NULL
                    )
                """)
                self._conn.execute("""
                    CREATE TABLE IF NOT EXISTS coordinators (
                        coordinator_id TEXT PRIMARY KEY,
                        data_json TEXT NOT NULL,
                        updated_at TEXT NOT NULL
                    )
                """)
                self._conn.execute("""
                    CREATE TABLE IF NOT EXISTS leadership_state (
                        id INTEGER PRIMARY KEY CHECK (id = 1),
                        term INTEGER NOT NULL,
                        leader_id TEXT NOT NULL,
                        fencing_generation INTEGER NOT NULL,
                        expires_at REAL NOT NULL,
                        updated_at TEXT NOT NULL
                    )
                """)

    def save_worker(self, worker_id: str, worker_data: Dict[str, Any]) -> None:
        with self._lock:
            now = datetime.now(timezone.utc).isoformat()
            data_str = json.dumps(worker_data)
            with self._conn:
                self._conn.execute(
                    "INSERT OR REPLACE INTO workers (worker_id, data_json, updated_at) VALUES (?, ?, ?)",
                    (worker_id, data_str, now),
                )

    def get_worker(self, worker_id: str) -> Optional[Dict[str, Any]]:
        with self._lock:
            cur = self._conn.cursor()
            cur.execute("SELECT data_json FROM workers WHERE worker_id = ?", (worker_id,))
            row = cur.fetchone()
            if row:
                return json.loads(row["data_json"])
            return None

    def list_workers(self) -> List[Dict[str, Any]]:
        with self._lock:
            cur = self._conn.cursor()
            cur.execute("SELECT data_json FROM workers")
            return [json.loads(r["data_json"]) for r in cur.fetchall()]

    def delete_worker(self, worker_id: str) -> None:
        with self._lock:
            with self._conn:
                self._conn.execute("DELETE FROM workers WHERE worker_id = ?", (worker_id,))

    def save_lease(self, operation_id: str, lease_data: Dict[str, Any]) -> None:
        with self._lock:
            now = datetime.now(timezone.utc).isoformat()
            data_str = json.dumps(lease_data)
            with self._conn:
                self._conn.execute(
                    "INSERT OR REPLACE INTO leases (operation_id, data_json, updated_at) VALUES (?, ?, ?)",
                    (operation_id, data_str, now),
                )

    def get_lease(self, operation_id: str) -> Optional[Dict[str, Any]]:
        with self._lock:
            cur = self._conn.cursor()
            cur.execute("SELECT data_json FROM leases WHERE operation_id = ?", (operation_id,))
            row = cur.fetchone()
            if row:
                return json.loads(row["data_json"])
            return None

    def list_leases(self) -> List[Dict[str, Any]]:
        with self._lock:
            cur = self._conn.cursor()
            cur.execute("SELECT data_json FROM leases")
            return [json.loads(r["data_json"]) for r in cur.fetchall()]

    def delete_lease(self, operation_id: str) -> None:
        with self._lock:
            with self._conn:
                self._conn.execute("DELETE FROM leases WHERE operation_id = ?", (operation_id,))

    def save_idempotency_record(self, key: str, value: Dict[str, Any]) -> None:
        with self._lock:
            now = datetime.now(timezone.utc).isoformat()
            data_str = json.dumps(value)
            with self._conn:
                self._conn.execute(
                    "INSERT OR REPLACE INTO idempotency_records (record_key, data_json, created_at) VALUES (?, ?, ?)",
                    (key, data_str, now),
                )

    def get_idempotency_record(self, key: str) -> Optional[Dict[str, Any]]:
        with self._lock:
            cur = self._conn.cursor()
            cur.execute("SELECT data_json FROM idempotency_records WHERE record_key = ?", (key,))
            row = cur.fetchone()
            if row:
                return json.loads(row["data_json"])
            return None

    def save_coordinator(self, coordinator_id: str, data: Dict[str, Any]) -> None:
        with self._lock:
            now = datetime.now(timezone.utc).isoformat()
            data_str = json.dumps(data)
            with self._conn:
                self._conn.execute(
                    "INSERT OR REPLACE INTO coordinators (coordinator_id, data_json, updated_at) VALUES (?, ?, ?)",
                    (coordinator_id, data_str, now),
                )

    def get_coordinator(self, coordinator_id: str) -> Optional[Dict[str, Any]]:
        with self._lock:
            cur = self._conn.cursor()
            cur.execute("SELECT data_json FROM coordinators WHERE coordinator_id = ?", (coordinator_id,))
            row = cur.fetchone()
            if row:
                return json.loads(row["data_json"])
            return None

    def list_coordinators(self) -> List[Dict[str, Any]]:
        with self._lock:
            cur = self._conn.cursor()
            cur.execute("SELECT data_json FROM coordinators")
            return [json.loads(r["data_json"]) for r in cur.fetchall()]

    def save_leadership(self, term: int, leader_id: str, fencing_generation: int, expires_at: float) -> None:
        with self._lock:
            now = datetime.now(timezone.utc).isoformat()
            with self._conn:
                self._conn.execute(
                    "INSERT OR REPLACE INTO leadership_state (id, term, leader_id, fencing_generation, expires_at, updated_at) VALUES (1, ?, ?, ?, ?, ?)",
                    (term, leader_id, fencing_generation, expires_at, now),
                )

    def get_leadership(self) -> Optional[Dict[str, Any]]:
        with self._lock:
            cur = self._conn.cursor()
            cur.execute("SELECT term, leader_id, fencing_generation, expires_at, updated_at FROM leadership_state WHERE id = 1")
            row = cur.fetchone()
            if row:
                return {
                    "term": row["term"],
                    "leader_id": row["leader_id"],
                    "fencing_generation": row["fencing_generation"],
                    "expires_at": row["expires_at"],
                    "updated_at": row["updated_at"],
                }
            return None

    def close(self) -> None:
        with self._lock:
            try:
                self._conn.close()
            except Exception:
                pass

