"""AST-backed design-pattern recognition and anti-pattern recommendations."""

from __future__ import annotations

import ast
import os
from pathlib import Path
from typing import Any


class DesignPatternEngine:
    """Finds recognizable implementation patterns and actionable code smells."""

    def analyze(self, project_root: str | Path) -> dict[str, Any]:
        root = Path(project_root).resolve()
        patterns: list[dict[str, Any]] = []
        anti_patterns: list[dict[str, Any]] = []
        analysis_errors: list[dict[str, str]] = []
        for current, directories, filenames in os.walk(root):
            directories[:] = sorted(
                name for name in directories
                if name not in {".git", ".venv", "venv", "__pycache__", ".pytest_cache", "node_modules"}
                and not name.startswith(".venv-")
            )
            for filename in sorted(filenames):
                if not filename.endswith(".py"):
                    continue
                path = Path(current) / filename
                relative = path.relative_to(root).as_posix()
                try:
                    tree = ast.parse(path.read_text(encoding="utf-8"), filename=relative)
                except (OSError, UnicodeError, SyntaxError) as exc:
                    line = getattr(exc, "lineno", None)
                    detail = f"SyntaxError at line {line}: {exc.msg}" if isinstance(exc, SyntaxError) else f"{type(exc).__name__}: {exc}"
                    analysis_errors.append({"file": relative, "error": detail})
                    continue
                for node in tree.body:
                    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        if node.name.lower().startswith(("create_", "build_", "make_")):
                            patterns.append(self._pattern("factory", relative, node.name, node.lineno))
                        if len(node.body) > 40 or getattr(node, "end_lineno", node.lineno) - node.lineno > 50:
                            anti_patterns.append({
                                "kind": "long_function",
                                "location": f"{relative}:{node.lineno}",
                                "recommendation": "Extract cohesive steps into small private helpers.",
                            })
                    if isinstance(node, ast.ClassDef):
                        names = {member.name.lower() for member in node.body if isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef))}
                        lower_name = node.name.lower()
                        if "repository" in lower_name:
                            patterns.append(self._pattern("repository", relative, node.name, node.lineno))
                        if "adapter" in lower_name or "wrapper" in lower_name:
                            patterns.append(self._pattern("adapter", relative, node.name, node.lineno))
                        if names & {"subscribe", "unsubscribe", "notify", "publish"}:
                            patterns.append(self._pattern("observer", relative, node.name, node.lineno))
                        if names & {"get_instance", "instance"}:
                            patterns.append(self._pattern("singleton", relative, node.name, node.lineno))
                        if names & {"execute", "run", "apply", "handle"} and len(names) >= 2:
                            patterns.append(self._pattern("strategy_candidate", relative, node.name, node.lineno))
                        if len(names) > 12:
                            anti_patterns.append({
                                "kind": "god_class",
                                "location": f"{relative}:{node.lineno}",
                                "method_count": len(names),
                                "recommendation": "Split the class by responsibility and preserve its public facade.",
                            })
                for node in ast.walk(tree):
                    if isinstance(node, ast.ExceptHandler) and node.type is None:
                        anti_patterns.append({
                            "kind": "bare_except",
                            "location": f"{relative}:{node.lineno}",
                            "recommendation": "Catch explicit exceptions and preserve diagnostic context.",
                        })

        patterns = self._unique_sorted(patterns)
        anti_patterns = self._unique_sorted(anti_patterns)
        suggestions = sorted({
            f"Review {item['kind']} at {item['location']}."
            for item in anti_patterns
        })
        return {
            "patterns": patterns,
            "anti_patterns": anti_patterns,
            "recommendations": suggestions,
            "analysis_errors": sorted(analysis_errors, key=lambda item: (item["file"], item["error"])),
        }

    @staticmethod
    def _pattern(kind: str, path: str, name: str, line: int) -> dict[str, Any]:
        return {
            "kind": kind,
            "location": f"{path}:{line}",
            "symbol": name,
            "recommendation": (
                "Keep the pattern when it reduces coupling; avoid additional indirection without a measured need."
            ),
        }

    @staticmethod
    def _unique_sorted(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
        unique = {
            (item["kind"], item["location"], item.get("symbol", "")): item
            for item in items
        }
        return [unique[key] for key in sorted(unique)]

core/doc_incremental_builder.py.content:
"""Section-oriented documentation updates for incremental AutoDev workflows."""

from __future__ import annotations

import hashlib
import logging
import os
import re
import tempfile
from pathlib import Path
from typing import Mapping, Optional

from core.execution_scheduler import ExecutionScheduler

logger = logging.getLogger("AutoDev.DocIncrementalBuilder")


class DocIncrementalBuilder:
    """Rewrites only named, managed documentation sections that actually changed."""

    SECTION_PATTERN = re.compile(
        r"(?P<start><!-- autodev:section:(?P<key>[0-9a-f]{16}):start -->\n)"
        r"(?P<body>.*?)"
        r"(?P<end><!-- autodev:section:(?P=key):end -->)",
        re.DOTALL,
    )

    def __init__(self, max_workers: int = 4) -> None:
        self.max_workers = max_workers
        self._document_cache: dict[
            Path,
            tuple[tuple[int, int, int, int], dict[str, str]],
        ] = {}

    def update_document(
        self,
        path: str | Path,
        sections: Mapping[str, str],
    ) -> bool:
        """Updates requested sections and preserves all text outside their markers."""
        if not sections:
            return False
        target = Path(path).resolve()
        try:
            initial_stat = target.stat()
        except FileNotFoundError:
            initial_stat = None
        if initial_stat is not None:
            signature = self._stat_signature(initial_stat)
            cached = self._document_cache.get(target)
            if cached is not None and cached[0] == signature and cached[1] == sections:
                return False
        section_signature = tuple(
            (name, content.rstrip())
            for name, content in sorted(sections.items())
        )
        original = target.read_text(encoding="utf-8") if target.exists() else ""
        matches: dict[str, re.Match[str]] = {}
        for match in self.SECTION_PATTERN.finditer(original):
            matches.setdefault(match.group("key"), match)
        replacements: list[tuple[int, int, str]] = []
        appended: list[str] = []
        for section_name, content in section_signature:
            key = hashlib.sha256(section_name.encode("utf-8")).hexdigest()[:16]
            start = f"<!-- autodev:section:{key}:start -->\n"
            end = f"<!-- autodev:section:{key}:end -->"
            replacement = f"{start}{content}\n{end}"
            match = matches.get(key)
            if match:
                if match.group(0) != replacement:
                    replacements.append((match.start(), match.end(), replacement))
            else:
                appended.append(replacement)

        changed = bool(replacements or appended)
        if changed:
            parts: list[str] = []
            last_position = 0
            for start, end, replacement in sorted(replacements):
                parts.extend((original[last_position:start], replacement))
                last_position = end
            parts.append(original[last_position:])
            updated = "".join(parts)
            if appended:
                separator = "" if not updated else ("\n" if updated.endswith("\n") else "\n\n")
                updated += separator + "\n\n".join(appended) + "\n"
            self._atomic_write(target, updated)
            logger.info("Updated managed documentation sections in %s", target)
        try:
            current_stat = target.stat()
        except OSError:
            self._document_cache.pop(target, None)
        else:
            self._document_cache[target] = (
                self._stat_signature(current_stat),
                dict(sections),
            )
        return changed

    @staticmethod
    def _stat_signature(file_stat: os.stat_result) -> tuple[int, int, int, int]:
        return (
            file_stat.st_size,
            file_stat.st_mtime_ns,
            file_stat.st_ctime_ns,
            getattr(file_stat, "st_ino", 0),
        )

    def update_documents(
        self,
        documents: Mapping[str | Path, Mapping[str, str]],
    ) -> Dict[str, bool]:
        """Updates independent documents concurrently and returns per-path change flags."""
        scheduler = ExecutionScheduler(max_workers=self.max_workers)
        path_map: dict[str, Path] = {}
        for path, sections in sorted(
            documents.items(),
            key=lambda item: str(item[0]),
        ):
            target = Path(path)
            task_id = str(target.resolve())
            if task_id in path_map:
                raise ValueError(f"Duplicate documentation target: {target}")
            path_map[task_id] = target
            scheduler.add_task(
                task_id,
                self.update_document,
                args=(target, sections),
            )
        results = scheduler.execute()
        return {
            str(path_map[task_id]): bool(results[task_id])
            for task_id in sorted(results)
        }

    def document_kind(self, path: str | Path) -> str:
        """Classifies README, engineering, architecture, and API documentation."""
        normalized = str(path).replace("\\", "/").lower()
        name = Path(normalized).name
        if name.startswith("readme"):
            return "readme"
        if "architecture" in name or "/architecture" in normalized:
            return "architecture"
        if "api" in name or "/api" in normalized:
            return "api"
        if "engineering" in name or "report" in name:
            return "engineering_report"
        return "documentation"

    @staticmethod
    def _atomic_write(target: Path, content: str) -> None:
        target.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-8", dir=target.parent, delete=False
        ) as temp_file:
            temp_file.write(content)
            temp_path = Path(temp_file.name)
        temp_path.replace(target)

core/documentation_intelligence.py.content:
"""Indexes documentation and links it to engineering knowledge."""

from __future__ import annotations

import hashlib
import re
from pathlib import Path
from typing import Any, Iterable

from core.engineering_memory import EngineeringMemory
from core.knowledge_graph import KnowledgeGraph


class DocumentationIntelligence:
    """Extracts stable documentation sections and connects them to memories."""

    def __init__(
        self,
        project_root: str | Path = ".",
        memory: EngineeringMemory | None = None,
        knowledge_graph: KnowledgeGraph | None = None,
    ) -> None:
        self.project_root = Path(project_root).resolve()
        self.memory = memory
        self.knowledge_graph = knowledge_graph or KnowledgeGraph()

    def analyze(self, paths: Iterable[str | Path] | None = None) -> list[dict[str, Any]]:
        targets = (
            [self.project_root / path for path in paths]
            if paths is not None
            else sorted(self.project_root.glob("**/*.md"))
        )
        results = []
        for path in sorted({Path(item).resolve() for item in targets}, key=str):
            if not path.is_file() or not path.is_relative_to(self.project_root):
                continue
            text = path.read_text(encoding="utf-8")
            relative = path.relative_to(self.project_root).as_posix()
            for section in _sections(text):
                section_id = hashlib.sha256(
                    f"{relative}\0{section['heading']}".encode("utf-8")
                ).hexdigest()[:20]
                item = {
                    "path": relative,
                    "heading": section["heading"],
                    "level": section["level"],
                    "summary": " ".join(section["content"].split())[:1000],
                    "content_hash": hashlib.sha256(section["content"].encode("utf-8")).hexdigest(),
                    "section_id": section_id,
                }
                node_id = f"documentation:{section_id}"
                self.knowledge_graph.add_node(
                    "documentation",
                    node_id,
                    section["heading"],
                    item,
                )
                results.append(item)
        return results

    def search(self, query: str, *, limit: int = 20) -> list[dict[str, Any]]:
        if limit < 0:
            raise ValueError("limit must not be negative.")
        needle = query.casefold().strip()
        matches = []
        for node in self.knowledge_graph.nodes("documentation"):
            attrs = node["attributes"]
            haystack = f"{node['name']} {attrs.get('path', '')} {attrs.get('summary', '')}".casefold()
            if needle in haystack:
                matches.append({
                    "heading": node["name"],
                    "path": attrs["path"],
                    "summary": attrs["summary"],
                    "section_id": attrs["section_id"],
                })
        return sorted(matches, key=lambda item: (item["path"], item["heading"]))[:limit]

    def link_memories(self) -> int:
        if self.memory is None:
            return 0
        linked = 0
        docs = self.knowledge_graph.nodes("documentation")
        for record in self.memory.records():
            phrases = _terms(record)
            for doc in docs:
                attrs = doc["attributes"]
                text = f"{doc['name']} {attrs.get('summary', '')}".casefold()
                if any(term in text for term in phrases if len(term) > 3):
                    memory_node = f"memory:{record['record_id']}"
                    if self.knowledge_graph.get_node(memory_node) is None:
                        self.knowledge_graph.add_node(
                            "memory",
                            memory_node,
                            str(record.get("title", record["record_id"])),
                            {"record_id": record["record_id"], "type": record.get("type")},
                        )
                    self.knowledge_graph.add_edge(memory_node, doc["id"], "documented_by")
                    linked += 1
        return linked


def _sections(text: str) -> list[dict[str, Any]]:
    sections: list[dict[str, Any]] = []
    heading = ""
    level = 0
    content: list[str] = []
    for line in text.splitlines():
        match = re.match(r"^(#{1,6})\s+(.+?)\s*#*\s*$", line)
        if match:
            if heading:
                sections.append({"heading": heading, "level": level, "content": "\n".join(content)})
            heading, level, content = match.group(2), len(match.group(1)), []
        elif heading:
            content.append(line)
    if heading:
        sections.append({"heading": heading, "level": level, "content": "\n".join(content)})
    return sections


def _terms(record: dict[str, Any]) -> set[str]:
    values = [str(record.get(key, "")) for key in ("title", "summary", "description", "recommendation")]
    return set(re.findall(r"[a-z0-9_]+", " ".join(values).casefold()))

