"""
AutoDev Duplication Detector (v2.7)
Deterministic AST and token-based detector for exact duplicates, near-duplicates,
repeated conditions, repeated literals, repeated SQL queries, and repeated regex patterns.
"""

from __future__ import annotations

import ast
import hashlib
import re
from typing import Any, Dict, List, Optional, Set, Tuple

from core.quality_models import CodeLocation, DuplicationBlock

# Regex patterns for detecting SQL and regex literals
SQL_PATTERN = re.compile(r"(?i)\b(SELECT\s+.+\s+FROM|INSERT\s+INTO|UPDATE\s+.+\s+SET|DELETE\s+FROM|CREATE\s+TABLE)\b")
REGEX_SPECIALS = re.compile(r"[\^$*+?{}\[\]\\|()]")


class ASTNormalizer(ast.NodeTransformer):
    """Normalizes AST tokens by masking variable names and constant values for near-duplicate detection."""

    def visit_Name(self, node: ast.Name) -> ast.AST:
        return ast.copy_location(ast.Name(id="$VAR", ctx=node.ctx), node)

    def visit_Constant(self, node: ast.Constant) -> ast.AST:
        # Preserve type class while normalizing value
        type_tag = type(node.value).__name__
        return ast.copy_location(ast.Constant(value=f"${type_tag}"), node)


class DuplicationDetector:
    """Detects multi-tier code duplications across files and workspaces."""

    def __init__(
        self,
        min_block_lines: int = 4,
        min_literal_occurrences: int = 3,
        min_lines: Optional[int] = None,
        min_token_length: Optional[int] = None,
        similarity_threshold: float = 0.85,
        **kwargs: Any,
    ):
        self.min_block_lines = min_lines if min_lines is not None else min_block_lines
        self.min_literal_occurrences = min_literal_occurrences
        self.similarity_threshold = similarity_threshold
        self.min_token_length = min_token_length

    def detect_duplicates(self, files_content: Dict[str, str]) -> List[DuplicationBlock]:
        """Detects exact and near-duplicate code blocks."""
        exact, near, _ = self._detect_code_blocks(files_content)
        return exact + near

    def detect_repeated_conditions(self, files_content: Dict[str, str]) -> Dict[str, List[CodeLocation]]:
        """Identifies repeated condition expressions across files."""
        blocks = self._detect_repeated_conditions(files_content)
        return {b.code_snippet: b.locations for b in blocks}

    def detect_repeated_literals(self, files_content: Dict[str, str]) -> Dict[str, List[CodeLocation]]:
        """Identifies magic string/number literals repeated across files."""
        blocks = self._detect_repeated_literals(files_content)
        return {b.code_snippet: b.locations for b in blocks if b.duplication_type == "repeated_literal"}

    def detect_repeated_sql(self, files_content: Dict[str, str]) -> Dict[str, List[CodeLocation]]:
        """Identifies raw SQL query literals repeated across files."""
        blocks = self._detect_repeated_literals(files_content)
        return {b.code_snippet: b.locations for b in blocks if b.duplication_type == "repeated_sql"}

    def detect_repeated_regex(self, files_content: Dict[str, str]) -> Dict[str, List[CodeLocation]]:
        """Identifies regex pattern literals repeated across files."""
        blocks = self._detect_repeated_literals(files_content)
        return {b.code_snippet: b.locations for b in blocks if b.duplication_type == "repeated_regex"}

    def scan_files(self, files_content: Dict[str, str]) -> Tuple[List[DuplicationBlock], float]:
        """
        Scans a collection of files (rel_path -> code_str) for duplications.
        Returns: (List[DuplicationBlock], duplication_percentage)
        """
        all_blocks: List[DuplicationBlock] = []
        total_sloc = 0
        duplicated_sloc_lines: Set[Tuple[str, int]] = set()

        # 1. Exact & Near Duplicate Block Detection via Normalized Window Hashes
        exact_blocks, near_blocks, sloc_by_file = self._detect_code_blocks(files_content)
        all_blocks.extend(exact_blocks)
        all_blocks.extend(near_blocks)

        for b in exact_blocks + near_blocks:
            for loc in b.locations:
                for line in range(loc.start_line, loc.end_line + 1):
                    duplicated_sloc_lines.add((loc.file_path, line))

        # 2. Repeated Conditions Detection
        condition_blocks = self._detect_repeated_conditions(files_content)
        all_blocks.extend(condition_blocks)

        # 3. Repeated Literals (Magic numbers, strings, SQL, Regex)
        literal_blocks = self._detect_repeated_literals(files_content)
        all_blocks.extend(literal_blocks)

        total_sloc = sum(sloc_by_file.values())
        dup_percentage = (
            (len(duplicated_sloc_lines) / total_sloc * 100.0)
            if total_sloc > 0
            else 0.0
        )

        return all_blocks, round(min(100.0, dup_percentage), 2)

    def _detect_code_blocks(
        self, files_content: Dict[str, str]
    ) -> Tuple[List[DuplicationBlock], List[DuplicationBlock], Dict[str, int]]:
        """Detects exact and near-duplicate multi-line statement blocks."""
        exact_hashes: Dict[str, List[Tuple[str, int, int, str]]] = {}
        near_hashes: Dict[str, List[Tuple[str, int, int, str]]] = {}
        sloc_by_file: Dict[str, int] = {}

        for file_path, content in files_content.items():
            lines = content.splitlines()
            sloc_lines = [
                (idx + 1, line.strip())
                for idx, line in enumerate(lines)
                if line.strip() and not line.strip().startswith("#")
            ]
            sloc_by_file[file_path] = len(sloc_lines)

            if len(sloc_lines) < self.min_block_lines:
                continue

            # Sliding window over executable statements
            for i in range(len(sloc_lines) - self.min_block_lines + 1):
                window = sloc_lines[i : i + self.min_block_lines]
                start_line = window[0][0]
                end_line = window[-1][0]
                block_str = "\n".join(item[1] for item in window)

                # Exact hash
                h_exact = hashlib.sha256(block_str.encode("utf-8")).hexdigest()
                exact_hashes.setdefault(h_exact, []).append((file_path, start_line, end_line, block_str))

                # Near-duplicate hash (normalize variables/literals with regex)
                norm_str = re.sub(r"\b[a-zA-Z_]\w*\b", "$ID", block_str)
                norm_str = re.sub(r"\b\d+\b", "$NUM", norm_str)
                norm_str = re.sub(r"['\"].*?['\"]", "$STR", norm_str)
                h_near = hashlib.sha256(norm_str.encode("utf-8")).hexdigest()
                near_hashes.setdefault(h_near, []).append((file_path, start_line, end_line, block_str))

        exact_dups: List[DuplicationBlock] = []
        for h, occurrences in exact_hashes.items():
            # Check for occurrences across different locations
            if len(occurrences) > 1:
                # Discard overlapping windows in same file
                filtered = self._filter_overlapping(occurrences)
                if len(filtered) > 1:
                    locations = [
                        CodeLocation(file_path=f, start_line=s, end_line=e)
                        for f, s, e, _ in filtered
                    ]
                    exact_dups.append(
                        DuplicationBlock(
                            locations=locations,
                            line_count=self.min_block_lines,
                            duplication_type="exact",
                            code_snippet=filtered[0][3],
                            similarity_score=1.0,
                        )
                    )

        near_dups: List[DuplicationBlock] = []
        # Exclude blocks already captured in exact duplicates
        for h, occurrences in near_hashes.items():
            if len(occurrences) > 1:
                filtered = self._filter_overlapping(occurrences)
                if len(filtered) > 1:
                    locations = [
                        CodeLocation(file_path=f, start_line=s, end_line=e)
                        for f, s, e, _ in filtered
                    ]
                    # Check if not exact match
                    is_exact = any(
                        filtered[0][3] == filtered[k][3]
                        for k in range(1, len(filtered))
                    )
                    if not is_exact:
                        near_dups.append(
                            DuplicationBlock(
                                locations=locations,
                                line_count=self.min_block_lines,
                                duplication_type="near_duplicate",
                                code_snippet=filtered[0][3],
                                similarity_score=0.85,
                            )
                        )

        return exact_dups, near_dups, sloc_by_file

    def _filter_overlapping(
        self, occurrences: List[Tuple[str, int, int, str]]
    ) -> List[Tuple[str, int, int, str]]:
        """Filters out heavily overlapping sliding windows in the same file."""
        distinct: List[Tuple[str, int, int, str]] = []
        for occ in occurrences:
            file_p, s, e, text = occ
            overlap = any(
                file_p == d[0] and abs(s - d[1]) < self.min_block_lines
                for d in distinct
            )
            if not overlap:
                distinct.append(occ)
        return distinct

    def _detect_repeated_conditions(self, files_content: Dict[str, str]) -> List[DuplicationBlock]:
        """Finds identical boolean conditions used across multiple conditionals."""
        condition_map: Dict[str, List[CodeLocation]] = {}

        for file_path, content in files_content.items():
            try:
                tree = ast.parse(content, filename=file_path)
            except Exception:
                continue

            for node in ast.walk(tree):
                if isinstance(node, (ast.If, ast.While, ast.IfExp)):
                    try:
                        cond_str = ast.unparse(node.test).strip()
                    except Exception:
                        continue

                    # Ignore trivial boolean constants like True, False, None
                    if cond_str in ("True", "False", "None", "1", "0", ""):
                        continue

                    loc = CodeLocation(
                        file_path=file_path,
                        start_line=getattr(node.test, "lineno", 0),
                        end_line=getattr(node.test, "end_lineno", getattr(node.test, "lineno", 0)),
                    )
                    condition_map.setdefault(cond_str, []).append(loc)

        blocks: List[DuplicationBlock] = []
        for cond_str, locs in condition_map.items():
            if len(locs) >= 2:
                blocks.append(
                    DuplicationBlock(
                        locations=locs,
                        line_count=1,
                        duplication_type="repeated_condition",
                        code_snippet=cond_str,
                        similarity_score=1.0,
                    )
                )
        return blocks

    def _detect_repeated_literals(self, files_content: Dict[str, str]) -> List[DuplicationBlock]:
        """Finds repeated magic constants, SQL queries, and regex literals."""
        literal_map: Dict[str, List[Tuple[CodeLocation, str]]] = {}

        for file_path, content in files_content.items():
            try:
                tree = ast.parse(content, filename=file_path)
            except Exception:
                continue

            for node in ast.walk(tree):
                if isinstance(node, ast.Constant):
                    val = node.value
                    if isinstance(val, str) and len(val.strip()) >= 5:
                        val_str = val.strip()
                        lit_type = "repeated_literal"
                        if SQL_PATTERN.search(val_str):
                            lit_type = "repeated_sql"
                        elif len(val_str) > 8 and REGEX_SPECIALS.search(val_str):
                            lit_type = "repeated_regex"

                        loc = CodeLocation(
                            file_path=file_path,
                            start_line=getattr(node, "lineno", 0),
                            end_line=getattr(node, "end_lineno", getattr(node, "lineno", 0)),
                        )
                        literal_map.setdefault(val_str, []).append((loc, lit_type))

        blocks: List[DuplicationBlock] = []
        for lit_str, loc_entries in literal_map.items():
            ltype = loc_entries[0][1]
            min_req = 2 if ltype in ("repeated_sql", "repeated_regex") else self.min_literal_occurrences
            if len(loc_entries) >= min_req:
                locs = [entry[0] for entry in loc_entries]
                blocks.append(
                    DuplicationBlock(
                        locations=locs,
                        line_count=1,
                        duplication_type=ltype,
                        code_snippet=lit_str[:120],
                        similarity_score=1.0,
                    )
                )
        return blocks

core/engineering_memory.py.content:
"""Persistent, structured long-term engineering memory."""

from __future__ import annotations

import hashlib
import json
import re
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Mapping

from core.memory_manager import MemoryManager


_TYPE_CATEGORY = {
    "architecture": "ARCHITECTURE",
    "architecture_decision": "DECISION",
    "bug": "BUG",
    "failure": "BUG",
    "fix": "LESSON",
    "benchmark": "OPTIMIZATION",
    "experiment": "IMPLEMENTATION",
    "learning": "LESSON",
    "reflection": "LESSON",
    "review": "REVIEW",
    "code_review": "REVIEW",
    "plan": "DECISION",
    "task": "IMPLEMENTATION",
    "project": "ARCHITECTURE",
    "refactoring": "REFACTORING",
    "performance": "OPTIMIZATION",
    "report": "IMPLEMENTATION",
}
_SENSITIVE_KEYS = {
    "chain_of_thought",
    "private_reasoning",
    "reasoning_trace",
    "internal_reasoning",
}


class EngineeringMemory:
    """Stores structured engineering records using the existing persistent store."""

    def __init__(
        self,
        project_root: str | Path = ".",
        memory_manager: MemoryManager | None = None,
        *,
        memory_path: str | Path | None = None,
    ) -> None:
        root = Path(project_root).resolve()
        self.memory_manager = memory_manager or MemoryManager(
            memory_path=memory_path or root / "memory" / "engineering_memory.json"
        )

    def store(
        self,
        record: Mapping[str, Any] | str,
        data: Mapping[str, Any] | None = None,
        *,
        record_type: str | None = None,
        record_id: str | None = None,
        title: str | None = None,
        importance: int | None = None,
    ) -> dict[str, Any]:
        """Persist a typed record; equivalent IDs update the existing record."""
        if isinstance(record, str):
            kind = record_type or record
            payload = dict(data or {})
        elif isinstance(record, Mapping):
            payload = dict(record)
            kind = record_type or str(payload.get("type", payload.get("record_type", "implementation")))
        else:
            raise TypeError("record must be a mapping or a record type string.")

        kind = kind.strip().lower().replace("-", "_")
        safe_payload = _safe_mapping(payload)
        safe_payload["type"] = kind
        resolved_title = (title or str(safe_payload.get("title", ""))).strip()
        if not resolved_title:
            resolved_title = f"{kind.replace('_', ' ').title()} record"
        safe_payload.setdefault("title", resolved_title)
        explicit_id = record_id or str(
            safe_payload.get("record_id", safe_payload.get("id", ""))
        ).strip()
        stable_id = explicit_id or _stable_id(kind, safe_payload)
        memory_id = f"eng_{stable_id}"
        content = json.dumps(
            safe_payload,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        )
        category = _TYPE_CATEGORY.get(kind, "IMPLEMENTATION")
        raw_tags = safe_payload.get("tags", [])
        if isinstance(raw_tags, str):
            raw_tags = [raw_tags]
        tags = sorted({
            kind,
            *[str(tag).strip().lower() for tag in raw_tags if str(tag).strip()],
        })
        related_tasks = [
            str(safe_payload.get("task_id"))
        ] if safe_payload.get("task_id") else []
        current = self.memory_manager.get_memory(memory_id)
        if current is None:
            entry = self.memory_manager.add_memory(
                title=resolved_title,
                content=content,
                category=category,
                tags=tags,
                importance=importance if importance is not None else int(safe_payload.get("importance", 5)),
                related_tasks=related_tasks,
                entry_id=memory_id,
                timestamp=str(safe_payload.get("timestamp") or _utc_now()),
            )
        else:
            entry = self.memory_manager.update(
                memory_id,
                title=resolved_title,
                content=content,
                category=category,
                tags=tags,
                importance=importance if importance is not None else int(safe_payload.get("importance", 5)),
                related_tasks=related_tasks,
            )
        return self._decode(entry)

    def retrieve(self, record_id: str) -> dict[str, Any] | None:
        """Retrieve a structured record by its explicit or generated ID."""
        key = str(record_id).strip()
        memory_id = key if key.startswith("eng_") else f"eng_{key}"
        entry = self.memory_manager.get_memory(memory_id)
        return self._decode(entry) if entry is not None else None

    def update(self, record_id: str, changes: Mapping[str, Any]) -> dict[str, Any]:
        """Merge structured fields into an existing record and persist it."""
        if not isinstance(changes, Mapping):
            raise TypeError("changes must be a mapping.")
        existing = self.retrieve(record_id)
        if existing is None:
            raise KeyError(f"Engineering memory record {record_id!r} not found.")
        merged = {**existing, **_safe_mapping(changes)}
        return self.store(
            merged,
            record_type=str(merged["type"]),
            record_id=str(existing["record_id"]),
            title=str(merged.get("title", existing["title"])),
        )

    def search(
        self,
        query: str = "",
        *,
        record_type: str | None = None,
        limit: int = 20,
    ) -> list[dict[str, Any]]:
        """Search records deterministically, optionally restricting record type."""
        if limit < 0:
            raise ValueError("limit must not be negative.")
        category = _TYPE_CATEGORY.get(record_type.strip().lower().replace("-", "_")) if record_type else None
        results = self.memory_manager.search(
            query,
            category=category,
            limit=max(limit * 3, limit),
        )
        records = []
        for result in results:
            record = self._decode(result.entry)
            if record_type and record.get("type") != record_type.strip().lower().replace("-", "_"):
                continue
            record["score"] = result.score
            records.append(record)
        return sorted(
            records,
            key=lambda item: (-float(item["score"]), str(item["record_id"])),
        )[:limit]

    def records(self, record_type: str | None = None) -> list[dict[str, Any]]:
        """Return all structured records in stable ID order."""
        entries = self.memory_manager.entries.values()
        records = [self._decode(item) for item in entries]
        if record_type:
            kind = record_type.strip().lower().replace("-", "_")
            records = [item for item in records if item.get("type") == kind]
        return sorted(records, key=lambda item: str(item["record_id"]))

    def forget(self, record_id: str) -> bool:
        """Delete an explicitly identified memory record."""
        key = str(record_id).strip()
        memory_id = key if key.startswith("eng_") else f"eng_{key}"
        return self.memory_manager.delete(memory_id)

    def summarize(self, *, record_type: str | None = None) -> dict[str, Any]:
        records = self.records(record_type)
        counts: dict[str, int] = {}
        for record in records:
            kind = str(record.get("type", "implementation"))
            counts[kind] = counts.get(kind, 0) + 1
        return {
            "total_records": len(records),
            "records_by_type": dict(sorted(counts.items())),
            "record_ids": [str(item["record_id"]) for item in records],
        }

    @staticmethod
    def _decode(entry: Any) -> dict[str, Any]:
        try:
            payload = json.loads(entry.content)
        except (TypeError, json.JSONDecodeError) as exc:
            raise ValueError(f"Stored engineering memory {entry.id!r} is malformed.") from exc
        if not isinstance(payload, dict):
            raise ValueError(f"Stored engineering memory {entry.id!r} is not a JSON object.")
        payload["record_id"] = entry.id.removeprefix("eng_")
        payload.setdefault("type", entry.category.lower())
        payload.setdefault("title", entry.title)
        payload.setdefault("timestamp", entry.timestamp)
        return payload


def _safe_mapping(value: Mapping[str, Any]) -> dict[str, Any]:
    def sanitize(item: Any) -> Any:
        if isinstance(item, Mapping):
            return {
                str(key): sanitize(child)
                for key, child in sorted(item.items(), key=lambda pair: str(pair[0]))
                if str(key).casefold() not in _SENSITIVE_KEYS
            }
        if isinstance(item, (list, tuple)):
            return [sanitize(child) for child in item]
        if isinstance(item, set):
            return sorted((sanitize(child) for child in item), key=str)
        if item is None or isinstance(item, (str, int, float, bool)):
            return item
        if callable(getattr(item, "to_dict", None)):
            return sanitize(item.to_dict())
        return str(item)

    return sanitize(value)


def _stable_id(*parts: Any) -> str:
    encoded = json.dumps(parts, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()[:24]


def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

core/engineering_search.py.content:
"""Lexical and graph-aware search across engineering memory and code artifacts."""

from __future__ import annotations

import re
from typing import Any, Mapping

from core.engineering_memory import EngineeringMemory
from core.knowledge_graph import KnowledgeGraph
from core.memory_ranking import MemoryRankingEngine
from core.symbol_graph import SymbolGraph


class EngineeringSearchEngine:
    """Search structured history, symbols, and graph entities without external services."""

    def __init__(
        self,
        memory: EngineeringMemory,
        knowledge_graph: KnowledgeGraph | None = None,
        symbol_graph: SymbolGraph | None = None,
        ranking_engine: MemoryRankingEngine | None = None,
    ) -> None:
        self.memory = memory
        self.knowledge_graph = knowledge_graph or KnowledgeGraph()
        self.symbol_graph = symbol_graph
        self.ranking_engine = ranking_engine or MemoryRankingEngine()

    def search(
        self,
        query: str,
        *,
        scope: str | None = None,
        mode: str = "semantic",
        limit: int = 20,
    ) -> list[dict[str, Any]]:
        if limit < 0:
            raise ValueError("limit must not be negative.")
        if mode not in {"semantic", "lexical", "dependency"}:
            raise ValueError("mode must be 'semantic', 'lexical', or 'dependency'.")
        if mode == "dependency":
            return self._dependency_search(query, limit)
        records = self.memory.search(query, record_type=scope, limit=limit * 2)
        ranked = self.ranking_engine.rank(records, query)
        results = [
            {"kind": "memory", "score": item["ranking_score"], "record": item}
            for item in ranked[:limit]
        ]
        if scope is None or scope in {"module", "package", "class", "function", "pattern", "architecture", "benchmark", "experiment", "learning", "reasoning"}:
            graph_types = scope if scope in {"module", "package", "class", "function", "pattern", "architecture", "benchmark", "experiment", "learning", "reasoning"} else None
            results.extend(
                self._graph_matches(query, graph_types, max(0, limit - len(results)), mode)
            )
        return sorted(
            results,
            key=lambda item: (
                -float(item["score"]),
                str(item.get("record", item.get("node", {})).get("record_id", item.get("node", {}).get("id", ""))),
            ),
        )[:limit]

    def similar(
        self,
        record: Mapping[str, Any] | str,
        *,
        limit: int = 10,
    ) -> list[dict[str, Any]]:
        if isinstance(record, Mapping):
            query = _text(record)
            excluded = str(record.get("record_id", record.get("id", "")))
        else:
            query = str(record)
            excluded = str(record)
        return [
            item for item in self.search(query, limit=limit + 1)
            if item.get("record", {}).get("record_id") != excluded
        ][:limit]

    def history(
        self,
        *,
        task_id: str | None = None,
        record_type: str | None = None,
        limit: int = 50,
    ) -> list[dict[str, Any]]:
        records = self.memory.records(record_type)
        if task_id is not None:
            records = [
                item for item in records
                if str(item.get("task_id", "")) == str(task_id)
                or str(task_id) in map(str, item.get("related_tasks", []))
            ]
        return sorted(
            records,
            key=lambda item: (
                str(item.get("timestamp", "")),
                str(item.get("record_id", "")),
            ),
            reverse=True,
        )[:max(0, limit)]

    def recommend(
        self,
        query: str,
        *,
        limit: int = 10,
    ) -> list[dict[str, Any]]:
        candidates = self.search(query, limit=limit * 3)
        successful = []
        for item in candidates:
            record = item.get("record", {})
            if record.get("success") is True or float(record.get("success_rate", 0.0)) > 0.0:
                successful.append(item)
        return successful[:limit]

    def _dependency_search(self, query: str, limit: int) -> list[dict[str, Any]]:
        needle = query.strip()
        if not needle:
            return []
        nodes = self.knowledge_graph.search(needle)
        matched_ids = [item["id"] for item in nodes]
        if self.symbol_graph is not None:
            matched_ids.extend(
                f"module:{path}"
                for path in self.symbol_graph.files
                if needle.casefold() in path.casefold()
            )
        results = []
        for node_id in sorted(set(matched_ids)):
            related = self.knowledge_graph.traverse(
                node_id,
                max_depth=2,
                direction="both",
            )
            results.append({
                "kind": "dependency",
                "node_id": node_id,
                "related_nodes": related,
                "score": 1.0,
            })
        return results[:limit]

    def _graph_matches(
        self,
        query: str,
        node_type: str | None,
        limit: int,
        mode: str,
    ) -> list[dict[str, Any]]:
        if limit == 0:
            return []
        query_tokens = _tokens(query)
        matched = []
        for node in self.knowledge_graph.nodes(node_type):
            text = " ".join((node["name"], node["id"], str(node.get("attributes", {}))))
            haystack = _tokens(text)
            overlap = len(query_tokens & haystack) / len(query_tokens) if query_tokens else 0.0
            phrase = query.casefold() in text.casefold() if query else False
            score = max(overlap, float(phrase))
            if score > 0:
                matched.append({
                    "kind": "graph",
                    "score": round(score, 6),
                    "node": node,
                    "match_mode": mode,
                })
        return sorted(matched, key=lambda item: (-item["score"], item["node"]["id"]))[:limit]


def _tokens(value: str) -> set[str]:
    return {token for token in re.findall(r"[a-z0-9_]+", value.casefold()) if len(token) > 1}


def _text(value: Mapping[str, Any]) -> str:
    return " ".join(
        str(value.get(key, ""))
        for key in ("title", "description", "summary", "content", "solution", "root_cause", "type")
    )

core/execution_scheduler.py.content:
"""Dependency-aware concurrent execution of independent engineering tasks."""

from __future__ import annotations

from concurrent.futures import FIRST_COMPLETED, Future, ThreadPoolExecutor, wait
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, Iterable, Optional, Set


@dataclass
class ScheduledTask:
    """A callable and the task identifiers that must finish before it starts."""

    task_id: str
    function: Callable[..., Any]
    args: tuple[Any, ...] = ()
    kwargs: Dict[str, Any] = field(default_factory=dict)
    dependencies: Set[str] = field(default_factory=set)
    resources: Set[str] = field(default_factory=set)


class ExecutionScheduler:
    """Runs ready tasks concurrently while enforcing a deterministic DAG order."""

    def __init__(
        self,
        max_workers: int = 4,
        resource_limits: Optional[Dict[str, int]] = None,
    ) -> None:
        if max_workers < 1:
            raise ValueError("max_workers must be at least 1.")
        self.max_workers = max_workers
        self.resource_limits = dict(resource_limits or {})
        if any(not name or limit < 1 for name, limit in self.resource_limits.items()):
            raise ValueError("resource names must be non-empty and capacities at least 1.")
        self._tasks: Dict[str, ScheduledTask] = {}

    def add_task(
        self,
        task_id: str,
        function: Callable[..., Any],
        args: Optional[tuple[Any, ...]] = None,
        kwargs: Optional[Dict[str, Any]] = None,
        dependencies: Optional[Set[str]] = None,
        resources: Optional[Set[str]] = None,
    ) -> None:
        """Registers a task; duplicate identifiers are rejected."""
        if not task_id:
            raise ValueError("task_id must not be empty.")
        if task_id in self._tasks:
            raise ValueError(f"Task {task_id!r} is already scheduled.")
        self._tasks[task_id] = ScheduledTask(
            task_id=task_id,
            function=function,
            args=args or (),
            kwargs=kwargs or {},
            dependencies=set(dependencies or ()),
            resources=set(resources or ()),
        )

    def execute(self, tasks: Optional[Iterable[ScheduledTask]] = None) -> Dict[str, Any]:
        """Executes registered or supplied tasks, propagating the first task failure."""
        task_map = dict(self._tasks)
        if tasks is not None:
            for task in tasks:
                if task.task_id in task_map:
                    raise ValueError(f"Task {task.task_id!r} is already scheduled.")
                task_map[task.task_id] = task
        self._validate_graph(task_map)

        results: Dict[str, Any] = {}
        pending = set(task_map)
        running: Dict[Future[Any], str] = {}
        active_resources: Dict[str, int] = {}

        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            while pending or running:
                ready = sorted(
                    task_id
                    for task_id in pending
                    if task_map[task_id].dependencies.issubset(results)
                    and all(
                        active_resources.get(resource, 0)
                        < self.resource_limits.get(resource, 1)
                        for resource in task_map[task_id].resources
                    )
                )
                while ready and len(running) < self.max_workers:
                    task_id = ready.pop(0)
                    task = task_map[task_id]
                    future = executor.submit(task.function, *task.args, **task.kwargs)
                    running[future] = task_id
                    pending.remove(task_id)
                    for resource in task.resources:
                        active_resources[resource] = active_resources.get(resource, 0) + 1

                if not running:
                    raise RuntimeError("Scheduler reached a blocked state after graph validation.")

                completed, _ = wait(running, return_when=FIRST_COMPLETED)
                failures: list[tuple[str, Exception]] = []
                for future in sorted(completed, key=lambda item: running[item]):
                    task_id = running.pop(future)
                    for resource in task_map[task_id].resources:
                        active_resources[resource] -= 1
                        if active_resources[resource] == 0:
                            del active_resources[resource]
                    try:
                        results[task_id] = future.result()
                    except Exception as err:
                        failures.append((task_id, err))
                if failures:
                    task_id, error = sorted(failures, key=lambda item: item[0])[0]
                    raise RuntimeError(f"Scheduled task {task_id!r} failed.") from error

        return {task_id: results[task_id] for task_id in sorted(results)}

    def run(self, tasks: Optional[Iterable[ScheduledTask]] = None) -> Dict[str, Any]:
        """Alias for :meth:`execute`."""
        return self.execute(tasks)

    @staticmethod
    def _validate_graph(tasks: Dict[str, ScheduledTask]) -> None:
        for task_id, task in tasks.items():
            unknown = task.dependencies - tasks.keys()
            if unknown:
                raise ValueError(
                    f"Task {task_id!r} has unknown dependencies: {', '.join(sorted(unknown))}."
                )

        remaining = {task_id: set(task.dependencies) for task_id, task in tasks.items()}
        while remaining:
            ready = sorted(task_id for task_id, deps in remaining.items() if not deps)
            if not ready:
                raise ValueError("Scheduled tasks contain a dependency cycle.")
            for task_id in ready:
                remaining.pop(task_id)
            for dependencies in remaining.values():
                dependencies.difference_update(ready)

