"""
AutoDev Kubernetes Worker Provider (Phase 3 - Kubernetes-Native Worker Orchestration)
Provides abstraction over Kubernetes API for managing worker pools, Deployments,
and Pod lifecycles with strict isolation and fake client test doubles.
"""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field, asdict
from datetime import datetime, timezone
from typing import Dict, List, Optional, Any
import copy
import uuid


@dataclass
class WorkerSecurityProfile:
    run_as_non_root: bool = True
    read_only_root_filesystem: bool = True
    allow_privilege_escalation: bool = False
    privileged: bool = False
    run_as_user: int = 10001
    run_as_group: int = 10001


@dataclass
class WorkerPoolSpec:
    name: str
    namespace: str = "autodev-system"
    image: str = "autodev/worker:v2.4.0"
    replicas: int = 1
    min_replicas: int = 1
    max_replicas: int = 10
    required_capabilities: List[str] = field(default_factory=lambda: ["python", "sandbox"])
    allowed_operation_types: List[str] = field(default_factory=lambda: ["file_edit", "shell_exec", "test_run"])
    resources_requests: Dict[str, str] = field(default_factory=lambda: {"cpu": "250m", "memory": "512Mi"})
    resources_limits: Dict[str, str] = field(default_factory=lambda: {"cpu": "1000m", "memory": "1Gi"})
    security_profile: WorkerSecurityProfile = field(default_factory=WorkerSecurityProfile)
    heartbeat_timeout_seconds: int = 30
    graceful_shutdown_seconds: int = 60
    labels: Dict[str, str] = field(default_factory=dict)
    annotations: Dict[str, str] = field(default_factory=dict)


@dataclass
class WorkerPodInfo:
    name: str
    namespace: str
    pool_name: str
    phase: str  # Pending, Running, Succeeded, Failed, Unknown
    ready: bool
    ip: Optional[str] = None
    node_name: Optional[str] = None
    created_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    labels: Dict[str, str] = field(default_factory=dict)
    draining: bool = False


@dataclass
class WorkerPoolStatus:
    replicas: int = 0
    ready_replicas: int = 0
    active_tasks: int = 0
    phase: str = "Pending"  # Pending, Scaling, Running, Degraded, Failed
    conditions: List[Dict[str, Any]] = field(default_factory=list)
    last_scale_time: Optional[str] = None
    observed_generation: int = 0


class KubernetesClientInterface(ABC):
    """Abstract interface for interacting with Kubernetes API."""

    @abstractmethod
    def get_custom_resource(self, group: str, version: str, plural: str, name: str, namespace: str) -> Optional[Dict[str, Any]]:
        pass

    @abstractmethod
    def list_custom_resources(self, group: str, version: str, plural: str, namespace: str) -> List[Dict[str, Any]]:
        pass

    @abstractmethod
    def update_custom_resource_status(self, group: str, version: str, plural: str, name: str, namespace: str, status: Dict[str, Any]) -> bool:
        pass

    @abstractmethod
    def get_deployment(self, name: str, namespace: str) -> Optional[Dict[str, Any]]:
        pass

    @abstractmethod
    def create_deployment(self, deployment: Dict[str, Any], namespace: str) -> Dict[str, Any]:
        pass

    @abstractmethod
    def update_deployment(self, name: str, deployment: Dict[str, Any], namespace: str) -> Dict[str, Any]:
        pass

    @abstractmethod
    def scale_deployment(self, name: str, replicas: int, namespace: str) -> bool:
        pass

    @abstractmethod
    def delete_deployment(self, name: str, namespace: str) -> bool:
        pass

    @abstractmethod
    def list_pods(self, namespace: str, label_selector: Optional[str] = None) -> List[Dict[str, Any]]:
        pass

    @abstractmethod
    def delete_pod(self, name: str, namespace: str, grace_period_seconds: int = 30) -> bool:
        pass


class FakeKubernetesClient(KubernetesClientInterface):
    """
    In-memory mock implementation of Kubernetes API client for hermetic testing.
    Provides full CRD, Deployment, and Pod simulation with labels and status.
    """

    def __init__(self) -> None:
        self.custom_resources: Dict[str, Dict[str, Any]] = {}
        self.deployments: Dict[str, Dict[str, Any]] = {}
        self.pods: Dict[str, Dict[str, Any]] = {}
        self.deleted_resources: List[str] = []

    def _key(self, kind: str, name: str, namespace: str) -> str:
        return f"{namespace}/{kind}/{name}"

    def get_custom_resource(self, group: str, version: str, plural: str, name: str, namespace: str) -> Optional[Dict[str, Any]]:
        key = self._key(plural, name, namespace)
        return copy.deepcopy(self.custom_resources.get(key))

    def list_custom_resources(self, group: str, version: str, plural: str, namespace: str) -> List[Dict[str, Any]]:
        prefix = f"{namespace}/{plural}/"
        return [copy.deepcopy(v) for k, v in self.custom_resources.items() if k.startswith(prefix)]

    def create_custom_resource(self, group: str, version: str, plural: str, resource: Dict[str, Any], namespace: str) -> Dict[str, Any]:
        name = resource.get("metadata", {}).get("name", "unnamed")
        key = self._key(plural, name, namespace)
        self.custom_resources[key] = copy.deepcopy(resource)
        return copy.deepcopy(resource)

    def update_custom_resource_status(self, group: str, version: str, plural: str, name: str, namespace: str, status: Dict[str, Any]) -> bool:
        key = self._key(plural, name, namespace)
        if key not in self.custom_resources:
            return False
        self.custom_resources[key]["status"] = copy.deepcopy(status)
        return True

    def get_deployment(self, name: str, namespace: str) -> Optional[Dict[str, Any]]:
        key = self._key("deployment", name, namespace)
        return copy.deepcopy(self.deployments.get(key))

    def create_deployment(self, deployment: Dict[str, Any], namespace: str) -> Dict[str, Any]:
        name = deployment["metadata"]["name"]
        key = self._key("deployment", name, namespace)
        self.deployments[key] = copy.deepcopy(deployment)
        # Automatically create initial simulated pods
        replicas = deployment.get("spec", {}).get("replicas", 1)
        self._sync_pods(name, namespace, replicas, deployment)
        return copy.deepcopy(deployment)

    def update_deployment(self, name: str, deployment: Dict[str, Any], namespace: str) -> Dict[str, Any]:
        key = self._key("deployment", name, namespace)
        self.deployments[key] = copy.deepcopy(deployment)
        replicas = deployment.get("spec", {}).get("replicas", 1)
        self._sync_pods(name, namespace, replicas, deployment)
        return copy.deepcopy(deployment)

    def scale_deployment(self, name: str, replicas: int, namespace: str) -> bool:
        key = self._key("deployment", name, namespace)
        if key not in self.deployments:
            return False
        self.deployments[key]["spec"]["replicas"] = replicas
        self._sync_pods(name, namespace, replicas, self.deployments[key])
        return True

    def delete_deployment(self, name: str, namespace: str) -> bool:
        key = self._key("deployment", name, namespace)
        if key in self.deployments:
            del self.deployments[key]
            self.deleted_resources.append(key)
            # Delete corresponding pods
            pods_to_del = [
                pk for pk, p in self.pods.items()
                if p.get("metadata", {}).get("labels", {}).get("app.kubernetes.io/instance") == name
                or p.get("metadata", {}).get("name", "").startswith(f"{name}-")
            ]
            for pk in pods_to_del:
                del self.pods[pk]
            return True
        return False

    def list_pods(self, namespace: str, label_selector: Optional[str] = None) -> List[Dict[str, Any]]:
        prefix = f"{namespace}/pod/"
        results = [copy.deepcopy(v) for k, v in self.pods.items() if k.startswith(prefix)]
        if label_selector:
            # Simple k=v parsing
            pairs = [p.split("=") for p in label_selector.split(",") if "=" in p]
            filtered = []
            for pod in results:
                pod_labels = pod.get("metadata", {}).get("labels", {})
                if all(pod_labels.get(k.strip()) == v.strip() for k, v in pairs):
                    filtered.append(pod)
            return filtered
        return results

    def delete_pod(self, name: str, namespace: str, grace_period_seconds: int = 30) -> bool:
        key = self._key("pod", name, namespace)
        if key in self.pods:
            del self.pods[key]
            self.deleted_resources.append(key)
            return True
        return False

    def _sync_pods(self, deployment_name: str, namespace: str, target_replicas: int, deployment: Dict[str, Any]) -> None:
        prefix = f"{namespace}/pod/"
        existing_pods = [k for k, p in self.pods.items() if k.startswith(prefix) and p.get("metadata", {}).get("labels", {}).get("app.kubernetes.io/instance") == deployment_name]

        current_count = len(existing_pods)
        labels = deployment.get("spec", {}).get("template", {}).get("metadata", {}).get("labels", {}).copy()
        labels["app.kubernetes.io/instance"] = deployment_name

        if current_count < target_replicas:
            for _ in range(target_replicas - current_count):
                pod_name = f"{deployment_name}-{uuid.uuid4().hex[:6]}"
                pod_key = self._key("pod", pod_name, namespace)
                self.pods[pod_key] = {
                    "metadata": {
                        "name": pod_name,
                        "namespace": namespace,
                        "labels": labels,
                        "creationTimestamp": datetime.now(timezone.utc).isoformat(),
                    },
                    "status": {
                        "phase": "Running",
                        "podIP": f"10.244.1.{len(self.pods)+1}",
                        "conditions": [{"type": "Ready", "status": "True"}],
                    }
                }
        elif current_count > target_replicas:
            to_remove = existing_pods[:(current_count - target_replicas)]
            for k in to_remove:
                del self.pods[k]


class KubernetesWorkerProvider:
    """
    Manages AutoDev worker deployments and pods using Kubernetes API.
    Enforces security profiles (non-root, read-only rootfs) and isolation.
    """

    def __init__(self, client: Optional[KubernetesClientInterface] = None) -> None:
        self.client = client or FakeKubernetesClient()

    def create_or_update_pool_deployment(self, spec: WorkerPoolSpec) -> Dict[str, Any]:
        """Create or update Kubernetes Deployment corresponding to WorkerPoolSpec."""
        labels = {
            "app.kubernetes.io/name": "autodev-worker",
            "app.kubernetes.io/instance": spec.name,
            "app.kubernetes.io/managed-by": "autodev-controller",
            "autodev.io/pool": spec.name,
        }
        labels.update(spec.labels)

        deployment_manifest = {
            "apiVersion": "apps/v1",
            "kind": "Deployment",
            "metadata": {
                "name": f"autodev-worker-{spec.name}",
                "namespace": spec.namespace,
                "labels": labels,
                "annotations": spec.annotations,
            },
            "spec": {
                "replicas": spec.replicas,
                "selector": {
                    "matchLabels": {
                        "app.kubernetes.io/name": "autodev-worker",
                        "autodev.io/pool": spec.name,
                    }
                },
                "template": {
                    "metadata": {
                        "labels": labels,
                    },
                    "spec": {
                        "serviceAccountName": "autodev-worker",
                        "securityContext": {
                            "runAsNonRoot": spec.security_profile.run_as_non_root,
                            "runAsUser": spec.security_profile.run_as_user,
                            "runAsGroup": spec.security_profile.run_as_group,
                        },
                        "containers": [
                            {
                                "name": "worker",
                                "image": spec.image,
                                "resources": {
                                    "requests": spec.resources_requests,
                                    "limits": spec.resources_limits,
                                },
                                "securityContext": {
                                    "readOnlyRootFilesystem": spec.security_profile.read_only_root_filesystem,
                                    "allowPrivilegeEscalation": spec.security_profile.allow_privilege_escalation,
                                    "privileged": spec.security_profile.privileged,
                                },
                                "env": [
                                    {"name": "AUTODEV_POOL_NAME", "value": spec.name},
                                    {"name": "AUTODEV_CAPABILITIES", "value": ",".join(spec.required_capabilities)},
                                ],
                            }
                        ],
                        "terminationGracePeriodSeconds": spec.graceful_shutdown_seconds,
                    }
                }
            }
        }

        existing = self.client.get_deployment(f"autodev-worker-{spec.name}", spec.namespace)
        if existing:
            return self.client.update_deployment(f"autodev-worker-{spec.name}", deployment_manifest, spec.namespace)
        return self.client.create_deployment(deployment_manifest, spec.namespace)

    def scale_pool(self, pool_name: str, namespace: str, desired_replicas: int) -> bool:
        deployment_name = f"autodev-worker-{pool_name}"
        return self.client.scale_deployment(deployment_name, desired_replicas, namespace)

    def list_pool_workers(self, pool_name: str, namespace: str) -> List[WorkerPodInfo]:
        label_selector = f"autodev.io/pool={pool_name}"
        pods = self.client.list_pods(namespace=namespace, label_selector=label_selector)
        worker_pods: List[WorkerPodInfo] = []

        for p in pods:
            meta = p.get("metadata", {})
            status = p.get("status", {})
            conditions = status.get("conditions", [])
            is_ready = any(c.get("type") == "Ready" and c.get("status") == "True" for c in conditions)

            worker_pods.append(
                WorkerPodInfo(
                    name=meta.get("name", "unknown"),
                    namespace=meta.get("namespace", namespace),
                    pool_name=pool_name,
                    phase=status.get("phase", "Unknown"),
                    ready=is_ready,
                    ip=status.get("podIP"),
                    node_name=status.get("nodeName"),
                    created_at=meta.get("creationTimestamp", datetime.now(timezone.utc).isoformat()),
                    labels=meta.get("labels", {}),
                )
            )
        return worker_pods

core/multi_agent_runtime.py.content:
"""Opt-in runtime for deterministic agent discovery and task dispatch."""

from __future__ import annotations

import concurrent.futures
import threading
from typing import Any, Callable, Optional

from core.agent_bus import AgentBus, AgentMessageType
from core.agent_metrics import AgentMetricsTracker
from core.capability_manager import AgentCapabilityManager
from core.multi_agent.agent_registry import AgentDescriptor, AgentRegistry, AgentRole, AgentStatus
from core.task_negotiation import NegotiationResult, TaskNegotiationEngine


class MultiAgentRuntime:
    """Combines the legacy registry with typed bus, capabilities, and negotiation."""

    def __init__(
        self,
        registry: Optional[AgentRegistry] = None,
        bus: Optional[AgentBus] = None,
        capability_manager: Optional[AgentCapabilityManager] = None,
        metrics_tracker: Optional[AgentMetricsTracker] = None,
        max_workers: int = 4,
    ) -> None:
        if max_workers < 1:
            raise ValueError("max_workers must be at least one")
        self.registry = registry or AgentRegistry()
        self.bus = bus or AgentBus()
        self.capability_manager = capability_manager or AgentCapabilityManager(self.registry)
        self.metrics_tracker = metrics_tracker
        self.negotiator = TaskNegotiationEngine(self.capability_manager, metrics_tracker)
        self.max_workers = max_workers
        self._lock = threading.RLock()
        self._handlers: dict[str, Callable[[Any], Any]] = {}
        self._executor = concurrent.futures.ThreadPoolExecutor(max_workers=max_workers)

    def register_agent(
        self,
        agent: Any = None,
        *,
        agent_id: Optional[str] = None,
        name: Optional[str] = None,
        capabilities: Optional[list[str]] = None,
        languages: Optional[list[str]] = None,
        domains: Optional[list[str]] = None,
        preferred_workloads: Optional[list[str]] = None,
        handler: Optional[Callable[[Any], Any]] = None,
        role: AgentRole = AgentRole.TASK_SCHEDULER,
        priority: int = 50,
        max_workload: int = 1,
        metadata: Optional[dict[str, Any]] = None,
    ) -> AgentDescriptor:
        descriptor = agent if isinstance(agent, AgentDescriptor) else None
        resolved_id = descriptor.agent_id if descriptor else (agent_id or getattr(agent, "agent_id", ""))
        if not resolved_id:
            raise ValueError("agent_id or an AgentDescriptor with an ID is required")
        if descriptor is None:
            resolved_name = name or getattr(agent, "name", resolved_id)
            descriptor = AgentDescriptor(
                agent_id=resolved_id,
                name=resolved_name,
                role=role,
                capabilities=sorted(set(capabilities or [])),
                priority=priority,
                max_workload=max_workload,
                metadata=dict(metadata or {}),
            )
        self.registry.register_agent(descriptor)
        self.bus.register_inbox(resolved_id)
        self.capability_manager.register(
            resolved_id,
            skills=capabilities or descriptor.capabilities,
            languages=languages,
            domains=domains,
            preferred_workloads=preferred_workloads,
        )
        selected_handler = handler or self._find_handler(agent)
        if selected_handler is not None:
            with self._lock:
                self._handlers[resolved_id] = selected_handler
        return descriptor

    def remove_agent(self, agent_id: str) -> bool:
        with self._lock:
            removed = self.registry.remove_agent(agent_id)
            if removed:
                self._handlers.pop(agent_id, None)
                self.bus.remove_inbox(agent_id)
            return removed

    def discover(
        self,
        capability: Optional[str] = None,
        required_capabilities: Optional[list[str]] = None,
        required_languages: Optional[list[str]] = None,
        required_domains: Optional[list[str]] = None,
        available_only: bool = True,
    ) -> list[AgentDescriptor]:
        skills = list(required_capabilities or [])
        if capability:
            skills.append(capability)
        results = self.capability_manager.discover(
            skills=skills,
            languages=required_languages,
            domains=required_domains,
            available_only=available_only,
        )
        return [item["agent"] for item in results]

    def dispatch(
        self,
        task: Any,
        required_capabilities: Optional[list[str]] = None,
        timeout: Optional[float] = None,
        record_metrics: bool = True,
        execute_handler: bool = True,
    ) -> dict[str, Any]:
        if timeout is not None and timeout < 0:
            raise ValueError("timeout must not be negative")
        negotiation = self.negotiator.negotiate(task, required_capabilities)
        if not negotiation.agent_id:
            raise RuntimeError(negotiation.reason)
        agent_id = negotiation.agent_id
        handler = self._handlers.get(agent_id)
        payload = self._task_payload(task)
        message = self.bus.publish(
            AgentMessageType.TASK_REQUEST,
            sender="multi_agent_runtime",
            receiver=agent_id,
            payload=payload,
        )
        if not execute_handler:
            return {
                "agent_id": agent_id,
                "message_id": message.message_id,
                "status": "queued",
                "negotiation": negotiation.to_dict(),
            }
        if handler is None:
            return {
                "agent_id": agent_id,
                "message_id": message.message_id,
                "status": "queued",
                "negotiation": negotiation.to_dict(),
            }
        self.registry.update_workload(agent_id, 1)
        self.registry.set_status(agent_id, AgentStatus.BUSY)
        try:
            future = self._executor.submit(handler, task)
            result = future.result(timeout=timeout)
        except concurrent.futures.TimeoutError:
            if future.cancel():
                self.registry.record_completion(
                    agent_id,
                    success=False,
                    duration=timeout or 0.0,
                )
            else:
                future.add_done_callback(
                    lambda _: self.registry.record_completion(
                        agent_id,
                        success=False,
                        duration=timeout or 0.0,
                    )
                )
            raise TimeoutError(f"Agent {agent_id!r} did not complete task before timeout")
        except Exception:
            self.registry.record_completion(agent_id, success=False, duration=0.0)
            raise
        else:
            self.registry.record_completion(agent_id, success=True, duration=0.0)
            if record_metrics and self.metrics_tracker is not None:
                self.metrics_tracker.record(agent_id, success=True)
            self.bus.acknowledge(message.message_id)
            return {
                "agent_id": agent_id,
                "message_id": message.message_id,
                "status": "completed",
                "result": result,
                "negotiation": negotiation.to_dict(),
            }

    def broadcast(
        self,
        message: Any,
        payload: Optional[dict[str, Any]] = None,
        message_type: AgentMessageType | str = AgentMessageType.SYSTEM_EVENT,
    ) -> Any:
        if isinstance(message, str):
            sender = message
            body = payload or {}
        else:
            sender = "multi_agent_runtime"
            body = self._task_payload(message)
        return self.bus.broadcast(sender, body, message_type)

    def get_status(self, agent_id: Optional[str] = None) -> Any:
        if agent_id is not None:
            descriptor = self.registry.get_agent(agent_id)
            return descriptor.to_dict() if descriptor else None
        return {
            "agents": [agent.to_dict() for agent in self.registry.get_all_agents()],
            "agent_count": int(self.registry.count),
            "messages": len(self.bus.history()),
        }

    def close(self) -> None:
        self._executor.shutdown(wait=True)

    @staticmethod
    def _task_payload(task: Any) -> dict[str, Any]:
        if isinstance(task, dict):
            return dict(task)
        if hasattr(task, "to_dict"):
            return task.to_dict()
        if hasattr(task, "__dict__"):
            return dict(task.__dict__)
        return {"task": str(task)}

    @staticmethod
    def _find_handler(agent: Any) -> Optional[Callable[[Any], Any]]:
        for method_name in ("handle_task", "execute_task", "process_task", "run_task"):
            method = getattr(agent, method_name, None)
            if callable(method):
                return method
        return agent if callable(agent) else None

core/organization_manager.py.content:
"""Organization and team lifecycle management for the opt-in v3.9 workflow."""

from __future__ import annotations

import copy
import threading
from dataclasses import asdict, dataclass, field
from typing import Any, Optional


@dataclass
class EngineeringTeam:
    team_id: str
    name: str
    capabilities: list[str] = field(default_factory=list)
    agent_ids: list[str] = field(default_factory=list)
    role_assignments: dict[str, str] = field(default_factory=dict)
    parent_team_id: Optional[str] = None
    status: str = "ACTIVE"

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


class OrganizationManager:
    """Maintains a deterministic team hierarchy around the existing agent runtime."""

    def __init__(self, runtime: Optional[Any] = None) -> None:
        self.runtime = runtime
        self._lock = threading.RLock()
        self._teams: dict[str, EngineeringTeam] = {}
        self._next_team_number = 1

    def create_team(
        self,
        name: str,
        capabilities: Optional[list[str]] = None,
        parent_team_id: Optional[str] = None,
        team_id: Optional[str] = None,
    ) -> EngineeringTeam:
        if not name.strip():
            raise ValueError("Team name must not be empty.")
        with self._lock:
            if parent_team_id is not None and parent_team_id not in self._teams:
                raise KeyError(f"Parent team {parent_team_id!r} does not exist.")
            resolved_id = team_id or f"TEAM-{self._next_team_number:04d}"
            if resolved_id in self._teams:
                raise ValueError(f"Team {resolved_id!r} already exists.")
            team = EngineeringTeam(
                team_id=resolved_id,
                name=name,
                capabilities=sorted(set(capabilities or [])),
                parent_team_id=parent_team_id,
            )
            self._teams[resolved_id] = team
            self._next_team_number += 1
            return copy.deepcopy(team)

    def remove_team(self, team_id: str, cascade: bool = False) -> bool:
        with self._lock:
            if team_id not in self._teams:
                return False
            children = sorted(
                team.team_id for team in self._teams.values()
                if team.parent_team_id == team_id
            )
            if children and not cascade:
                raise ValueError(f"Team {team_id!r} has child teams.")
            for child_id in children:
                self.remove_team(child_id, cascade=True)
            del self._teams[team_id]
            return True

    def assign_agent(
        self,
        team_id: str,
        agent_id: str,
        role: Optional[str] = None,
    ) -> bool:
        if not agent_id:
            raise ValueError("Agent ID must not be empty.")
        with self._lock:
            team = self._require_team(team_id)
            if self.runtime is not None and self.runtime.get_status(agent_id) is None:
                raise KeyError(f"Agent {agent_id!r} is not registered.")
            if agent_id not in team.agent_ids:
                team.agent_ids.append(agent_id)
                team.agent_ids.sort()
            if role:
                team.role_assignments[role] = agent_id
            return True

    def remove_agent(self, team_id: str, agent_id: str) -> bool:
        with self._lock:
            team = self._teams.get(team_id)
            if team is None or agent_id not in team.agent_ids:
                return False
            team.agent_ids.remove(agent_id)
            team.role_assignments = {
                role: assigned
                for role, assigned in team.role_assignments.items()
                if assigned != agent_id
            }
            return True

    def team_status(self, team_id: str) -> Optional[dict[str, Any]]:
        with self._lock:
            team = self._teams.get(team_id)
            if team is None:
                return None
            result = team.to_dict()
            statuses = [
                self.runtime.get_status(agent_id)
                for agent_id in team.agent_ids
            ] if self.runtime is not None else []
            statuses = [status for status in statuses if isinstance(status, dict)]
            available = sum(
                1 for status in statuses
                if status.get("status") not in {"OFFLINE", "FAILED"}
                and status.get("workload", 0) < status.get("max_workload", 1)
            )
            result["health"] = round(available / len(statuses), 4) if statuses else 1.0
            result["agent_statuses"] = statuses
            return result

    def organization_summary(self) -> dict[str, Any]:
        with self._lock:
            teams = [self.team_status(team_id) for team_id in sorted(self._teams)]
            return {
                "team_count": len(teams),
                "agent_count": len({agent for team in self._teams.values() for agent in team.agent_ids}),
                "teams": teams,
            }

    def list_teams(self) -> list[EngineeringTeam]:
        with self._lock:
            return [copy.deepcopy(self._teams[team_id]) for team_id in sorted(self._teams)]

    def _require_team(self, team_id: str) -> EngineeringTeam:
        try:
            return self._teams[team_id]
        except KeyError as exc:
            raise KeyError(f"Team {team_id!r} does not exist.") from exc

