"""Dependency- and resource-aware public scheduler for multi-agent tasks."""

from __future__ import annotations

from typing import Any, Callable, Iterable, Optional

from core.execution_scheduler import ExecutionScheduler, ScheduledTask
from core.planning_revision import PlanningRevisionEngine


class ParallelTaskScheduler(ExecutionScheduler):
    """Extends the existing worker pool with file/resource serialization."""

    @staticmethod
    def safe_parallel_groups(tasks: Any) -> list[list[str]]:
        revision = PlanningRevisionEngine().optimize(tasks)
        return revision.parallel_groups

    def schedule(
        self,
        tasks: Iterable[ScheduledTask],
    ) -> dict[str, Any]:
        """Executes dependency-valid tasks and returns results in task-ID order."""
        return self.execute(tasks)


ParallelScheduler = ParallelTaskScheduler

core/patch_validator.py.content:
"""
AutoDev Patch Validator (v2.6)
Strict validation gates: workspace containment, AST syntax checking,
anti-test-weakening enforcement, and security sensitivity inspection.
"""

from __future__ import annotations

import ast
import logging
import os
import re
from typing import Any, Dict, List, Optional

from core.repair_models import (
    CandidatePatch,
    FilePatch,
    PatchValidationResult,
    RepairPolicy,
    RiskLevel,
)

logger = logging.getLogger(__name__)

SECURITY_KEYWORDS = {"auth", "crypto", "consensus", "isolation", "secret", "ebpf", "token", "sandbox", "fencing"}


class PatchValidator:
    """Validates candidate patches against workspace boundaries, syntax rules, and anti-weakening policies."""

    def __init__(self, workspace_path: str, policy: Optional[RepairPolicy] = None):
        self.workspace_path = os.path.realpath(os.path.abspath(workspace_path))
        self.policy = policy or RepairPolicy()

    def validate(self, patch: CandidatePatch) -> PatchValidationResult:
        """Executes full validation suite on candidate patch."""
        rejection_reasons: List[str] = []
        warnings: List[str] = []
        syntax_ok = True
        containment_ok = True
        size_ok = True
        anti_weakening_ok = True
        security_ok = True

        if not patch.file_patches:
            return PatchValidationResult(
                is_valid=False,
                rejection_reasons=["Candidate patch contains no file modifications."],
            )

        # 1. Size limits
        if patch.total_lines_changed > self.policy.max_diff_lines:
            size_ok = False
            rejection_reasons.append(
                f"Patch diff size ({patch.total_lines_changed} lines) exceeds maximum allowed limit ({self.policy.max_diff_lines} lines)."
            )

        # 2. File-by-file checks
        for fp in patch.file_patches:
            # Containment check
            if not self._check_containment(fp.file_path):
                containment_ok = False
                rejection_reasons.append(f"File path '{fp.file_path}' attempts path traversal outside workspace boundaries.")

            # Syntax check for Python files
            if fp.file_path.endswith(".py"):
                syntax_valid, err_msg = self._check_python_syntax(fp.new_content, fp.file_path)
                if not syntax_valid:
                    syntax_ok = False
                    rejection_reasons.append(f"Syntax validation failed in '{fp.file_path}': {err_msg}")

            # Anti-weakening check
            weakening_detected, reason = self._check_anti_weakening(fp)
            if weakening_detected:
                anti_weakening_ok = False
                rejection_reasons.append(f"Anti-weakening policy violation in '{fp.file_path}': {reason}")

            # Security sensitivity check
            if not self.policy.allow_security_sensitive_changes:
                if any(k in fp.file_path.lower() for k in SECURITY_KEYWORDS):
                    fp.is_security_sensitive = True
                    if patch.risk_level != RiskLevel.CRITICAL:
                        patch.risk_level = RiskLevel.HIGH
                    warnings.append(f"Patch touches security-sensitive file '{fp.file_path}'. Requires human approval.")

        is_valid = containment_ok and syntax_ok and size_ok and anti_weakening_ok and (len(rejection_reasons) == 0)

        return PatchValidationResult(
            is_valid=is_valid,
            rejection_reasons=rejection_reasons,
            warnings=warnings,
            syntax_ok=syntax_ok,
            containment_ok=containment_ok,
            size_ok=size_ok,
            anti_weakening_ok=anti_weakening_ok,
            security_ok=security_ok,
        )

    def _check_containment(self, rel_path: str) -> bool:
        """Verifies path resolves within the authorized workspace."""
        if os.path.isabs(rel_path):
            abs_target = os.path.realpath(rel_path)
        else:
            abs_target = os.path.realpath(os.path.abspath(os.path.join(self.workspace_path, rel_path)))

        return abs_target == self.workspace_path or abs_target.startswith(self.workspace_path + os.sep)

    def _check_python_syntax(self, code: str, filename: str) -> tuple[bool, str]:
        """Parses Python source using AST to ensure valid grammar."""
        try:
            ast.parse(code, filename=filename)
            return True, ""
        except SyntaxError as e:
            return False, f"Line {e.lineno}: {e.msg}"
        except Exception as e:
            return False, str(e)

    def _check_anti_weakening(self, fp: FilePatch) -> tuple[bool, str]:
        """Detects malicious or deceptive test weakening and silent exception swallows."""
        # Check for bare except pass in new content
        bare_except_pass = re.search(r"except(?:\s+Exception)?\s*:\s*(?:pass|\.\.\.)", fp.new_content)
        if bare_except_pass:
            return True, "Detected silent exception suppression (`except: pass`). Defect must be properly resolved."

        # If modifying a test file, ensure assertions are not deleted or replaced with trivial 'assert True'
        if fp.is_test_file:
            orig_asserts = len(re.findall(r"\bassert\b", fp.original_content))
            new_asserts = len(re.findall(r"\bassert\b", fp.new_content))
            if orig_asserts > 0 and new_asserts == 0:
                return True, "Test weakening detected: all assert statements were removed from test file."

            if "assert True" in fp.new_content and "assert True" not in fp.original_content:
                return True, "Test weakening detected: introduced trivial 'assert True'."

        return False, ""

core/performance_evolution.py.content:
"""Stage telemetry interpretation for continuous performance improvement."""

from __future__ import annotations

import sys
import time
from typing import Any, Mapping


class PerformanceEvolutionEngine:
    """Normalizes runtime metrics and suggests measured performance investigations."""

    STAGES = ("execution", "planning", "scheduling", "learning")

    def __init__(self) -> None:
        self.history: list[dict[str, Any]] = []

    def capture(
        self,
        *,
        cache_manager: Any = None,
        stage_metrics: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Captures process CPU/RSS and optional cache and stage telemetry."""
        cpu: dict[str, Any] = {"process_cpu_seconds": time.process_time()}
        memory: dict[str, Any] = {}
        try:
            import resource
        except ImportError:
            memory["peak_bytes"] = None
            memory["availability"] = "resource module unavailable"
        else:
            usage = resource.getrusage(resource.RUSAGE_SELF)
            multiplier = 1 if sys.platform == "darwin" else 1024
            memory["peak_bytes"] = int(usage.ru_maxrss * multiplier)
            cpu["user_seconds"] = usage.ru_utime
            cpu["system_seconds"] = usage.ru_stime

        cache: dict[str, Any] = {}
        if cache_manager is not None:
            stats = cache_manager.get_stats()
            total_hits = sum(
                int(item.get("hit_count", 0))
                for item in stats.get("caches", {}).values()
            )
            total_misses = sum(
                int(item.get("miss_count", 0))
                for item in stats.get("caches", {}).values()
            )
            total = total_hits + total_misses
            cache = {
                "cache_count": stats.get("cache_count", 0),
                "size_bytes": stats.get("total_size_bytes", 0),
                "hit_count": total_hits,
                "miss_count": total_misses,
                "hit_ratio": total_hits / total if total else 0.0,
            }
        return self.analyze({
            "cpu": cpu,
            "memory": memory,
            "cache": cache,
            **dict(stage_metrics or {}),
        })

    def analyze(self, metrics: Mapping[str, Any] | None = None) -> dict[str, Any]:
        data = dict(metrics or {})
        cpu = data.get("cpu", {})
        memory = data.get("memory", {})
        cache = data.get("cache", {})
        stages = {
            stage: self._stage_metrics(data.get(stage, {}))
            for stage in self.STAGES
        }
        recommendations = []
        cpu_seconds = cpu.get("process_cpu_seconds") if isinstance(cpu, Mapping) else None
        if isinstance(cpu_seconds, (int, float)) and cpu_seconds > 60.0:
            recommendations.append({
                "domain": "cpu",
                "priority": "medium",
                "action": "Profile CPU-heavy stages and compare equivalent workloads.",
                "evidence": {"process_cpu_seconds": cpu_seconds},
            })
        for stage, values in stages.items():
            latency = values.get("latency_seconds")
            if isinstance(latency, (int, float)) and latency > 1.0:
                recommendations.append({
                    "domain": stage,
                    "priority": "high" if latency > 5.0 else "medium",
                    "action": f"Profile the {stage} stage and benchmark a behavior-preserving alternative.",
                    "evidence": {"latency_seconds": latency},
                })
        hit_ratio = cache.get("hit_ratio") if isinstance(cache, Mapping) else None
        if isinstance(hit_ratio, (int, float)) and hit_ratio < 0.5:
            recommendations.append({
                "domain": "cache",
                "priority": "medium",
                "action": "Inspect cache-key stability and invalidation frequency.",
                "evidence": {"hit_ratio": hit_ratio},
            })
        peak = memory.get("peak_bytes") if isinstance(memory, Mapping) else None
        if isinstance(peak, (int, float)) and peak > 512 * 1024 * 1024:
            recommendations.append({
                "domain": "memory",
                "priority": "high",
                "action": "Profile large allocations and bound retained histories.",
                "evidence": {"peak_bytes": peak},
            })
        record = {
            "cpu": dict(cpu) if isinstance(cpu, Mapping) else {},
            "memory": dict(memory) if isinstance(memory, Mapping) else {},
            "cache": dict(cache) if isinstance(cache, Mapping) else {},
            "stages": stages,
            "recommendations": sorted(
                recommendations,
                key=lambda item: (
                    0 if item["priority"] == "high" else 1,
                    item["domain"],
                    item["action"],
                ),
            ),
        }
        self.history.append(record)
        return record

    @staticmethod
    def _stage_metrics(value: Any) -> dict[str, Any]:
        if isinstance(value, Mapping):
            return {
                key: value[key]
                for key in ("latency_seconds", "operations", "error_rate", "throughput")
                if key in value
            }
        if isinstance(value, (int, float)):
            return {"latency_seconds": float(value)}
        return {}

core/planning_revision.py.content:
"""Deterministic planning validation, repair, and safe parallel opportunity analysis."""

from __future__ import annotations

import copy
from dataclasses import dataclass, field
from typing import Any, Mapping, Sequence


@dataclass
class PlanReview:
    valid: bool = True
    issues: list[dict[str, Any]] = field(default_factory=list)
    dependency_violations: list[dict[str, str]] = field(default_factory=list)
    resource_conflicts: list[dict[str, str]] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "valid": self.valid,
            "issues": copy.deepcopy(self.issues),
            "dependency_violations": copy.deepcopy(self.dependency_violations),
            "resource_conflicts": copy.deepcopy(self.resource_conflicts),
        }


@dataclass
class PlanningRevision:
    tasks: Any
    review: PlanReview
    parallel_groups: list[list[str]] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "tasks": [PlanningRevisionEngine._task_dict(task) for task in self.tasks],
            "review": self.review.to_dict(),
            "parallel_groups": copy.deepcopy(self.parallel_groups),
        }


class PlanningRevisionEngine:
    """Checks task plans and repairs only deterministic, mechanically safe defects."""

    def review(self, plan: Any) -> PlanReview:
        tasks = self._tasks(plan)
        review = PlanReview()
        by_id: dict[str, Any] = {}
        for index, task in enumerate(tasks):
            task_id = str(self._get(task, "id", self._get(task, "task_id", "")))
            if not task_id:
                review.issues.append({"type": "missing_id", "index": index})
            elif task_id in by_id:
                review.issues.append({"type": "duplicate_id", "task_id": task_id})
            else:
                by_id[task_id] = task

        completed = {
            task_id for task_id, task in by_id.items()
            if str(self._get(task, "status", "")).lower() in {"done", "completed", "success"}
        }
        for task_id, task in sorted(by_id.items()):
            dependencies = self._dependencies(task)
            for dependency in dependencies:
                if dependency not in by_id:
                    review.dependency_violations.append(
                        {"task_id": task_id, "dependency": dependency, "reason": "missing dependency"}
                    )
                elif dependency == task_id:
                    review.dependency_violations.append(
                        {"task_id": task_id, "dependency": dependency, "reason": "self dependency"}
                    )
                elif str(self._get(task, "status", "")).lower() in {"done", "completed", "success"} and dependency not in completed:
                    review.dependency_violations.append(
                        {"task_id": task_id, "dependency": dependency, "reason": "completed before prerequisite"}
                    )
        for left_index, left in enumerate(tasks):
            for right in tasks[left_index + 1:]:
                left_id = str(self._get(left, "id", self._get(left, "task_id", "")))
                right_id = str(self._get(right, "id", self._get(right, "task_id", "")))
                overlap = sorted(set(self._resources(left)) & set(self._resources(right)))
                if overlap and not self._has_dependency_path(left_id, right_id, by_id) and not self._has_dependency_path(right_id, left_id, by_id):
                    review.resource_conflicts.append({
                        "task_a": left_id, "task_b": right_id, "resources": overlap,
                    })
        review.issues.extend(self._cycle_issues(by_id))
        review.valid = not (
            review.issues or review.dependency_violations or review.resource_conflicts
        )
        return review

    def repair(self, plan: Any) -> Any:
        revised, tasks, wrapper_key = self._copy_plan(plan)
        by_id: dict[str, Any] = {}
        for task in tasks:
            task_id = str(self._get(task, "id", self._get(task, "task_id", "")))
            if task_id and task_id not in by_id:
                by_id[task_id] = task
        for task_id in sorted(by_id):
            task = by_id[task_id]
            dependencies = [
                dep for dep in self._dependencies(task)
                if dep in by_id and dep != task_id
            ]
            self._set_dependencies(task, list(dict.fromkeys(dependencies)))
        while True:
            cycle = self._find_cycle(by_id)
            if not cycle:
                break
            source, dependency = sorted(zip(cycle, cycle[1:]))[-1]
            task = by_id[source]
            self._set_dependencies(
                task, [item for item in self._dependencies(task) if item != dependency]
            )
        if isinstance(revised, dict) and wrapper_key is not None:
            revised[wrapper_key] = tasks
            return revised
        return tasks

    def optimize(self, plan: Any) -> PlanningRevision:
        repaired = self.repair(plan)
        tasks = self._tasks(repaired)
        review = self.review(repaired)
        by_id = {
            str(self._get(task, "id", self._get(task, "task_id", ""))): task
            for task in tasks
        }
        remaining = set(by_id)
        completed: set[str] = set()
        groups: list[list[str]] = []
        while remaining:
            ready = sorted(
                task_id for task_id in remaining
                if set(self._dependencies(by_id[task_id])) <= completed
            )
            if not ready:
                break
            group: list[str] = []
            resources: set[str] = set()
            for task_id in ready:
                task_resources = set(self._resources(by_id[task_id]))
                if not task_resources.intersection(resources):
                    group.append(task_id)
                    resources.update(task_resources)
            if not group:
                group = [ready[0]]
            groups.append(group)
            completed.update(group)
            remaining.difference_update(group)
        return PlanningRevision(repaired, review, groups)

    @classmethod
    def _tasks(cls, plan: Any) -> list[Any]:
        if isinstance(plan, Mapping):
            tasks = plan.get("tasks", [])
        else:
            tasks = plan
        return list(tasks) if isinstance(tasks, Sequence) and not isinstance(tasks, (str, bytes)) else []

    @classmethod
    def _copy_plan(cls, plan: Any) -> tuple[Any, list[Any], str | None]:
        revised = copy.deepcopy(plan)
        if isinstance(revised, dict):
            key = "tasks" if isinstance(revised.get("tasks"), list) else None
            return revised, revised.get(key, []) if key else [], key
        return revised, cls._tasks(revised), None

    @staticmethod
    def _task_dict(task: Any) -> dict[str, Any]:
        if isinstance(task, Mapping):
            return dict(task)
        if hasattr(task, "to_dict"):
            return task.to_dict()
        if hasattr(task, "__dict__"):
            return dict(task.__dict__)
        return {"value": str(task)}

    @staticmethod
    def _get(task: Any, key: str, default: Any = None) -> Any:
        return task.get(key, default) if isinstance(task, Mapping) else getattr(task, key, default)

    @classmethod
    def _dependencies(cls, task: Any) -> list[str]:
        values = cls._get(task, "dependencies", []) or []
        return [str(value) for value in values if value]

    @staticmethod
    def _set_dependencies(task: Any, dependencies: list[str]) -> None:
        if isinstance(task, dict):
            task["dependencies"] = dependencies
        else:
            task.dependencies = dependencies

    @classmethod
    def _resources(cls, task: Any) -> list[str]:
        values = cls._get(task, "resources", cls._get(task, "estimated_files", [])) or []
        return [str(value) for value in ([values] if isinstance(values, str) else values) if value]

    @classmethod
    def _has_dependency_path(cls, source: str, target: str, by_id: Mapping[str, Any]) -> bool:
        pending = list(cls._dependencies(by_id.get(target, {})))
        seen: set[str] = set()
        while pending:
            item = pending.pop()
            if item == source:
                return True
            if item not in seen:
                seen.add(item)
                pending.extend(cls._dependencies(by_id.get(item, {})))
        return False

    @classmethod
    def _find_cycle(cls, by_id: Mapping[str, Any]) -> list[str]:
        visited: set[str] = set()
        active: list[str] = []
        def visit(task_id: str) -> list[str]:
            if task_id in active:
                return active[active.index(task_id):] + [task_id]
            if task_id in visited:
                return []
            active.append(task_id)
            for dependency in sorted(cls._dependencies(by_id[task_id])):
                if dependency in by_id:
                    result = visit(dependency)
                    if result:
                        return result
            active.pop()
            visited.add(task_id)
            return []
        for task_id in sorted(by_id):
            result = visit(task_id)
            if result:
                return result
        return []

    @classmethod
    def _cycle_issues(cls, by_id: Mapping[str, Any]) -> list[dict[str, Any]]:
        cycle = cls._find_cycle(by_id)
        return [{"type": "dependency_cycle", "tasks": cycle}] if cycle else []

core/providers/gemini_provider.py.content:
"""
gemini_provider.py - Google Gemini LLM Provider for AutoDev

Integrates Google's Gemini models (e.g. gemini-1.5-pro, gemini-1.5-flash, gemini-2.0-flash)
with comprehensive error mapping for authentication, connection, and API response issues.
"""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from typing import Any, Dict, Optional

from core.llm import BaseLLM
from core.providers.exceptions import (
    ProviderAuthenticationError,
    ProviderConnectionError,
    ProviderResponseError,
)


class GeminiProvider(BaseLLM):
    """
    Google Gemini LLM provider integration.
    """

    DEFAULT_MODEL = "gemini-1.5-pro"
    API_URL_TEMPLATE = "https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"

    def __init__(
        self,
        model_name: Optional[str] = None,
        api_key: Optional[str] = None,
        temperature: float = 0.7,
        max_tokens: Optional[int] = None,
        client: Optional[Any] = None,
        **kwargs: Any,
    ) -> None:
        """
        Initializes the GeminiProvider.

        Args:
            model_name: Name of the Gemini model (default: 'gemini-1.5-pro').
            api_key: API key. If not provided, reads from GEMINI_API_KEY or GOOGLE_API_KEY env vars.
            temperature: Sampling temperature between 0.0 and 2.0 (default: 0.7).
            max_tokens: Maximum output tokens.
            client: Optional pre-configured or mocked SDK client.
            **kwargs: Additional parameters passed to BaseLLM.

        Raises:
            ProviderAuthenticationError: If no API key is provided or found in the environment.
        """
        resolved_key = (
            api_key
            or os.environ.get("GEMINI_API_KEY")
            or os.environ.get("GOOGLE_API_KEY")
        )
        if not resolved_key or not resolved_key.strip():
            raise ProviderAuthenticationError(
                "Gemini API key is required. Set GEMINI_API_KEY or GOOGLE_API_KEY environment variable.",
                provider="gemini",
            )

        super().__init__(
            model_name=model_name or self.DEFAULT_MODEL,
            api_key=resolved_key.strip(),
            temperature=temperature,
            max_tokens=max_tokens,
            **kwargs,
        )
        self.client = client

    def generate(self, prompt: str, **kwargs: Any) -> str:
        """
        Generates a completion from Google Gemini.

        Args:
            prompt: The input prompt string.
            **kwargs: Generation overrides (e.g. temperature, max_tokens, model).

        Returns:
            The generated response string.

        Raises:
            ProviderAuthenticationError: On invalid API key or 401/403 status.
            ProviderConnectionError: On network or socket failure.
            ProviderResponseError: On bad status, rate limits, or malformed responses.
        """
        if not prompt or not prompt.strip():
            return ""

        model = kwargs.get("model") or kwargs.get("model_name") or self.model_name
        temperature = kwargs.get("temperature", self.temperature)
        max_tokens = kwargs.get("max_tokens", self.max_tokens)

        # 1. If an injected SDK client exists, use it
        if self.client is not None:
            return self._generate_with_client(self.client, prompt, model, temperature, max_tokens, **kwargs)

        # 2. Check for official google.genai SDK
        try:
            from google import genai
            from google.genai import types

            client = genai.Client(api_key=self.api_key)
            config = types.GenerateContentConfig(
                temperature=temperature,
                max_output_tokens=max_tokens,
            )
            response = client.models.generate_content(
                model=model,
                contents=prompt,
                config=config,
            )
            if hasattr(response, "text") and response.text is not None:
                return str(response.text)
            raise ProviderResponseError(
                "Gemini SDK returned an empty or invalid content response.",
                provider="gemini",
            )
        except ImportError:
            # Fall back to HTTP REST endpoint
            return self._generate_with_http(prompt, model, temperature, max_tokens)
        except (ProviderAuthenticationError, ProviderConnectionError, ProviderResponseError):
            raise
        except Exception as exc:
            self._handle_exception(exc)
            raise ProviderResponseError(f"Unexpected error communicating with Gemini: {exc}", provider="gemini")

    def _generate_with_client(
        self,
        client: Any,
        prompt: str,
        model: str,
        temperature: float,
        max_tokens: Optional[int],
        **kwargs: Any,
    ) -> str:
        """Executes generation using an injected client object."""
        try:
            # Check for models.generate_content (google.genai style)
            if hasattr(client, "models") and hasattr(client.models, "generate_content"):
                resp = client.models.generate_content(model=model, contents=prompt, **kwargs)
                if hasattr(resp, "text"):
                    return str(resp.text)
                return str(resp)

            # Check for generate_content (google.generativeai GenerativeModel style)
            if hasattr(client, "generate_content"):
                resp = client.generate_content(prompt, **kwargs)
                if hasattr(resp, "text"):
                    return str(resp.text)
                return str(resp)

            # Check for callable client
            if callable(client):
                return str(client(prompt, **kwargs))

            raise ProviderResponseError(
                f"Injected client {type(client)} does not support generate_content.",
                provider="gemini",
            )
        except (ProviderAuthenticationError, ProviderConnectionError, ProviderResponseError):
            raise
        except Exception as exc:
            self._handle_exception(exc)
            raise ProviderResponseError(f"Error from Gemini client: {exc}", provider="gemini")

    def _generate_with_http(
        self,
        prompt: str,
        model: str,
        temperature: float,
        max_tokens: Optional[int],
    ) -> str:
        """Executes generation using standard HTTP POST to Gemini REST API."""
        url = self.API_URL_TEMPLATE.format(model=model) + f"?key={self.api_key}"
        payload: Dict[str, Any] = {
            "contents": [{"parts": [{"text": prompt}]}],
            "generationConfig": {
                "temperature": temperature,
            },
        }
        if max_tokens is not None:
            payload["generationConfig"]["maxOutputTokens"] = max_tokens

        req_data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(
            url,
            data=req_data,
            headers={"Content-Type": "application/json"},
            method="POST",
        )

        try:
            with urllib.request.urlopen(req, timeout=60.0) as resp:
                resp_data = resp.read().decode("utf-8")
                parsed = json.loads(resp_data)
                candidates = parsed.get("candidates", [])
                if not candidates:
                    raise ProviderResponseError("Gemini returned no response candidates.", provider="gemini")
                content = candidates[0].get("content", {})
                parts = content.get("parts", [])
                if not parts or "text" not in parts[0]:
                    raise ProviderResponseError("Gemini response missing text in candidate parts.", provider="gemini")
                return str(parts[0]["text"])
        except urllib.error.HTTPError as http_err:
            status = http_err.code
            body = ""
            try:
                body = http_err.read().decode("utf-8")
            except Exception:
                pass

            if status in (401, 403):
                raise ProviderAuthenticationError(
                    f"Gemini authentication failed (HTTP {status}): {body or http_err.reason}",
                    provider="gemini",
                )
            if status == 429:
                raise ProviderResponseError(
                    f"Gemini rate limit exceeded (HTTP 429): {body or http_err.reason}",
                    provider="gemini",
                )
            raise ProviderResponseError(
                f"Gemini API returned error (HTTP {status}): {body or http_err.reason}",
                provider="gemini",
            )
        except (urllib.error.URLError, TimeoutError, OSError) as net_err:
            raise ProviderConnectionError(
                f"Failed to connect to Gemini API endpoint: {net_err}",
                provider="gemini",
            )
        except (ProviderAuthenticationError, ProviderConnectionError, ProviderResponseError):
            raise
        except Exception as exc:
            raise ProviderResponseError(f"Failed to process Gemini response: {exc}", provider="gemini")

    def _handle_exception(self, exc: Exception) -> None:
        """Maps third-party SDK exceptions to typed provider exceptions."""
        exc_str = str(exc).lower()
        exc_type = type(exc).__name__.lower()

        if any(w in exc_str or w in exc_type for w in ("auth", "permission", "api_key", "401", "403", "unauthenticated", "unauthorized")):
            raise ProviderAuthenticationError(f"Gemini authentication failed: {exc}", provider="gemini")
        if any(w in exc_str or w in exc_type for w in ("connection", "timeout", "socket", "network", "unreachable", "dns")):
            raise ProviderConnectionError(f"Gemini connection error: {exc}", provider="gemini")
        if any(w in exc_str or w in exc_type for w in ("rate", "quota", "429", "500", "503", "overloaded")):
            raise ProviderResponseError(f"Gemini rate limit or server error: {exc}", provider="gemini")

core/providers/openai_provider.py.content:
"""
openai_provider.py - OpenAI LLM Provider for AutoDev

Integrates OpenAI models (e.g. gpt-4o, gpt-4o-mini, gpt-4-turbo, o1)
with comprehensive error mapping for authentication, connection, and API response issues.
"""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from typing import Any, Dict, Optional

from core.llm import BaseLLM
from core.providers.exceptions import (
    ProviderAuthenticationError,
    ProviderConnectionError,
    ProviderResponseError,
)


class OpenAIProvider(BaseLLM):
    """
    OpenAI LLM provider integration.
    """

    DEFAULT_MODEL = "gpt-4o"
    API_URL = "https://api.openai.com/v1/chat/completions"

    def __init__(
        self,
        model_name: Optional[str] = None,
        api_key: Optional[str] = None,
        temperature: float = 0.7,
        max_tokens: Optional[int] = None,
        client: Optional[Any] = None,
        organization: Optional[str] = None,
        **kwargs: Any,
    ) -> None:
        """
        Initializes the OpenAIProvider.

        Args:
            model_name: Name of the OpenAI model (default: 'gpt-4o').
            api_key: API key. If not provided, reads from OPENAI_API_KEY env var.
            temperature: Sampling temperature between 0.0 and 2.0 (default: 0.7).
            max_tokens: Maximum output tokens.
            client: Optional pre-configured or mocked SDK client.
            organization: Optional OpenAI organization ID.
            **kwargs: Additional parameters passed to BaseLLM.

        Raises:
            ProviderAuthenticationError: If no API key is provided or found in the environment.
        """
        resolved_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not resolved_key or not resolved_key.strip():
            raise ProviderAuthenticationError(
                "OpenAI API key is required. Set OPENAI_API_KEY environment variable.",
                provider="openai",
            )

        super().__init__(
            model_name=model_name or self.DEFAULT_MODEL,
            api_key=resolved_key.strip(),
            temperature=temperature,
            max_tokens=max_tokens,
            **kwargs,
        )
        self.client = client
        self.organization = organization or os.environ.get("OPENAI_ORG_ID")

    def generate(self, prompt: str, **kwargs: Any) -> str:
        """
        Generates a completion from OpenAI.

        Args:
            prompt: The input prompt string.
            **kwargs: Generation overrides (e.g. temperature, max_tokens, model).

        Returns:
            The generated response string.

        Raises:
            ProviderAuthenticationError: On invalid API key or 401/403 status.
            ProviderConnectionError: On network or socket failure.
            ProviderResponseError: On bad status, rate limits, or malformed responses.
        """
        if not prompt or not prompt.strip():
            return ""

        model = kwargs.get("model") or kwargs.get("model_name") or self.model_name
        temperature = kwargs.get("temperature", self.temperature)
        max_tokens = kwargs.get("max_tokens", self.max_tokens)

        # 1. If an injected SDK client exists, use it
        if self.client is not None:
            return self._generate_with_client(self.client, prompt, model, temperature, max_tokens, **kwargs)

        # 2. Check for official openai SDK
        try:
            import openai

            client_kwargs: Dict[str, Any] = {"api_key": self.api_key}
            if self.organization:
                client_kwargs["organization"] = self.organization

            client = openai.OpenAI(**client_kwargs)
            completion_kwargs: Dict[str, Any] = {
                "model": model,
                "messages": [{"role": "user", "content": prompt}],
                "temperature": temperature,
            }
            if max_tokens is not None:
                completion_kwargs["max_tokens"] = max_tokens

            response = client.chat.completions.create(**completion_kwargs)
            if hasattr(response, "choices") and response.choices:
                choice = response.choices[0]
                if hasattr(choice, "message") and hasattr(choice.message, "content"):
                    return str(choice.message.content or "")
            raise ProviderResponseError(
                "OpenAI SDK returned empty or invalid choices in response.",
                provider="openai",
            )
        except ImportError:
            # Fall back to HTTP REST endpoint
            return self._generate_with_http(prompt, model, temperature, max_tokens)
        except (ProviderAuthenticationError, ProviderConnectionError, ProviderResponseError):
            raise
        except Exception as exc:
            self._handle_exception(exc)
            raise ProviderResponseError(f"Unexpected error communicating with OpenAI: {exc}", provider="openai")

    def _generate_with_client(
        self,
        client: Any,
        prompt: str,
        model: str,
        temperature: float,
        max_tokens: Optional[int],
        **kwargs: Any,
    ) -> str:
        """Executes generation using an injected client object."""
        try:
            # Check for chat.completions.create (openai.OpenAI style)
            if hasattr(client, "chat") and hasattr(client.chat, "completions"):
                completion_kwargs: Dict[str, Any] = {
                    "model": model,
                    "messages": [{"role": "user", "content": prompt}],
                    "temperature": temperature,
                }
                if max_tokens is not None:
                    completion_kwargs["max_tokens"] = max_tokens
                resp = client.chat.completions.create(**completion_kwargs)
                if hasattr(resp, "choices") and resp.choices:
                    choice = resp.choices[0]
                    if hasattr(choice, "message") and hasattr(choice.message, "content"):
                        return str(choice.message.content or "")
                return str(resp)

            # Check for callable client
            if callable(client):
                return str(client(prompt, **kwargs))

            raise ProviderResponseError(
                f"Injected client {type(client)} does not support chat completions.",
                provider="openai",
            )
        except (ProviderAuthenticationError, ProviderConnectionError, ProviderResponseError):
            raise
        except Exception as exc:
            self._handle_exception(exc)
            raise ProviderResponseError(f"Error from OpenAI client: {exc}", provider="openai")

    def _generate_with_http(
        self,
        prompt: str,
        model: str,
        temperature: float,
        max_tokens: Optional[int],
    ) -> str:
        """Executes generation using standard HTTP POST to OpenAI REST API."""
        payload: Dict[str, Any] = {
            "model": model,
            "messages": [{"role": "user", "content": prompt}],
            "temperature": temperature,
        }
        if max_tokens is not None:
            payload["max_tokens"] = max_tokens

        req_data = json.dumps(payload).encode("utf-8")
        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.api_key}",
        }
        if self.organization:
            headers["OpenAI-Organization"] = self.organization

        req = urllib.request.Request(
            self.API_URL,
            data=req_data,
            headers=headers,
            method="POST",
        )

        try:
            with urllib.request.urlopen(req, timeout=60.0) as resp:
                resp_data = resp.read().decode("utf-8")
                parsed = json.loads(resp_data)
                choices = parsed.get("choices", [])
                if not choices:
                    raise ProviderResponseError("OpenAI returned no response choices.", provider="openai")
                message = choices[0].get("message", {})
                content = message.get("content", "")
                return str(content or "")
        except urllib.error.HTTPError as http_err:
            status = http_err.code
            body = ""
            try:
                body = http_err.read().decode("utf-8")
            except Exception:
                pass

            if status in (401, 403):
                raise ProviderAuthenticationError(
                    f"OpenAI authentication failed (HTTP {status}): {body or http_err.reason}",
                    provider="openai",
                )
            if status == 429:
                raise ProviderResponseError(
                    f"OpenAI rate limit exceeded (HTTP 429): {body or http_err.reason}",
                    provider="openai",
                )
            raise ProviderResponseError(
                f"OpenAI API returned error (HTTP {status}): {body or http_err.reason}",
                provider="openai",
            )
        except (urllib.error.URLError, TimeoutError, OSError) as net_err:
            raise ProviderConnectionError(
                f"Failed to connect to OpenAI API endpoint: {net_err}",
                provider="openai",
            )
        except (ProviderAuthenticationError, ProviderConnectionError, ProviderResponseError):
            raise
        except Exception as exc:
            raise ProviderResponseError(f"Failed to process OpenAI response: {exc}", provider="openai")

    def _handle_exception(self, exc: Exception) -> None:
        """Maps third-party SDK exceptions to typed provider exceptions."""
        exc_str = str(exc).lower()
        exc_type = type(exc).__name__.lower()

        if any(w in exc_str or w in exc_type for w in ("auth", "permission", "api_key", "401", "403", "unauthorized")):
            raise ProviderAuthenticationError(f"OpenAI authentication failed: {exc}", provider="openai")
        if any(w in exc_str or w in exc_type for w in ("connection", "timeout", "socket", "network", "unreachable", "dns")):
            raise ProviderConnectionError(f"OpenAI connection error: {exc}", provider="openai")
        if any(w in exc_str or w in exc_type for w in ("rate", "quota", "429", "500", "503", "overloaded")):
            raise ProviderResponseError(f"OpenAI rate limit or server error: {exc}", provider="openai")

