"""Produces deterministic engineering recommendations from project history."""

from __future__ import annotations

from typing import Any, Mapping

from core.engineering_memory import EngineeringMemory
from core.engineering_search import EngineeringSearchEngine
from core.memory_ranking import MemoryRankingEngine


class RecommendationEngine:
    """Ranks evidence-backed recommendations from engineering records."""

    def __init__(
        self,
        memory: EngineeringMemory,
        search_engine: EngineeringSearchEngine | None = None,
        ranking_engine: MemoryRankingEngine | None = None,
    ) -> None:
        self.memory = memory
        self.search_engine = search_engine or EngineeringSearchEngine(memory)
        self.ranking_engine = ranking_engine or MemoryRankingEngine()

    def recommend(
        self,
        context: str | Mapping[str, Any] = "",
        *,
        limit: int = 10,
    ) -> list[dict[str, Any]]:
        if limit < 0:
            raise ValueError("limit must not be negative.")
        query = context if isinstance(context, str) else " ".join(
            str(context.get(key, "")) for key in ("goal", "task", "summary", "files")
        )
        matches = self.search_engine.search(query, limit=max(limit * 4, limit))
        recommendations = []
        seen = set()
        for match in matches:
            record = match.get("record")
            if not isinstance(record, dict):
                continue
            suggestion = record.get("recommendation", record.get("solution"))
            if not suggestion:
                continue
            normalized = str(suggestion).strip()
            if not normalized or normalized.casefold() in seen:
                continue
            seen.add(normalized.casefold())
            recommendations.append({
                "recommendation": normalized,
                "source_record_id": record.get("record_id"),
                "source_type": record.get("type"),
                "confidence": float(record.get("confidence", match.get("score", 0.0))),
                "success": record.get("success"),
                "score": float(match.get("score", 0.0)),
                "evidence": _evidence(record),
            })
        return sorted(
            recommendations,
            key=lambda item: (-item["score"], -item["confidence"], str(item["source_record_id"])),
        )[:limit]

    def recommend_for_task(
        self,
        task: Mapping[str, Any],
        *,
        limit: int = 10,
    ) -> list[dict[str, Any]]:
        return self.recommend(task, limit=limit)


def _evidence(record: Mapping[str, Any]) -> dict[str, Any]:
    return {
        key: record[key]
        for key in ("task_id", "timestamp", "success", "benchmark", "review")
        if key in record
    }

core/regression_test_selector.py.content:
"""
AutoDev Regression Test Selector (v2.6)
Selects risk-proportional regression tests across four validation levels
using static impact analysis and symbol graph relationships.
"""

from __future__ import annotations

import ast
import logging
import os
import re
from dataclasses import asdict, dataclass, field
from typing import Any, Dict, List, Optional, Set

from core.repair_models import CandidatePatch

logger = logging.getLogger(__name__)

SECURITY_MODULES = {"auth", "crypto", "consensus", "isolation", "sandbox", "fencing", "transaction"}


@dataclass
class TestSelectionResult:
    """Outcome of regression test selection analysis."""
    validation_level: str
    selected_tests: List[str] = field(default_factory=list)
    rationale: Dict[str, str] = field(default_factory=dict)  # test_path -> selection reason
    escalated: bool = False
    escalation_reason: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


class RegressionTestSelector:
    """Selects targeted and regression test suites based on patch blast radius and risk."""

    def __init__(self, workspace_path: str, all_discovered_tests: Optional[List[str]] = None):
        self.workspace_path = os.path.realpath(os.path.abspath(workspace_path))
        self.all_discovered_tests = all_discovered_tests or self._discover_all_test_files()

    def _discover_all_test_files(self) -> List[str]:
        """Discovers all test files in the workspace tests/ directory."""
        test_dir = os.path.join(self.workspace_path, "tests")
        if not os.path.isdir(test_dir):
            return []

        tests = []
        for root, _, files in os.walk(test_dir):
            for file in files:
                if file.startswith("test_") and file.endswith(".py"):
                    rel_path = os.path.relpath(os.path.join(root, file), self.workspace_path)
                    tests.append(rel_path.replace("\\", "/"))
        return sorted(tests)

    def select_tests(
        self,
        patch: CandidatePatch,
        validation_level: str = "standard",
        primary_failing_test: Optional[str] = None,
    ) -> TestSelectionResult:
        """Selects proportional test suite for verifying a candidate patch."""
        selected: Set[str] = set()
        rationale: Dict[str, str] = {}
        escalated = False
        escalation_reason = None

        # Always include the primary failing test target
        if primary_failing_test:
            selected.add(primary_failing_test)
            rationale[primary_failing_test] = "Primary failing test target"

        modified_files = patch.modified_files

        # Check for security escalation
        for f in modified_files:
            f_lower = f.lower()
            if any(sec in f_lower for sec in SECURITY_MODULES):
                if validation_level in ("targeted", "standard"):
                    validation_level = "comprehensive"
                    escalated = True
                    escalation_reason = f"Escalated to comprehensive due to security-sensitive file: {f}"
                break

        # Level: Full Suite
        if validation_level == "full_suite":
            for t in self.all_discovered_tests:
                selected.add(t)
                if t not in rationale:
                    rationale[t] = "Full suite execution policy"
            return TestSelectionResult(
                validation_level=validation_level,
                selected_tests=sorted(list(selected)),
                rationale=rationale,
                escalated=escalated,
                escalation_reason=escalation_reason,
            )

        # 1. Direct unit tests corresponding to modified files (e.g. core/foo.py -> tests/test_foo.py)
        for f in modified_files:
            basename = os.path.splitext(os.path.basename(f))[0]
            expected_test_name = f"test_{basename}.py"

            for t in self.all_discovered_tests:
                if expected_test_name in t:
                    selected.add(t)
                    rationale[t] = f"Direct unit test for modified module {f}"

        # Level: Targeted - return after direct matching
        if validation_level == "targeted":
            if not selected and primary_failing_test:
                selected.add(primary_failing_test)
            # Fallback if no test found
            if not selected and self.all_discovered_tests:
                selected.add(self.all_discovered_tests[0])
                rationale[self.all_discovered_tests[0]] = "Fallback test target"
            return TestSelectionResult(
                validation_level=validation_level,
                selected_tests=sorted(list(selected)),
                rationale=rationale,
                escalated=escalated,
                escalation_reason=escalation_reason,
            )

        # 2. Level: Standard - add importing and dependent tests
        for f in modified_files:
            module_name = os.path.splitext(os.path.basename(f))[0]
            for t in self.all_discovered_tests:
                if t in selected:
                    continue
                if self._test_imports_module(t, module_name):
                    selected.add(t)
                    rationale[t] = f"Test imports or references {module_name}"

        if validation_level == "standard":
            return TestSelectionResult(
                validation_level=validation_level,
                selected_tests=sorted(list(selected)),
                rationale=rationale,
                escalated=escalated,
                escalation_reason=escalation_reason,
            )

        # 3. Level: Comprehensive - add integration and end-to-end tests
        for t in self.all_discovered_tests:
            if "integration" in t.lower() or "e2e" in t.lower():
                selected.add(t)
                if t not in rationale:
                    rationale[t] = "Integration regression suite covering subsystem boundaries"

        return TestSelectionResult(
            validation_level=validation_level,
            selected_tests=sorted(list(selected)),
            rationale=rationale,
            escalated=escalated,
            escalation_reason=escalation_reason,
        )

    def _test_imports_module(self, test_rel_path: str, module_name: str) -> bool:
        """Inspects test file imports using AST to see if it depends on module_name."""
        abs_path = os.path.join(self.workspace_path, test_rel_path)
        if not os.path.isfile(abs_path):
            return False

        try:
            with open(abs_path, "r", encoding="utf-8", errors="replace") as f:
                content = f.read()

            # Fast string check before AST parse
            if module_name not in content:
                return False

            tree = ast.parse(content, filename=abs_path)
            for node in ast.walk(tree):
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if module_name in alias.name:
                            return True
                elif isinstance(node, ast.ImportFrom):
                    if node.module and module_name in node.module:
                        return True
            return False
        except Exception:
            return module_name in content

core/research_engine.py.content:
"""Deterministic research planning and findings for autonomous evolution."""

from __future__ import annotations

import hashlib
import json
import math
import os
import tempfile
from pathlib import Path
from typing import Any, Mapping, Sequence

from core.statistical_analyzer import StatisticalAnalyzer


_SEVERITY = {"CRITICAL": 4, "HIGH": 3, "MEDIUM": 2, "LOW": 1}


class ResearchEngine:
    """Finds engineering problems, evaluates research plans, and publishes results."""

    def __init__(self, storage_dir: str | Path | None = None) -> None:
        self.storage_dir = Path(storage_dir) if storage_dir is not None else None
        self.findings: list[dict[str, Any]] = []
        if self.storage_dir is not None:
            self._load_findings()

    def discover_problems(
        self,
        observations: Mapping[str, Any] | None = None,
    ) -> list[dict[str, Any]]:
        """Returns evidence-backed problems ordered by severity and stable ID."""
        data = observations or {}
        candidates: list[dict[str, Any]] = []

        def add(title: str, severity: str, evidence: Mapping[str, Any]) -> None:
            normalized = dict(sorted(evidence.items()))
            problem_id = _stable_id(title, normalized)
            candidates.append({
                "problem_id": problem_id,
                "title": title,
                "severity": severity,
                "evidence": normalized,
                "confidence": 0.9 if normalized else 0.5,
            })

        for problem in data.get("problems", []):
            if not isinstance(problem, Mapping):
                continue
            title = str(problem.get("title", "")).strip()
            if title:
                severity = str(problem.get("severity", "MEDIUM")).upper()
                if severity not in _SEVERITY:
                    severity = "MEDIUM"
                add(title, severity, problem.get("evidence", {}))

        quality = data.get("code_quality", {})
        if isinstance(quality, Mapping):
            for cycle in quality.get("architecture_violations", []):
                add("Architecture boundary violation", "HIGH", {"violation": str(cycle)})
            if quality.get("duplication_ratio", 0) >= 10:
                add(
                    "Elevated code duplication",
                    "MEDIUM",
                    {"duplication_ratio": quality["duplication_ratio"]},
                )
            if quality.get("dead_code_candidates"):
                add(
                    "Potential dead code",
                    "LOW",
                    {"candidate_count": len(quality["dead_code_candidates"])},
                )
            if quality.get("complexity_hotspots"):
                add(
                    "High-complexity modules",
                    "HIGH",
                    {"hotspots": list(quality["complexity_hotspots"])},
                )

        architecture = data.get("architecture", {})
        if isinstance(architecture, Mapping) and architecture.get("circular_dependencies"):
            add(
                "Circular module dependencies",
                "HIGH",
                {"cycles": list(architecture["circular_dependencies"])},
            )

        performance = data.get("performance", {})
        if isinstance(performance, Mapping):
            for stage in ("planning", "scheduling", "execution", "learning"):
                value = performance.get(stage)
                if isinstance(value, (int, float)) and value > 1.0:
                    add(
                        f"High {stage} latency",
                        "MEDIUM",
                        {"stage": stage, "latency_seconds": float(value)},
                    )

        return sorted(
            candidates,
            key=lambda item: (
                -_SEVERITY[item["severity"]],
                -item["confidence"],
                item["problem_id"],
            ),
        )

    def discover_problem(
        self,
        observations: Mapping[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Returns the highest-priority discovered problem, or ``None``."""
        problems = self.discover_problems(observations)
        return problems[0] if problems else None

    def generate_research_plan(
        self,
        problem: Mapping[str, Any] | str,
        alternatives: Sequence[str] | None = None,
        *,
        metric: str = "maintainability",
        higher_is_better: bool = True,
    ) -> dict[str, Any]:
        """Creates a measurable, stable plan for comparing engineering alternatives."""
        problem_data = (
            dict(problem)
            if isinstance(problem, Mapping)
            else {"problem_id": _stable_id(str(problem)), "title": str(problem)}
        )
        title = str(problem_data.get("title", "Engineering improvement"))
        options = sorted({
            str(value).strip()
            for value in (alternatives or ("current_design", "simplified_design"))
            if str(value).strip()
        })
        if len(options) < 2:
            options = sorted(set(options) | {"current_design", "simplified_design"})
        plan_id = _stable_id(str(problem_data.get("problem_id", title)), options, metric)
        baseline = (
            "current_design"
            if "current_design" in options
            else options[0]
        )
        return {
            "plan_id": plan_id,
            "problem_id": str(problem_data.get("problem_id", _stable_id(title))),
            "goal": f"Improve {metric} for: {title}",
            "alternatives": options,
            "baseline": baseline,
            "metric": metric,
            "higher_is_better": bool(higher_is_better),
            "evaluation_criteria": [
                "Compare equivalent inputs and workloads.",
                "Require repeatable measurements before selecting a winner.",
                "Retain the baseline when evidence is inconclusive.",
            ],
            "steps": [
                "Record a baseline using the declared metric.",
                "Evaluate each alternative in an isolated experiment.",
                "Compare results and publish the evidence-backed finding.",
            ],
        }

    def evaluate_results(
        self,
        plan: Mapping[str, Any],
        results: Mapping[str, Any],
        *,
        alpha: float = 0.05,
    ) -> dict[str, Any]:
        """Ranks alternative result samples and reports statistical evidence."""
        if not 0.0 < alpha < 1.0:
            raise ValueError("alpha must be between 0 and 1.")
        higher_is_better = bool(plan.get("higher_is_better", True))
        evaluated: list[dict[str, Any]] = []
        for name in sorted(results):
            value = results[name]
            if isinstance(value, Mapping):
                raw_samples = value.get("samples", [value.get("score", 0.0)])
            else:
                raw_samples = value if isinstance(value, Sequence) and not isinstance(value, (str, bytes)) else [value]
            samples = [float(sample) for sample in raw_samples]
            if not samples:
                raise ValueError(f"Alternative {name!r} has no result samples.")
            if any(not math.isfinite(sample) for sample in samples):
                raise ValueError(f"Alternative {name!r} contains a non-finite result sample.")
            evaluated.append({
                "alternative": str(name),
                "samples": samples,
                "mean": StatisticalAnalyzer.mean(samples),
                "statistics": StatisticalAnalyzer.summarize(samples).to_dict(),
            })

        if not evaluated:
            winner = None
        else:
            evaluated.sort(
                key=lambda item: (
                    -item["mean"] if higher_is_better else item["mean"],
                    item["alternative"],
                )
            )
            winner = evaluated[0]["alternative"]
        baseline_name = str(plan.get("baseline", "current_design"))
        baseline = next(
            (item for item in evaluated if item["alternative"] == baseline_name),
            None,
        )
        comparisons = {}
        if baseline is not None:
            for item in evaluated:
                if item is baseline:
                    continue
                test = StatisticalAnalyzer.t_test_two_sample(
                    sample_a=item["samples"],
                    sample_b=baseline["samples"],
                    alpha=alpha,
                )
                comparisons[item["alternative"]] = test.to_dict()
        return {
            "plan_id": str(plan.get("plan_id", "")),
            "winner": winner,
            "is_conclusive": any(
                comparison["is_significant"] for comparison in comparisons.values()
            ),
            "alternatives": evaluated,
            "comparisons": comparisons,
        }

    def publish_findings(
        self,
        finding: Mapping[str, Any],
        *,
        knowledge_graph: Any = None,
    ) -> dict[str, Any]:
        """Stores a stable finding in memory and optionally links it to the graph."""
        record = dict(finding)
        record.setdefault("finding_id", _stable_id(record))
        record = json.loads(json.dumps(record, sort_keys=True, default=str))
        if not any(item.get("finding_id") == record["finding_id"] for item in self.findings):
            self.findings.append(record)
            self.findings.sort(key=lambda item: item["finding_id"])
        if knowledge_graph is not None:
            knowledge_graph.add_node(
                "research",
                record["finding_id"],
                str(record.get("title", record.get("goal", "Research finding"))),
                record,
            )
        if self.storage_dir is not None:
            self._persist_findings()
        return record

    def _persist_findings(self) -> None:
        assert self.storage_dir is not None
        self.storage_dir.mkdir(parents=True, exist_ok=True)
        target = self.storage_dir / "research_findings.json"
        temporary: Path | None = None
        try:
            with tempfile.NamedTemporaryFile(
                "w", encoding="utf-8", dir=self.storage_dir, delete=False
            ) as stream:
                json.dump(self.findings, stream, indent=2, sort_keys=True)
                temporary = Path(stream.name)
            os.replace(temporary, target)
        except OSError:
            if temporary is not None:
                temporary.unlink(missing_ok=True)
            raise

    def _load_findings(self) -> None:
        assert self.storage_dir is not None
        target = self.storage_dir / "research_findings.json"
        try:
            data = json.loads(target.read_text(encoding="utf-8"))
        except FileNotFoundError:
            return
        except json.JSONDecodeError as exc:
            raise ValueError(f"Research findings file {target} is not valid JSON.") from exc
        if not isinstance(data, list) or any(
            not isinstance(item, dict) or not isinstance(item.get("finding_id"), str)
            for item in data
        ):
            raise ValueError(f"Research findings file {target} must contain findings with string IDs.")
        self.findings = sorted(data, key=lambda item: item["finding_id"])


def _stable_id(*parts: Any) -> str:
    encoded = json.dumps(parts, sort_keys=True, separators=(",", ":"), default=str)
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()[:16]

