"""Deterministic schedule, architecture, dependency, resource, and quality risk analysis."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Optional


@dataclass
class RiskAssessment:
    risks: list[dict[str, Any]] = field(default_factory=list)
    mitigation_plan: list[dict[str, str]] = field(default_factory=list)

    @property
    def risk_count(self) -> int:
        return len(self.risks)

    def to_dict(self) -> dict[str, Any]:
        return {
            "risk_count": self.risk_count,
            "risks": list(self.risks),
            "mitigation_plan": list(self.mitigation_plan),
        }


class RiskManager:
    """Turns explicit project signals into sorted risks and practical mitigations."""

    def analyze(
        self,
        signals: Optional[dict[str, Any]] = None,
        resource_manager: Optional[Any] = None,
    ) -> RiskAssessment:
        values = dict(signals or {})
        risks: list[dict[str, Any]] = []
        self._add(risks, "schedule", int(values.get("overdue_milestones", 0)) > 0 or float(values.get("schedule_variance", 0)) > 0,
                  "HIGH", "Milestones are overdue or behind schedule.")
        self._add(risks, "architecture", float(values.get("architecture_risk_score", 0)) >= 70,
                  "HIGH", "Architecture risk score exceeds the review threshold.")
        self._add(risks, "technical_debt", int(values.get("technical_debt_items", 0)) > 0,
                  "MEDIUM", "Technical debt items are accumulating.")
        self._add(risks, "dependency", int(values.get("dependency_bottlenecks", 0)) > 0,
                  "HIGH", "Dependency bottlenecks may block the critical path.")
        self._add(risks, "quality", float(values.get("quality_score", 100)) < 80 or float(values.get("quality_trend", 0)) < 0,
                  "HIGH", "Quality is below target or trending downward.")
        if resource_manager is not None:
            demand = values.get("resource_demand", {})
            forecast = resource_manager.forecast(demand)
            for resource, estimate in forecast.items():
                if estimate["sufficient"] is False:
                    risks.append({
                        "category": "resource",
                        "severity": "HIGH",
                        "description": f"Insufficient {resource} capacity for planned demand.",
                        "resource": resource,
                    })
        risks.sort(key=lambda item: ({"CRITICAL": 0, "HIGH": 1, "MEDIUM": 2, "LOW": 3}[item["severity"]], item["category"]))
        mitigation = [
            {
                "risk": item["category"],
                "action": self._mitigation(item["category"]),
            }
            for item in risks
        ]
        return RiskAssessment(risks=risks, mitigation_plan=mitigation)

    @staticmethod
    def _add(risks: list[dict[str, Any]], category: str, present: bool, severity: str, description: str) -> None:
        if present:
            risks.append({"category": category, "severity": severity, "description": description})

    @staticmethod
    def _mitigation(category: str) -> str:
        actions = {
            "schedule": "Re-sequence milestones and protect critical-path capacity.",
            "architecture": "Schedule an architecture review and document the accepted decision.",
            "technical_debt": "Prioritize debt items with the affected delivery work.",
            "dependency": "Resolve or isolate the blocking dependency before downstream work.",
            "quality": "Add focused validation and review the quality regression before release.",
            "resource": "Rebalance queued allocations or reduce concurrent demand.",
        }
        return actions[category]

core/self_optimizer.py.content:
"""Recommendation-only self-optimization across AutoDev engineering domains."""

from __future__ import annotations

from typing import Any, Mapping


class SelfOptimizer:
    """Produces measured optimization proposals without changing runtime behavior."""

    DOMAINS = (
        "planning",
        "scheduling",
        "prompting",
        "reasoning",
        "collaboration",
        "learning",
        "execution",
        "caching",
    )

    def optimize(
        self,
        metrics: Mapping[str, Any] | None = None,
        *,
        recommendations: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        data = dict(metrics or {})
        supplied = recommendations or {}
        proposals = []
        for domain in self.DOMAINS:
            value = data.get(domain, {})
            if isinstance(value, Mapping):
                latency = value.get("latency_seconds", value.get("latency"))
                error_rate = value.get("error_rate", 0.0)
                hit_ratio = value.get("hit_ratio")
            else:
                latency = value if isinstance(value, (int, float)) else None
                error_rate = 0.0
                hit_ratio = None

            actions = supplied.get(domain, [])
            if isinstance(actions, str):
                actions = [actions]
            if actions:
                rationale = "; ".join(sorted(str(action) for action in actions))
            elif domain == "caching" and isinstance(hit_ratio, (int, float)) and hit_ratio < 0.5:
                rationale = "Review cache keys and invalidation boundaries to improve the observed hit ratio."
            elif isinstance(error_rate, (int, float)) and error_rate > 0:
                rationale = "Reduce the observed failure rate with targeted validation and recovery tests."
            elif isinstance(latency, (int, float)) and latency > 1.0:
                rationale = f"Profile the {domain} path and remove measured latency bottlenecks."
            else:
                rationale = "Collect stage-specific telemetry before proposing a behavior-preserving change."
            proposals.append({
                "domain": domain,
                "action": rationale,
                "evidence": {
                    key: data[domain].get(key)
                    for key in ("latency_seconds", "latency", "error_rate", "hit_ratio")
                    if isinstance(data.get(domain), Mapping) and key in data[domain]
                },
                "changes_external_behavior": False,
                "requires_experiment": True,
            })
        return {"proposals": proposals, "behavior_changed": False}

core/software_knowledge_graph.py.content:
"""Deterministic graph of code structure and engineering evolution artifacts."""

from __future__ import annotations

import json
from copy import deepcopy
from collections import deque
from pathlib import Path
from typing import Any, Iterable

from core.symbol_graph import SymbolGraph


class SoftwareKnowledgeGraph:
    """Stores typed software entities with stable, deterministic traversal."""

    def __init__(self) -> None:
        self._nodes: dict[str, dict[str, Any]] = {}
        self._edges: set[tuple[str, str, str]] = set()

    def add_node(
        self,
        node_type: str,
        node_id: str,
        name: str,
        attributes: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        if not node_type.strip() or not node_id.strip():
            raise ValueError("node_type and node_id must be non-empty.")
        node = {
            "id": node_id,
            "type": node_type,
            "name": name,
            "attributes": deepcopy(attributes or {}),
        }
        self._nodes[node_id] = node
        return deepcopy(node)

    def add_edge(self, source_id: str, target_id: str, relation: str) -> None:
        if source_id not in self._nodes or target_id not in self._nodes:
            raise KeyError(f"Both edge endpoints must exist: {source_id!r} -> {target_id!r}.")
        if not relation.strip():
            raise ValueError("relation must be non-empty.")
        self._edges.add((source_id, target_id, relation))

    def add_repository(
        self,
        symbol_graph: SymbolGraph,
        *,
        architectures: Iterable[dict[str, Any]] = (),
        patterns: Iterable[dict[str, Any]] = (),
    ) -> None:
        modules = sorted(symbol_graph.files)
        for path in modules:
            self.add_node("module", f"module:{path}", path, {"path": path})
        for symbol in sorted(symbol_graph.symbols.values(), key=lambda item: item.id):
            module_id = f"module:{symbol.file}"
            self.add_node(
                self._symbol_type(symbol.symbol_type),
                f"symbol:{symbol.id}",
                symbol.name,
                {
                    "qualified_name": symbol.qualified_name,
                    "file": symbol.file,
                    "line": symbol.line,
                },
            )
            if module_id in self._nodes:
                self.add_edge(module_id, f"symbol:{symbol.id}", "defines")
        for dependency in sorted(
            symbol_graph.dependencies,
            key=lambda item: (item.source_file, item.target_file, item.dependency_type),
        ):
            source_id = f"module:{dependency.source_file}"
            target_id = f"module:{dependency.target_file}"
            if source_id in self._nodes and target_id in self._nodes:
                self.add_edge(source_id, target_id, "depends_on")
        for architecture in sorted(architectures, key=lambda item: str(item.get("pattern_name", ""))):
            name = str(architecture.get("pattern_name", architecture.get("name", "architecture")))
            node_id = f"architecture:{name}"
            self.add_node("architecture", node_id, name, architecture)
        for pattern in sorted(patterns, key=lambda item: (str(item.get("kind", "")), str(item.get("location", "")))):
            name = str(pattern.get("kind", "pattern"))
            node_id = f"pattern:{pattern.get('location', name)}"
            self.add_node("pattern", node_id, name, pattern)

    def add_artifact(self, artifact_type: str, artifact_id: str, name: str, data: dict[str, Any]) -> None:
        self.add_node(artifact_type, f"{artifact_type}:{artifact_id}", name, data)

    def get_node(self, node_id: str) -> dict[str, Any] | None:
        node = self._nodes.get(node_id)
        return deepcopy(node) if node is not None else None

    def nodes(self, node_type: str | None = None) -> list[dict[str, Any]]:
        selected = (
            node for node in self._nodes.values()
            if node_type is None or node["type"] == node_type
        )
        return [deepcopy(node) for node in sorted(selected, key=lambda item: item["id"])]

    def edges(self) -> list[dict[str, str]]:
        return [
            {"source": source, "target": target, "relation": relation}
            for source, target, relation in sorted(self._edges)
        ]

    def neighbors(self, node_id: str, direction: str = "outgoing") -> list[str]:
        if direction not in {"outgoing", "incoming", "both"}:
            raise ValueError("direction must be 'outgoing', 'incoming', or 'both'.")
        if node_id not in self._nodes:
            return []
        neighbors = set()
        for source, target, _ in self._edges:
            if direction in {"outgoing", "both"} and source == node_id:
                neighbors.add(target)
            if direction in {"incoming", "both"} and target == node_id:
                neighbors.add(source)
        return sorted(neighbors)

    def traverse(
        self,
        start_node_id: str,
        *,
        max_depth: int = 1,
        direction: str = "outgoing",
    ) -> list[str]:
        if max_depth < 0:
            raise ValueError("max_depth must not be negative.")
        if start_node_id not in self._nodes:
            return []
        visited = {start_node_id}
        queue = deque([(start_node_id, 0)])
        while queue:
            current, depth = queue.popleft()
            if depth >= max_depth:
                continue
            for neighbor in self.neighbors(current, direction):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, depth + 1))
        visited.remove(start_node_id)
        return sorted(visited)

    def shortest_path(self, start_node_id: str, end_node_id: str) -> list[str] | None:
        if start_node_id not in self._nodes or end_node_id not in self._nodes:
            return None
        queue = deque([[start_node_id]])
        visited = {start_node_id}
        while queue:
            path = queue.popleft()
            if path[-1] == end_node_id:
                return path
            for neighbor in self.neighbors(path[-1]):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(path + [neighbor])
        return None

    def search(self, query: str, node_type: str | None = None) -> list[dict[str, Any]]:
        needle = query.casefold()
        return [
            node for node in self.nodes(node_type)
            if needle in node["name"].casefold()
            or needle in node["id"].casefold()
        ]

    def to_dict(self) -> dict[str, Any]:
        return {"nodes": self.nodes(), "edges": self.edges()}

    def export_json(self, output_path: str | Path | None = None) -> str:
        content = json.dumps(self.to_dict(), indent=2, sort_keys=True)
        if output_path is not None:
            target = Path(output_path)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(content, encoding="utf-8")
        return content

    @staticmethod
    def _symbol_type(value: str) -> str:
        normalized = str(value).casefold()
        if "class" in normalized or "interface" in normalized:
            return "class"
        if "method" in normalized:
            return "function"
        return "function"

core/task_negotiation.py.content:
"""Deterministic agent selection across capability, workload, and performance."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Optional

from core.capability_manager import AgentCapabilityManager
from core.multi_agent.agent_registry import AgentDescriptor


@dataclass(frozen=True)
class NegotiationResult:
    agent_id: Optional[str]
    score: float
    candidates: tuple[dict[str, Any], ...]
    reason: str

    def to_dict(self) -> dict[str, Any]:
        return {
            "agent_id": self.agent_id,
            "score": self.score,
            "candidates": [dict(item) for item in self.candidates],
            "reason": self.reason,
        }


class TaskNegotiationEngine:
    """Scores eligible agents with fixed weights and stable identifier tie-breaks."""

    def __init__(
        self,
        capability_manager: AgentCapabilityManager,
        metrics_tracker: Optional[Any] = None,
    ) -> None:
        self.capability_manager = capability_manager
        self.metrics_tracker = metrics_tracker

    def negotiate(
        self,
        task: Any,
        required_capabilities: Optional[list[str]] = None,
        required_languages: Optional[list[str]] = None,
        required_domains: Optional[list[str]] = None,
        estimated_runtime: Optional[float] = None,
        confidence: Optional[float] = None,
    ) -> NegotiationResult:
        skills = list(required_capabilities or self._get(task, "required_capabilities", []))
        languages = list(required_languages or self._get(task, "required_languages", []))
        domains = list(required_domains or self._get(task, "required_domains", []))
        candidates = self.capability_manager.discover(
            skills=skills,
            languages=languages,
            domains=domains,
            available_only=True,
        )
        ranked = []
        for candidate in candidates:
            descriptor: AgentDescriptor = candidate["agent"]
            profile = candidate["profile"]
            workload_capacity = max(1, descriptor.max_workload)
            workload_score = max(0.0, 1.0 - descriptor.workload / workload_capacity)
            success = profile.get("historical_accuracy", descriptor.historical_success_rate)
            reliability = profile.get("reliability", descriptor.historical_success_rate)
            runtime_score = 1.0
            if estimated_runtime and estimated_runtime > 0:
                observed = descriptor.average_duration
                runtime_score = 1.0 if observed <= 0 else min(1.0, estimated_runtime / observed)
            confidence_score = self._bounded(
                confidence if confidence is not None else 1.0, 1.0
            )
            required = {item.lower() for item in skills + languages + domains}
            provided = set(profile.get("skills", [])) | set(profile.get("languages", [])) | set(profile.get("domains", []))
            capability_score = len(required & provided) / len(required) if required else 1.0
            metric = self.metrics_tracker.get_metrics(descriptor.agent_id) if self.metrics_tracker else {}
            historical_score = self._bounded(
                metric.get("success_rate", success), 1.0
            )
            score = (
                0.30 * capability_score
                + 0.20 * historical_score
                + 0.15 * workload_score
                + 0.10 * runtime_score
                + 0.10 * confidence_score
                + 0.15 * self._bounded(reliability, 1.0)
            )
            ranked.append({
                "agent_id": descriptor.agent_id,
                "score": round(score, 6),
                "capability_score": round(capability_score, 6),
                "historical_success": round(historical_score, 6),
                "workload_score": round(workload_score, 6),
                "runtime_score": round(runtime_score, 6),
                "confidence": round(confidence_score, 6),
                "available": descriptor.is_available,
            })
        ranked.sort(key=lambda item: (-item["score"], item["agent_id"]))
        if not ranked:
            return NegotiationResult(None, 0.0, (), "No available agent satisfies the requested capabilities.")
        winner = ranked[0]
        return NegotiationResult(
            winner["agent_id"],
            winner["score"],
            tuple(ranked),
            "Selected the highest-scoring available agent; ties use ascending agent ID.",
        )

    @staticmethod
    def _get(task: Any, name: str, default: Any = None) -> Any:
        return task.get(name, default) if isinstance(task, dict) else getattr(task, name, default)

    @staticmethod
    def _bounded(value: Any, maximum: float) -> float:
        try:
            number = float(value)
        except (TypeError, ValueError):
            return 0.0
        return max(0.0, min(maximum, number))

core/team_builder.py.content:
"""Capability-based engineering team formation using the v3.8 agent runtime."""

from __future__ import annotations

from typing import Any, Optional

from core.organization_manager import OrganizationManager


class TeamBuilder:
    """Forms stable teams from registered agent skills, reliability, and workload."""

    ROLE_SKILLS = {
        "Architect": {"architecture", "design"},
        "Planner": {"planning", "implementation"},
        "Backend": {"backend", "implementation", "python"},
        "Frontend": {"frontend", "ui", "javascript", "typescript"},
        "AI Engineer": {"ai", "machine-learning", "llm"},
        "QA": {"testing", "pytest", "qa"},
        "DevOps": {"devops", "infrastructure", "deployment"},
        "Security": {"security"},
        "Documentation": {"documentation", "docs"},
        "Reviewer": {"review", "code-review"},
    }

    def __init__(
        self,
        organization_manager: OrganizationManager,
        runtime: Optional[Any] = None,
        metrics_tracker: Optional[Any] = None,
    ) -> None:
        self.organization_manager = organization_manager
        self.runtime = runtime or organization_manager.runtime
        self.metrics_tracker = metrics_tracker

    def build_team(
        self,
        project_name: str,
        technology_stack: Optional[list[str]] = None,
        project_size: str = "medium",
        required_roles: Optional[list[str]] = None,
    ) -> dict[str, Any]:
        stack = sorted({value.lower() for value in technology_stack or []})
        roles = list(required_roles or self._roles_for(stack, project_size))
        team = self.organization_manager.create_team(
            name=f"{project_name} Engineering",
            capabilities=roles + stack,
        )
        agents = self.runtime.discover(available_only=False) if self.runtime is not None else []
        assigned: set[str] = set()
        assignments: dict[str, str] = {}
        for role in roles:
            candidates = [
                agent for agent in agents
                if agent.agent_id not in assigned and self._matches(agent, role)
            ]
            candidates.sort(key=lambda agent: self._score(agent))
            if candidates:
                agent = candidates[0]
                self.organization_manager.assign_agent(team.team_id, agent.agent_id, role)
                assigned.add(agent.agent_id)
                assignments[role] = agent.agent_id
        result = self.organization_manager.team_status(team.team_id) or team.to_dict()
        result["role_assignments"] = assignments
        result["technology_stack"] = stack
        return result

    def recommend_agents(self, role: str, limit: int = 5) -> list[dict[str, Any]]:
        if limit < 0:
            raise ValueError("limit must not be negative.")
        agents = self.runtime.discover(available_only=False) if self.runtime is not None else []
        matches = [agent for agent in agents if self._matches(agent, role)]
        return [
            {
                "agent_id": agent.agent_id,
                "role": agent.role.value,
                "score": self._reliability(agent),
                "workload": agent.workload,
            }
            for agent in sorted(matches, key=self._score)[:limit]
        ]

    def _matches(self, agent: Any, role: str) -> bool:
        required = self.ROLE_SKILLS.get(role, {role.lower()})
        capabilities = {value.lower() for value in getattr(agent, "capabilities", [])}
        agent_role = str(getattr(agent, "role", "")).lower()
        return bool(required & capabilities) or role.lower() in agent_role

    def _score(self, agent: Any) -> tuple[int, float, int, int, str]:
        status = getattr(getattr(agent, "status", None), "value", getattr(agent, "status", ""))
        unavailable = status in {"OFFLINE", "FAILED"} or agent.workload >= agent.max_workload
        return (
            int(unavailable),
            -self._reliability(agent),
            int(agent.workload),
            -int(agent.priority),
            str(agent.agent_id),
        )

    def _reliability(self, agent: Any) -> float:
        if self.metrics_tracker is not None:
            metrics = self.metrics_tracker.get_metrics(agent.agent_id)
            if metrics.get("task_count", 0):
                return float(metrics.get("success_rate", 0.0))
        return float(agent.historical_success_rate)

    @classmethod
    def _roles_for(cls, stack: list[str], project_size: str) -> list[str]:
        roles = ["Architect", "Backend", "QA", "Reviewer"]
        if any(item in stack for item in ("javascript", "typescript", "react", "frontend")):
            roles.append("Frontend")
        if any(item in stack for item in ("ai", "ml", "machine-learning", "llm")):
            roles.append("AI Engineer")
        if project_size.lower() in {"large", "enterprise"}:
            roles.extend(["Security", "DevOps", "Documentation"])
        return roles

core/terminal_gateway.py.content:
"""
AutoDev Terminal Gateway (Phase 5 - Secure Interactive Debugging)
WebSocket/JSON streaming gateway bridging browser dashboard terminals
with authorized interactive debugging sessions.
"""

from dataclasses import dataclass
from datetime import datetime, timezone
import json
from typing import Dict, Optional, Any, Callable
import logging

from core.interactive_session_manager import (
    InteractiveSessionManager,
    InteractiveDebugSession,
    DebugSessionStatus,
)
from core.terminal_authorization import (
    TerminalSecurityError,
    UnauthorizedSessionError,
    HostExecutionProhibitedError,
)

logger = logging.getLogger(__name__)


class TerminalGateway:
    """
    Message router and protocol handler for interactive WebSocket terminal sessions.
    """

    def __init__(
        self,
        session_manager: Optional[InteractiveSessionManager] = None,
        auth_token_validator: Optional[Callable[[str], bool]] = None,
    ) -> None:
        self.session_manager = session_manager or InteractiveSessionManager()
        self.auth_token_validator = auth_token_validator or (lambda token: bool(token and token.strip()))

    def handle_client_message(self, raw_message: str, auth_token: Optional[str] = None) -> Dict[str, Any]:
        """
        Process a single JSON message frame from client terminal.
        """
        # Validate auth token if provided
        if auth_token and not self.auth_token_validator(auth_token):
            return {"type": "error", "message": "Invalid or expired authentication token"}

        try:
            payload = json.loads(raw_message)
        except Exception as e:
            return {"type": "error", "message": f"Malformed JSON frame: {e}"}

        action = payload.get("action", "")

        try:
            if action == "create":
                principal_id = payload.get("principal_id", "anonymous")
                transaction_id = payload.get("transaction_id", "")
                sandbox_id = payload.get("sandbox_id", "")
                worker_id = payload.get("worker_id")
                is_coordinator_host = payload.get("is_coordinator_host", False)

                session = self.session_manager.create_session(
                    principal_id=principal_id,
                    transaction_id=transaction_id,
                    sandbox_id=sandbox_id,
                    worker_id=worker_id,
                    is_coordinator_host=is_coordinator_host,
                )
                return {
                    "type": "created",
                    "session_id": session.session_id,
                    "transaction_id": session.transaction_id,
                    "sandbox_id": session.sandbox_id,
                    "remaining_seconds": session.remaining_seconds,
                    "status": session.status.value,
                }

            elif action == "input":
                session_id = payload.get("session_id", "")
                data = payload.get("data", "")
                success = self.session_manager.write_input(session_id, data)
                if not success:
                    return {"type": "error", "session_id": session_id, "message": "Failed to write input to session"}
                return {"type": "input_ack", "session_id": session_id}

            elif action == "read":
                session_id = payload.get("session_id", "")
                timeout_ms = payload.get("timeout_ms", 100)
                output = self.session_manager.read_output(session_id, timeout_ms=timeout_ms)
                session = self.session_manager.get_session(session_id)
                status = session.status.value if session else "terminated"
                return {
                    "type": "output",
                    "session_id": session_id,
                    "data": output,
                    "status": status,
                    "remaining_seconds": session.remaining_seconds if session else 0.0,
                }

            elif action == "resize":
                session_id = payload.get("session_id", "")
                cols = int(payload.get("cols", 80))
                rows = int(payload.get("rows", 24))
                success = self.session_manager.resize_session(session_id, cols, rows)
                return {"type": "resize_ack", "session_id": session_id, "success": success}

            elif action == "terminate":
                session_id = payload.get("session_id", "")
                success = self.session_manager.terminate_session(session_id)
                return {"type": "terminated", "session_id": session_id, "success": success}

            elif action == "status":
                session_id = payload.get("session_id", "")
                session = self.session_manager.get_session(session_id)
                if not session:
                    return {"type": "status", "session_id": session_id, "status": "not_found"}
                return {
                    "type": "status",
                    "session_id": session_id,
                    "status": session.status.value,
                    "remaining_seconds": session.remaining_seconds,
                    "idle_seconds": session.idle_seconds,
                }

            else:
                return {"type": "error", "message": f"Unknown terminal action: {action}"}

        except TerminalSecurityError as tse:
            return {"type": "security_violation", "message": str(tse)}
        except Exception as ex:
            logger.exception("Unexpected error handling terminal gateway message: %s", ex)
            return {"type": "error", "message": f"Internal gateway error: {ex}"}

core/terminal_transport.py.content:
"""
AutoDev Version 2.5 - Terminal Transport Abstraction & Capabilities.

Defines the pluggable transport layer for interactive remote debugging sessions,
supporting both WebRTC low-latency data channels and resilient WebSocket fallback.
"""

from __future__ import annotations

import abc
import time
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional


@dataclass
class TerminalTransportCapabilities:
    """Declared capabilities of a terminal transport implementation."""
    transport_name: str  # 'webrtc', 'websocket'
    supports_binary_stream: bool = True
    supports_backpressure: bool = True
    is_peer_to_peer: bool = False
    typical_latency_ms: float = 10.0


@dataclass
class TerminalConnectionMetrics:
    """Real-time observability metrics for an active terminal streaming connection."""
    session_id: str
    transport_type: str
    connection_state: str  # 'connecting', 'connected', 'degraded', 'closed', 'failed'
    bytes_sent: int = 0
    bytes_received: int = 0
    messages_sent: int = 0
    messages_received: int = 0
    dropped_messages: int = 0
    round_trip_latency_ms: float = 0.0
    reconnect_attempts: int = 0
    connected_at: float = field(default_factory=time.time)
    last_activity_at: float = field(default_factory=time.time)


class TerminalTransport(abc.ABC):
    """Abstract base class for terminal I/O transports."""

    @abc.abstractmethod
    def get_capabilities(self) -> TerminalTransportCapabilities:
        """Return the transport capabilities."""
        pass

    @abc.abstractmethod
    def send_input(self, data: str) -> None:
        """Send user keystrokes / terminal input to the remote PTY."""
        pass

    @abc.abstractmethod
    def send_output(self, data: str) -> None:
        """Send PTY output stream to the attached client."""
        pass

    @abc.abstractmethod
    def send_resize(self, cols: int, rows: int) -> None:
        """Send terminal window resize event (SIGWINCH)."""
        pass

    @abc.abstractmethod
    def on_input(self, callback: Callable[[str], None]) -> None:
        """Register callback for received user input."""
        pass

    @abc.abstractmethod
    def on_output(self, callback: Callable[[str], None]) -> None:
        """Register callback for terminal output stream."""
        pass

    @abc.abstractmethod
    def get_metrics(self) -> TerminalConnectionMetrics:
        """Retrieve connection metrics."""
        pass

    @abc.abstractmethod
    def close(self, reason: str = "") -> None:
        """Gracefully terminate transport session."""
        pass


class WebSocketTerminalTransport(TerminalTransport):
    """
    Standard WebSocket/HTTP bidirectional transport for terminal streaming.
    Default resilient fallback across all browser and proxy environments.
    """

    def __init__(self, session_id: str):
        self.session_id = session_id
        self._metrics = TerminalConnectionMetrics(
            session_id=session_id,
            transport_type="websocket",
            connection_state="connected",
        )
        self._input_callbacks: List[Callable[[str], None]] = []
        self._output_callbacks: List[Callable[[str], None]] = []
        self._is_closed = False

    def get_capabilities(self) -> TerminalTransportCapabilities:
        return TerminalTransportCapabilities(
            transport_name="websocket",
            supports_binary_stream=True,
            supports_backpressure=True,
            is_peer_to_peer=False,
            typical_latency_ms=25.0,
        )

    def send_input(self, data: str) -> None:
        if self._is_closed:
            return
        self._metrics.bytes_received += len(data.encode())
        self._metrics.messages_received += 1
        self._metrics.last_activity_at = time.time()
        for cb in self._input_callbacks:
            cb(data)

    def send_output(self, data: str) -> None:
        if self._is_closed:
            return
        self._metrics.bytes_sent += len(data.encode())
        self._metrics.messages_sent += 1
        self._metrics.last_activity_at = time.time()
        for cb in self._output_callbacks:
            cb(data)

    def send_resize(self, cols: int, rows: int) -> None:
        self._metrics.last_activity_at = time.time()

    def on_input(self, callback: Callable[[str], None]) -> None:
        self._input_callbacks.append(callback)

    def on_output(self, callback: Callable[[str], None]) -> None:
        self._output_callbacks.append(callback)

    def get_metrics(self) -> TerminalConnectionMetrics:
        return self._metrics

    def close(self, reason: str = "") -> None:
        self._is_closed = True
        self._metrics.connection_state = "closed"

core/test_selector.py.content:
"""Deterministic impact-based test selection with safe full-suite fallback."""

from __future__ import annotations

import ast
import logging
import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Iterable, Optional

from core.change_detector import RepositoryChangeDetector

logger = logging.getLogger("AutoDev.TestSelector")


@dataclass
class TestSelection:
    """Selected tests and the deterministic reason for the chosen validation scope."""

    tests: list[str] = field(default_factory=list)
    fallback_to_full_suite: bool = False
    reason: str = ""
    confidence: Optional[float] = None


class TestSelector:
    """Selects a minimal test subset and escalates when impact confidence is low."""

    __test__ = False
    CONFIDENCE_THRESHOLD = 0.60

    def __init__(
        self,
        project_root: str | Path,
        impact_analyzer: Optional[Any] = None,
        confidence_threshold: float = CONFIDENCE_THRESHOLD,
        change_detector: Optional[RepositoryChangeDetector] = None,
    ) -> None:
        self.project_root = Path(project_root).resolve()
        self.impact_analyzer = impact_analyzer
        self.confidence_threshold = confidence_threshold
        self.change_detector = change_detector or RepositoryChangeDetector(self.project_root)
        self.all_tests = self._discover_tests()
        self.last_selection = TestSelection()

    def refresh_tests(self) -> list[str]:
        """Refreshes discovery so newly generated test files are selectable."""
        self.all_tests = self._discover_tests()
        return list(self.all_tests)

    def select_tests(
        self,
        changed_files: Iterable[str],
        affected_symbols: Optional[Iterable[str]] = None,
        impact_report: Optional[Any] = None,
    ) -> list[str]:
        """Returns the minimal deterministic list of tests for the supplied changes."""
        normalized = sorted({self._relative(path) for path in changed_files})
        if not normalized:
            self.last_selection = TestSelection(reason="No changed files.")
            return []

        reports = [impact_report] if impact_report is not None else []
        if not reports and self.impact_analyzer is not None:
            for path in normalized:
                if not RepositoryChangeDetector._is_test_file(path) and not self._is_documentation(path):
                    reports.append(self.impact_analyzer.analyze_file(path))

        confidence_values = [
            float(getattr(report, "confidence", 0.0))
            for report in reports
            if getattr(report, "confidence", None) is not None
        ]
        confidence = min(confidence_values) if confidence_values else None
        if confidence is not None and confidence < self.confidence_threshold:
            return self._select_full_suite(
                f"Impact confidence {confidence:.2f} is below the {self.confidence_threshold:.2f} threshold.",
                confidence,
            )

        changed_tests = {
            path for path in normalized
            if RepositoryChangeDetector._is_test_file(path) and path in self.all_tests
        }
        changed_code = [
            path for path in normalized
            if not self._is_documentation(path)
            and not RepositoryChangeDetector._is_test_file(path)
        ]
        if not changed_code:
            selected = sorted(changed_tests)
            self.last_selection = TestSelection(
                tests=selected,
                reason="Only test files or documentation changed.",
                confidence=confidence,
            )
            return selected

        selected = set(changed_tests)
        for report in reports:
            selected.update(
                test_path
                for test_path in getattr(report, "affected_tests", [])
                if test_path in self.all_tests
            )

        stems = {Path(path).stem.lower() for path in changed_code}
        symbols = {symbol.lower() for symbol in (affected_symbols or [])}
        parser_change = any("parser" in path.lower() or "parse" in path.lower() for path in changed_code)
        orchestrator_change = any("orchestrator" in path.lower() for path in changed_code)
        utility_change = any(
            "util" in Path(path).stem.lower()
            or Path(path).stem.lower() in {"helpers", "common"}
            for path in changed_code
        )

        for test_path in self.all_tests:
            test_name = Path(test_path).stem.lower()
            if any(f"test_{stem}" in test_name or f"{stem}_test" in test_name for stem in stems):
                selected.add(test_path)
            if parser_change and any(token in test_name for token in ("parser", "parse")):
                selected.add(test_path)
            if orchestrator_change and (
                "orchestrat" in test_name or "integration" in test_name or "scenario" in test_name
            ):
                selected.add(test_path)
            if utility_change and any(token in test_name for token in ("util", "helper", "common")):
                selected.add(test_path)
            if symbols and self._test_references_symbols(test_path, symbols):
                selected.add(test_path)

        for path in changed_code:
            if path.startswith("core/"):
                module_path = Path(path).with_suffix("").as_posix().replace("/", ".")
                module_name = Path(path).stem
                for test_path in self.all_tests:
                    if self._test_imports_module(test_path, module_path, module_name):
                        selected.add(test_path)

        if selected:
            result = sorted(selected)
            self.last_selection = TestSelection(
                tests=result,
                reason="Selected tests matching changed modules, imports, and impact results.",
                confidence=confidence,
            )
            return result

        if confidence is None or confidence < self.confidence_threshold:
            return self._select_full_suite(
                "No reliable dependency mapping was found for changed source files.",
                confidence,
            )

        return self._select_full_suite(
            "No matching tests were found; running the full suite is safer.",
            confidence,
        )

    def select(self, *args: Any, **kwargs: Any) -> TestSelection:
        """Returns selection details while keeping :meth:`select_tests` list-shaped."""
        self.select_tests(*args, **kwargs)
        return self.last_selection

    def _select_full_suite(self, reason: str, confidence: Optional[float]) -> list[str]:
        selected = list(self.all_tests)
        self.last_selection = TestSelection(
            tests=selected,
            fallback_to_full_suite=True,
            reason=reason,
            confidence=confidence,
        )
        logger.info("%s Selected %d tests.", reason, len(selected))
        return selected

    def _discover_tests(self) -> list[str]:
        tests: list[str] = []
        tests_dir = self.project_root / "tests"
        if not tests_dir.is_dir():
            return tests
        for current_root, directories, files in os.walk(tests_dir):
            directories[:] = sorted(d for d in directories if not d.startswith("."))
            for file_name in sorted(files):
                if file_name.startswith("test_") and file_name.endswith(".py"):
                    tests.append(
                        (Path(current_root) / file_name)
                        .relative_to(self.project_root)
                        .as_posix()
                    )
                elif file_name.endswith("_test.py"):
                    tests.append(
                        (Path(current_root) / file_name)
                        .relative_to(self.project_root)
                        .as_posix()
                    )
        return sorted(set(tests))

    def _test_imports_module(
        self,
        test_path: str,
        module_path: str,
        module_name: str,
    ) -> bool:
        file_path = self.project_root / test_path
        try:
            tree = ast.parse(file_path.read_text(encoding="utf-8"), filename=str(file_path))
        except (OSError, SyntaxError, UnicodeError):
            return False
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                if any(
                    alias.name == module_path or module_name in alias.name.split(".")
                    for alias in node.names
                ):
                    return True
            elif isinstance(node, ast.ImportFrom):
                if node.module and (
                    node.module == module_path or module_name in node.module.split(".")
                ):
                    return True
        return False

    def _test_references_symbols(self, test_path: str, symbols: set[str]) -> bool:
        try:
            content = (self.project_root / test_path).read_text(
                encoding="utf-8",
                errors="replace",
            ).lower()
        except OSError as err:
            logger.warning("Could not inspect test file %s: %s", test_path, err)
            return False
        return any(symbol and symbol in content for symbol in symbols)

    def _relative(self, path: str) -> str:
        file_path = Path(path)
        if file_path.is_absolute():
            try:
                file_path = file_path.resolve().relative_to(self.project_root)
            except ValueError:
                return file_path.as_posix()
        return file_path.as_posix().replace("\\", "/")

    def _is_documentation(self, path: str) -> bool:
        return self.change_detector._is_documentation_file(path)

core/worker_auth.py.content:
"""
worker_auth.py - Remote Worker Authentication & Authorization Policy Engine for AutoDev (v2.3)

Enforces zero-trust worker identity validation, mTLS certificate-to-worker binding,
capability authorization, and path/runtime privilege restrictions.
"""

from __future__ import annotations

from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
import logging
from typing import Any, Dict, List, Optional, Set, Tuple

logger = logging.getLogger("AutoDev.WorkerAuth")


class WorkerAuthorizationError(Exception):
    """Raised when an authenticated worker attempts an unauthorized operation."""
    pass


class WorkerAuthenticationError(Exception):
    """Raised when worker identity or mTLS verification fails."""
    pass


@dataclass
class WorkerSecurityScope:
    """Security boundaries and execution permissions granted to a worker."""
    worker_id: Optional[str] = None
    allowed_operation_types: Set[str] = field(
        default_factory=lambda: {"CREATE_FILE", "MODIFY_FILE", "DELETE_FILE", "EXECUTE_TEST", "RUN_TESTS"}
    )
    allowed_runtimes: Set[str] = field(default_factory=lambda: {"process", "container"})
    allowed_security_profiles: Set[str] = field(default_factory=lambda: {"restricted", "development"})
    allowed_runtime_profiles: Optional[Set[str]] = None
    max_concurrency: int = 4
    allow_network_access: bool = False
    max_submitted_artifacts: int = 100
    allowed_path_prefixes: Set[str] = field(default_factory=set)
    denied_path_prefixes: List[str] = field(
        default_factory=lambda: [".git", ".env", "memory/execution_journal", "certs", "secrets"]
    )

    def __post_init__(self) -> None:
        if self.allowed_runtime_profiles is not None and not self.allowed_security_profiles:
            self.allowed_security_profiles = set(self.allowed_runtime_profiles)
        elif self.allowed_runtime_profiles is not None:
            self.allowed_security_profiles = set(self.allowed_runtime_profiles)
        if isinstance(self.allowed_path_prefixes, list):
            self.allowed_path_prefixes = set(self.allowed_path_prefixes)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "worker_id": self.worker_id,
            "allowed_operation_types": sorted(list(self.allowed_operation_types)),
            "allowed_runtimes": sorted(list(self.allowed_runtimes)),
            "allowed_security_profiles": sorted(list(self.allowed_security_profiles)),
            "max_concurrency": self.max_concurrency,
            "allow_network_access": self.allow_network_access,
            "max_submitted_artifacts": self.max_submitted_artifacts,
            "allowed_path_prefixes": sorted(list(self.allowed_path_prefixes)),
            "denied_path_prefixes": self.denied_path_prefixes,
        }


@dataclass
class AuthenticatedWorkerIdentity:
    """Verified identity and granted security scope of a remote worker."""
    worker_id: str
    common_name: str = ""
    certificate_fingerprint: str = ""
    cert_fingerprint: str = ""
    organization: str = ""
    authenticated_via: str = "mTLS"  # mTLS | TOKEN | LOCAL
    scope: Optional[WorkerSecurityScope] = None
    authenticated_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())

    def __post_init__(self) -> None:
        if not self.common_name:
            self.common_name = self.worker_id
        if self.cert_fingerprint and not self.certificate_fingerprint:
            self.certificate_fingerprint = self.cert_fingerprint
        elif self.certificate_fingerprint and not self.cert_fingerprint:
            self.cert_fingerprint = self.certificate_fingerprint

    @property
    def is_authenticated(self) -> bool:
        return bool(self.worker_id and self.worker_id.strip())

    def to_dict(self) -> Dict[str, Any]:
        return {
            "worker_id": self.worker_id,
            "common_name": self.common_name,
            "certificate_fingerprint": self.certificate_fingerprint,
            "organization": self.organization,
            "authenticated_via": self.authenticated_via,
            "scope": self.scope.to_dict() if self.scope else None,
            "authenticated_at": self.authenticated_at,
        }


class WorkerAuthorizer:
    """
    Validates that a worker is authorized to register and execute requested operations.
    """

    def __init__(
        self,
        default_scope: Optional[WorkerSecurityScope] = None,
        scopes: Optional[Dict[str, WorkerSecurityScope]] = None,
        worker_scopes: Optional[Dict[str, WorkerSecurityScope]] = None,
        require_explicit_scope: bool = False,
    ) -> None:
        self.default_scope = default_scope or WorkerSecurityScope()
        self.worker_scopes = scopes or worker_scopes or {}
        self.require_explicit_scope = require_explicit_scope
        self._submitted_artifact_counts: Dict[str, int] = {}

    def get_scope_for_worker(self, worker_id: str) -> WorkerSecurityScope:
        """Returns specific scope configured for worker or falls back to default."""
        if worker_id in self.worker_scopes:
            return self.worker_scopes[worker_id]
        if self.require_explicit_scope:
            raise WorkerAuthorizationError(f"No authorization scope configured for worker '{worker_id}'")
        return self.default_scope

    def authorize_registration(self, identity: AuthenticatedWorkerIdentity) -> bool:
        """Validates worker identity for registration."""
        if not identity.is_authenticated:
            raise WorkerAuthorizationError("Unauthenticated identity: worker_id is missing or empty.")
        if self.require_explicit_scope and identity.worker_id not in self.worker_scopes:
            raise WorkerAuthorizationError(f"No authorization scope configured for worker '{identity.worker_id}'")
        return True

    def authorize_operation(
        self,
        identity: AuthenticatedWorkerIdentity,
        operation_type: str,
        target_file: Optional[str] = None,
        security_profile: str = "restricted",
    ) -> bool:
        """
        Validates task assignment against worker scope.
        Raises WorkerAuthorizationError if unauthorized.
        """
        if not identity.is_authenticated:
            raise WorkerAuthorizationError("Unauthenticated worker identity.")

        scope = identity.scope or self.get_scope_for_worker(identity.worker_id)

        # 1. Operation type authorization
        if operation_type not in scope.allowed_operation_types:
            raise WorkerAuthorizationError(
                f"Operation type '{operation_type}' not permitted for worker '{identity.worker_id}'. "
                f"Allowed: {sorted(list(scope.allowed_operation_types))}"
            )

        # 2. Security profile authorization
        if security_profile not in scope.allowed_security_profiles:
            raise WorkerAuthorizationError(
                f"Runtime profile '{security_profile}' not permitted for worker '{identity.worker_id}'."
            )

        # 3. Target file path authorization & traversal checks
        if target_file:
            raw_path = str(target_file)
            if ".." in raw_path or raw_path.startswith("/") or (len(raw_path) > 1 and raw_path[1] == ":"):
                raise WorkerAuthorizationError(
                    f"Path traversal or absolute path '{target_file}' is forbidden."
                )

            norm_path = raw_path.replace("\\", "/").lstrip("/")
            # Check denied prefixes
            for denied in scope.denied_path_prefixes:
                denied_norm = denied.replace("\\", "/").lstrip("/")
                if norm_path == denied_norm or norm_path.startswith(denied_norm + "/") or norm_path.startswith(denied_norm + "."):
                    raise WorkerAuthorizationError(
                        f"Worker '{identity.worker_id}' is forbidden from mutating protected path '{target_file}'."
                    )
            # Check allowed prefixes if specified
            if scope.allowed_path_prefixes:
                is_allowed = False
                for a in scope.allowed_path_prefixes:
                    clean_a = a.replace("\\", "/").strip("/")
                    if norm_path == clean_a or norm_path.startswith(clean_a + "/"):
                        is_allowed = True
                        break
                if not is_allowed:
                    raise WorkerAuthorizationError(
                        f"Target path '{target_file}' outside allowed prefixes: {sorted(list(scope.allowed_path_prefixes))}"
                    )

        return True

    def authorize_artifact_submission(self, identity: AuthenticatedWorkerIdentity, artifact_id: str) -> bool:
        """Validates artifact submission against worker's quota."""
        if not identity.is_authenticated:
            raise WorkerAuthorizationError("Unauthenticated worker identity.")
        scope = identity.scope or self.get_scope_for_worker(identity.worker_id)
        current = self._submitted_artifact_counts.get(identity.worker_id, 0)
        if current >= scope.max_submitted_artifacts:
            raise WorkerAuthorizationError(
                f"Artifact quota exceeded for worker '{identity.worker_id}' ({current}/{scope.max_submitted_artifacts})."
            )
        self._submitted_artifact_counts[identity.worker_id] = current + 1
        return True

    def authorize_task(
        self,
        identity: AuthenticatedWorkerIdentity,
        operation_type: str,
        target_file: Optional[str] = None,
        required_runtime: str = "process",
        security_profile: str = "restricted",
    ) -> None:
        """Legacy helper calling authorize_operation."""
        self.authorize_operation(identity, operation_type, target_file, security_profile)

